                <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden"><table className="w-full text-start text-sm"><thead className="bg-gray-50 text-gray-500"><tr><th className="px-4 py-3">{t.time}</th><th className="px-4 py-3">{t.user}</th><th className="px-4 py-3">{t.operation}</th><th className="px-4 py-3">{t.entity}</th><th className="px-4 py-3">{t.details}</th><th className="px-4 py-3">{t.action}</th></tr></thead><tbody className="divide-y divide-gray-100">{systemLogs.map(log => (<tr key={log.id} className="hover:bg-gray-50"><td className="px-4 py-3 text-gray-500 dir-ltr text-right">{new Date(log.timestamp).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</td><td className="px-4 py-3 font-bold text-gray-700">{log.actorName}</td><td className="px-4 py-3"><span className={`px-2 py-1 rounded text-xs font-bold ${log.actionType === 'DELETE' ? 'bg-red-100 text-red-700' : (log.actionType === 'CREATE' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700')}`}>{log.actionType}</span></td><td className="px-4 py-3">{log.entity}</td><td className="px-4 py-3 text-gray-600 truncate max-w-xs" title={log.details}>{log.details}</td><td className="px-4 py-3">{log.actionType === 'DELETE' && log.backupData && (<button onClick={() => handleRestore(log)} className="text-blue-600 hover:bg-blue-50 px-2 py-1 rounded flex items-center gap-1 font-bold text-xs"><IconRefreshCw className="w-3 h-3" /> {t.restore}</button>)}</td></tr>))}</tbody></table>{systemLogs.length === 0 && <div className="p-8 text-center text-gray-400">{t.noLogs}</div>}</div>
            </div>
        )}
        {activeTab === 'financial' && (isAdmin || isMaster) && renderFinancialReport()}
      </div>

      {selectedTicket && renderTicketModal()}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, FormField, FormFieldType, InvoiceTemplate, CustomForm, Personnel, FeaturedBusiness } from '../types';
import { IconSettings, IconPlus, IconTrash, IconEdit, IconCheck, IconLayout, IconInvoice, IconUpload, IconDatabase, IconShield, IconBulb, IconMagic, IconClipboard, IconFolder, IconBriefcase, IconStar, IconLink, IconCopy } from './Icons';
import { compressImage, backupSystemData, clearSystemData, saveCustomFormToCloud, deleteCustomFormFromCloud, subscribeToCustomForms, updateCustomFormInCloud, firebaseConfig, subscribeToSettings } from '../services/firebaseService';
import { generateFormFields } from '../services/geminiService';

interface Props {
  config: AppConfig;
  onUpdate: (newConfig: AppConfig) => void;
  isMaster?: boolean;
}

export const SettingsManager: React.FC<Props> = ({ config, onUpdate, isMaster = false }) => {
  const [activeTab, setActiveTab] = useState<'general' | 'form' | 'custom_forms' | 'invoice' | 'maintenance' | 'daily' | 'businesses' | 'google_forms'>('general');
  const [editingFieldId, setEditingFieldId] = useState<string | null>(null);
  const [customForms, setCustomForms] = useState<CustomForm[]>([]);
  const [services, setServices] = useState<any[]>([]);

  // Local state for general settings
  const [generalData, setGeneralData] = useState({
    appTitle: config.appTitle,
    appTitleEn: config.appTitleEn,
    appSubtitle: config.appSubtitle,
    appSubtitleEn: config.appSubtitleEn,
    landingHeroTitle: config.landingHeroTitle || '',
    landingHeroSubtitle: config.landingHeroSubtitle || '',
    footerText: config.footerText || ''
  });

  // Local state for invoice template
  const [invoiceTemplate, setInvoiceTemplate] = useState<InvoiceTemplate>(config.invoiceTemplate || {
      companyName: config.appTitle,
      address: '',
      phone: '',
      footerText: 'سپاس از انتخاب شما',
      termsConditions: 'پرداخت فاکتور به منزله تایید نهایی خدمات است.',
      defaultTaxRate: 0,
      colorTheme: '#4f46e5' // Default indigo
  });

  // Local State for Daily Tips
  const [dailyTips, setDailyTips] = useState<string[]>(config.dailyTips || []);
  const [showDailyTips, setShowDailyTips] = useState<boolean>(config.showDailyTips || false);
  const [newTip, setNewTip] = useState('');

  // Local State for Featured Businesses
  const [featuredBusinesses, setFeaturedBusinesses] = useState<FeaturedBusiness[]>(config.featuredBusinesses || []);
  const [editingBiz, setEditingBiz] = useState<Partial<FeaturedBusiness> | null>(null);
  const bizImageInputRef = useRef<HTMLInputElement>(null);

  // Google Form Integration State
  const [selectedServiceForScript, setSelectedServiceForScript] = useState('');
  const [generatedScript, setGeneratedScript] = useState('');

  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [isProcessingLogo, setIsProcessingLogo] = useState(false);
  const [maintenanceStatus, setMaintenanceStatus] = useState('');
  const logoInputRef = useRef<HTMLInputElement>(null);

  // AI Form Builder State
  const [showAiModal, setShowAiModal] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [targetFormForAi, setTargetFormForAi] = useState<'main' | 'custom'>('main');

  // Custom Form State
  const [editingCustomForm, setEditingCustomForm] = useState<CustomForm | null>(null);
  const [showCustomFormList, setShowCustomFormList] = useState(true);

  // Temporary state for the field being edited/added
  const [tempField, setTempField] = useState<Partial<FormField>>({});

  // Sync local state when config prop updates
  useEffect(() => {
    setGeneralData({
      appTitle: config.appTitle,
      appTitleEn: config.appTitleEn,
      appSubtitle: config.appSubtitle,
      appSubtitleEn: config.appSubtitleEn,
      landingHeroTitle: config.landingHeroTitle || '',
      landingHeroSubtitle: config.landingHeroSubtitle || '',
      footerText: config.footerText || ''
    });
    setDailyTips(config.dailyTips || []);
    setShowDailyTips(config.showDailyTips || false);
    setFeaturedBusinesses(config.featuredBusinesses || []);
    if (config.invoiceTemplate) {
        setInvoiceTemplate(config.invoiceTemplate);
    }
  }, [config]);

  useEffect(() => {
      const unsub = subscribeToCustomForms(setCustomForms);
      const unsubServices = subscribeToSettings(() => {}, (s) => setServices(s), () => {});
      return () => { unsub(); unsubServices(); };
  }, []);

  const handleGeneralChange = (key: string, value: string) => {
    setGeneralData(prev => ({ ...prev, [key]: value }));
    setSaveSuccess(false);
  };

  const saveSettings = () => {
    setIsSaving(true);
    onUpdate({
      ...config,
      ...generalData,
      invoiceTemplate: invoiceTemplate,
      dailyTips: dailyTips,
      showDailyTips: showDailyTips,
      featuredBusinesses: featuredBusinesses
    });

    setTimeout(() => {
      setIsSaving(false);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    }, 500);
  };

  const updateConfigWithFields = (newFields: FormField[]) => {
    onUpdate({
      ...config,
      ...generalData, 
      formFields: newFields,
      invoiceTemplate: invoiceTemplate,
      dailyTips: dailyTips,
      showDailyTips: showDailyTips,
      featuredBusinesses: featuredBusinesses
    });
  };

  // Form Builder Logic
  const handleAddField = () => {
    const newField: FormField = {
      id: `field-${Date.now()}`,
      key: `custom_${Date.now()}`,
      label: 'فیلد جدید',
      type: 'text',
      required: false,
      order: editingCustomForm ? editingCustomForm.fields.length + 1 : config.formFields.length + 1,
      isSystem: false
    };
    setTempField(newField);
    setEditingFieldId(newField.id);
  };

  const handleEditField = (field: FormField) => {
    setTempField({ ...field });
    setEditingFieldId(field.id);
  };

  const handleSaveField = () => {
    if (!editingFieldId || !tempField.label) return;

    if (activeTab === 'custom_forms' && editingCustomForm) {
        let newFields = [...editingCustomForm.fields];
        const existingIndex = newFields.findIndex(f => f.id === editingFieldId);
        if (existingIndex >= 0) {
            newFields[existingIndex] = { ...newFields[existingIndex], ...tempField } as FormField;
        } else {
            newFields.push(tempField as FormField);
        }
        setEditingCustomForm({ ...editingCustomForm, fields: newFields });
    } else {
        let newFields = [...config.formFields];
        const existingIndex = newFields.findIndex(f => f.id === editingFieldId);
        if (existingIndex >= 0) {
            newFields[existingIndex] = { ...newFields[existingIndex], ...tempField } as FormField;
        } else {
            newFields.push(tempField as FormField);
        }
        updateConfigWithFields(newFields);
    }

    setEditingFieldId(null);
    setTempField({});
  };

  const handleDeleteField = (id: string) => {
    if (window.confirm('آیا از حذف این فیلد اطمینان دارید؟')) {
      if (activeTab === 'custom_forms' && editingCustomForm) {
          setEditingCustomForm({ ...editingCustomForm, fields: editingCustomForm.fields.filter(f => f.id !== id) });
      } else {
          updateConfigWithFields(config.formFields.filter(f => f.id !== id));
      }
    }
  };

  const moveField = (index: number, direction: 'up' | 'down') => {
    if (activeTab === 'custom_forms' && editingCustomForm) {
        const newFields = [...editingCustomForm.fields];
        if (direction === 'up' && index > 0) {
            [newFields[index], newFields[index - 1]] = [newFields[index - 1], newFields[index]];
        } else if (direction === 'down' && index < newFields.length - 1) {
            [newFields[index], newFields[index + 1]] = [newFields[index + 1], newFields[index]];
        }
        setEditingCustomForm({ ...editingCustomForm, fields: newFields });
    } else {
        const newFields = [...config.formFields];
        if (direction === 'up' && index > 0) {
            [newFields[index], newFields[index - 1]] = [newFields[index - 1], newFields[index]];
        } else if (direction === 'down' && index < newFields.length - 1) {
            [newFields[index], newFields[index + 1]] = [newFields[index + 1], newFields[index]];
        }
        updateConfigWithFields(newFields);
    }
  };

  // AI Generation
  const handleAiGenerate = async () => {
      if (!aiPrompt.trim()) return;
      setIsGenerating(true);
      const fields = await generateFormFields(aiPrompt);
      setIsGenerating(false);
      setShowAiModal(false);
      setAiPrompt('');

      if (fields.length > 0) {
          if (targetFormForAi === 'custom' && editingCustomForm) {
              setEditingCustomForm(prev => prev ? ({ ...prev, fields: [...prev.fields, ...fields] }) : null);
          } else {
              updateConfigWithFields([...config.formFields, ...fields]);
          }
          alert('فیلدها با موفقیت تولید و اضافه شدند.');
      } else {
          alert('خطا در تولید فیلدها. لطفا دوباره تلاش کنید.');
      }
  };

  // Google Forms Script Generation
  const generateGoogleScript = () => {
      // Map all services to a JSON object string for the script
      const serviceMap = services.reduce((acc, s) => {
          acc[s.title] = s.id; // Map Farsi title to ID
          return acc;
      }, {} as Record<string, string>);

      // Add default if no match
      const defaultServiceId = selectedServiceForScript || (services.length > 0 ? services[0].id : 'unknown');

      const script = `
/**
 * Google Apps Script for syncing Google Form responses to Firestore (Smart Name & Brand Detection)
 * 
 * Features:
 * - Generates user-friendly IDs like EXP-1234-GF.
 * - Supports Multi-Service selection (Checkboxes).
 * - Distinguishes between Customer Name and Company Name.
 * - Formats description clearly with line breaks.
 * - Creates separate ticket for each service.
 * - Initializes all required fields to prevent dashboard crashes.
 * 
 * Setup:
 * 1. Tools > Script editor
 * 2. Paste code below
 * 3. Save & Run once to authorize
 * 4. Add Trigger: onFormSubmit -> From form -> On form submit
 */

function onFormSubmit(e) {
  var form = FormApp.getActiveForm();
  var itemResponses = e.response.getItemResponses();
  var timestamp = new Date().toISOString();

  // Configuration
  var projectId = "${firebaseConfig.projectId}";
  var collection = "tickets";
  var serviceMap = ${JSON.stringify(serviceMap)};
  var defaultServiceId = "${defaultServiceId}";

  // Extract Data
  var customerName = "کاربر گوگل فرم";
  var companyName = "";
  var phoneNumber = "";
  var description = "";
  var selectedServices = []; // Array of Service IDs

  for (var i = 0; i < itemResponses.length; i++) {
    var question = itemResponses[i].getItem().getTitle();
    var answer = itemResponses[i].getResponse(); // Can be string or array
    var qLower = question.toLowerCase();

    // Detect Company/Brand (Priority detection)
    if (question.indexOf("شرکت") > -1 || question.indexOf("برند") > -1 || qLower.indexOf("company") > -1 || qLower.indexOf("brand") > -1) {
        companyName = answer;
    }
    // Detect Person Name (Only if not already identified as Company)
    else if ((question.indexOf("نام") > -1 || qLower.indexOf("name") > -1) && question.indexOf("شرکت") === -1 && question.indexOf("برند") === -1) {
        customerName = answer;
    }
    // Detect Phone
    else if (question.indexOf("تلفن") > -1 || question.indexOf("موبایل") > -1 || qLower.indexOf("phone") > -1 || qLower.indexOf("mobile") > -1) {
        phoneNumber = answer;
    }
    // Detect Service (Looking for 'service' or 'خدمت')
    else if (question.indexOf("خدمت") > -1 || question.indexOf("سرویس") > -1 || qLower.indexOf("service") > -1) {
        var answers = Array.isArray(answer) ? answer : [answer];

        for (var j = 0; j < answers.length; j++) {
            var sName = answers[j];
            var foundId = null;
            for (var key in serviceMap) {
                if (sName.indexOf(key) > -1 || key.indexOf(sName) > -1) {
                    foundId = serviceMap[key];
                    break;
                }
            }
            if (foundId) selectedServices.push(foundId);
        }
    }

    // Append to description with clear formatting
    var answerStr = Array.isArray(answer) ? answer.join(", ") : answer;
    description += "🔹 " + question + ": " + answerStr + "\\n\\n";
  }

  // Fallback if no service detected
  if (selectedServices.length === 0) {
      selectedServices.push(defaultServiceId);
  }

  // Create a Ticket for EACH selected service
  for (var k = 0; k < selectedServices.length; k++) {
      var sId = selectedServices[k];

      // Generate Friendly ID: EXP-RANDOM-GF
      var randomCode = Math.floor(1000 + Math.random() * 9000);
      var trackingId = "EXP-" + randomCode + "-GF";

      // Firestore Document Payload (REST API Format)
      var payload = {
        fields: {
          id: { stringValue: trackingId },
          status: { stringValue: "ثبت شده" },
          createdAt: { stringValue: timestamp },
          serviceId: { stringValue: sId },
          description: { stringValue: description },
          customerName: { stringValue: customerName },
          companyName: { stringValue: companyName },
          phoneNumber: { stringValue: phoneNumber },
          whatsappNumber: { stringValue: phoneNumber },
          // Empty arrays for files and subServices to prevent crashes
          files: { arrayValue: { values: [] } },
          selectedSubServices: { arrayValue: { values: [] } },
          // Proper Timeline Initialization
          timeline: {
            arrayValue: {
              values: [
                {
                  mapValue: {
                    fields: {
                      type: { stringValue: "creation" },
                      title: { stringValue: "ثبت از گوگل فرم" },
                      description: { stringValue: "درخواست توسط گوگل فرم ثبت شد." },
                      actorName: { stringValue: "Google Form" },
                      timestamp: { stringValue: timestamp },
                      visibility: { stringValue: "public" }
                    }
                  }
                }
              ]
            }
          }
        }
      };

      var url = "https://firestore.googleapis.com/v1/projects/" + projectId + "/databases/(default)/documents/" + collection + "?documentId=" + trackingId;

      var options = {
        method: "post",
        contentType: "application/json",
        payload: JSON.stringify(payload),
        muteHttpExceptions: true
      };

      try {
        var response = UrlFetchApp.fetch(url, options);
        Logger.log("Response for " + trackingId + ": " + response.getContentText());
      } catch(error) {
        Logger.log("Error sending to Firestore: " + error);
      }
  }
}
      `;
      setGeneratedScript(script.trim());
  };

  // Custom Forms Logic
  const handleCreateCustomForm = () => {
      setEditingCustomForm({
          id: `form-${Date.now()}`,
          title: 'فرم جدید',
          category: 'عمومی',
          fields: [],
          allowedRoles: [],
          createdAt: new Date().toISOString(),
          createdBy: 'Admin'
      });
      setShowCustomFormList(false);
  };

  const handleEditCustomForm = (form: CustomForm) => {
      setEditingCustomForm(form);
      setShowCustomFormList(false);
  };

  const handleSaveCustomForm = async () => {
      if (!editingCustomForm || !editingCustomForm.title) return;
      if (customForms.find(f => f.id === editingCustomForm.id)) {
          await updateCustomFormInCloud(editingCustomForm.id, editingCustomForm, 'Admin');
      } else {
          await saveCustomFormToCloud(editingCustomForm, 'Admin');
      }
      setEditingCustomForm(null);
      setShowCustomFormList(true);
  };

  const handleDeleteCustomForm = async (id: string) => {
      if (window.confirm('آیا از حذف این فرم اطمینان دارید؟')) {
          await deleteCustomFormFromCloud(id, 'Admin');
      }
  };

  const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if(!file) return;
      setIsProcessingLogo(true);
      try {
          const logoData = await compressImage(file, 500); 
          setInvoiceTemplate(prev => ({ ...prev, logoUrl: logoData }));
      } catch (e) {
          alert('خطا در بارگذاری لوگو');
      } finally {
          setIsProcessingLogo(false);
      }
  };

  const handleBackup = async () => {
      setMaintenanceStatus('در حال ایجاد فایل پشتیبان...');
      const success = await backupSystemData();
      setMaintenanceStatus(success ? 'پشتیبان‌گیری با موفقیت انجام شد (دانلود شد).' : 'خطا در پشتیبان‌گیری.');
  };

  const handleClearData = async () => {
      if (window.confirm('هـــشــــدار: آیا مطمئن هستید؟ تمام تیکت‌ها و درخواست‌های مشتریان حذف خواهند شد. این عملیات غیرقابل بازگشت است.')) {
          if (window.confirm('تایید نهایی: این کار تمام اطلاعات عملیاتی را پاک می‌کند.')) {
              setMaintenanceStatus('در حال پاک‌سازی...');
              const success = await clearSystemData();
              setMaintenanceStatus(success ? 'اطلاعات با موفقیت پاک شد.' : 'خطا در پاک‌سازی.');
          }
      }
  };

  const handleAddTip = () => {
      if(newTip.trim()) {
          setDailyTips([...dailyTips, newTip.trim()]);
          setNewTip('');
      }
  };

  const handleRemoveTip = (idx: number) => {
      setDailyTips(dailyTips.filter((_, i) => i !== idx));
  };

  // --- Featured Businesses Logic ---
  const handleEditBiz = (biz: FeaturedBusiness) => {
      setEditingBiz(biz);
  };

  const handleCreateBiz = () => {
      setEditingBiz({
          id: `biz-${Date.now()}`,
          name: '',
          description: '',
          imageUrl: '',
          websiteUrl: '',
          contactNumber: '',
          category: '',
          isGold: false
      });
  };

  const handleSaveBiz = () => {
      if (!editingBiz?.name) return;

      let newFeatured = [...featuredBusinesses];
      if (featuredBusinesses.some(b => b.id === editingBiz.id)) {
          newFeatured = newFeatured.map(b => b.id === editingBiz.id ? editingBiz as FeaturedBusiness : b);
      } else {
          newFeatured.push(editingBiz as FeaturedBusiness);
      }
      setFeaturedBusinesses(newFeatured);
      setEditingBiz(null);
  };

  const handleDeleteBiz = (id: string) => {
      if (window.confirm('حذف شود؟')) {
          setFeaturedBusinesses(prev => prev.filter(b => b.id !== id));
          if (editingBiz?.id === id) setEditingBiz(null);
      }
  };

  const handleBizImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file || !editingBiz) return;
      try {
          const imgUrl = await compressImage(file, 600, 0.7);
          setEditingBiz(prev => ({ ...prev, imageUrl: imgUrl }));
      } catch(e) { alert('خطا در آپلود عکس'); }
  };

  // Helper to render Form Builder UI (shared between Main and Custom forms)
  const renderFormBuilderUI = (fields: FormField[], isCustom: boolean) => (
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
           <div className="lg:col-span-1 space-y-4">
              {/* AI Generator Button */}
              <div className="bg-gradient-to-r from-violet-600 to-indigo-600 rounded-2xl p-6 text-white text-center shadow-lg transform hover:scale-[1.02] transition-transform cursor-pointer" onClick={() => { setTargetFormForAi(isCustom ? 'custom' : 'main'); setShowAiModal(true); }}>
                  <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center mx-auto mb-3 backdrop-blur-sm">
                      <IconMagic className="w-6 h-6 text-white" />
                  </div>
                  <h3 className="font-bold text-lg mb-1">ساخت فرم با هوش مصنوعی</h3>
                  <p className="text-xs opacity-90">توضیح دهید، ما می‌سازیم.</p>
              </div>

              {editingFieldId ? (
                 <div className="bg-white p-6 rounded-2xl border border-indigo-200 shadow-md sticky top-6">
                    <h3 className="font-bold text-gray-800 mb-4 pb-2 border-b border-gray-100">{tempField.id?.startsWith('field-') ? 'افزودن فیلد جدید' : 'ویرایش فیلد'}</h3>
                    <div className="space-y-4">
                       <div>
                          <label className="block text-xs font-bold text-gray-500 mb-1">عنوان فیلد (فارسی)</label>
                          <input 
                             className="w-full px-3 py-2 rounded-lg border border-gray-300 text-sm focus:border-indigo-500 outline-none"
                             value={tempField.label || ''}
                             onChange={(e) => setTempField({...tempField, label: e.target.value})}
                             autoFocus
                          />
                       </div>
                       <div>
                          <label className="block text-xs font-bold text-gray-500 mb-1">نوع فیلد</label>
                          <select 
                             className="w-full px-3 py-2 rounded-lg border border-gray-300 text-sm focus:border-indigo-500 outline-none bg-white"
                             value={tempField.type}
                             onChange={(e) => setTempField({...tempField, type: e.target.value as FormFieldType})}
                             disabled={tempField.isSystem}
                          >
                             <option value="text">متن تک خطی</option>
                             <option value="textarea">متن چند خطی</option>
                             <option value="tel">شماره تماس</option>
                             <option value="email">ایمیل</option>
                             <option value="select">لیست کشویی</option>
                             <option value="checkbox">چک‌باکس</option>
                             <option value="date">تاریخ</option>
                             <option value="header">تیتر جداکننده</option>
                          </select>
                       </div>

                       {tempField.type === 'select' && (
                          <div>
                             <label className="block text-xs font-bold text-gray-500 mb-1">گزینه‌ها (با ویرگول جدا کنید)</label>
                             <textarea 
                                className="w-full px-3 py-2 rounded-lg border border-gray-300 text-sm focus:border-indigo-500 outline-none"
                                placeholder="گزینه 1, گزینه 2, گزینه 3"
