      // Add default if no match
      const defaultServiceId = selectedServiceForScript || (services.length > 0 ? services[0].id : 'unknown');

      const script = `
/**
 * Google Apps Script for syncing Google Form responses to Firestore (Smart Name & Brand Detection)
 * 
 * Features:
 * - Generates user-friendly IDs like EXP-1234-GF.
 * - Supports Multi-Service selection (Checkboxes).
 * - Distinguishes between Customer Name and Company Name.
 * - Formats description clearly with line breaks.
 * - Creates separate ticket for each service.
 * - Initializes all required fields to prevent dashboard crashes.
 * 
 * Setup:
 * 1. Tools > Script editor
 * 2. Paste code below
 * 3. Save & Run once to authorize
 * 4. Add Trigger: onFormSubmit -> From form -> On form submit
 */

function onFormSubmit(e) {
  var form = FormApp.getActiveForm();
  var itemResponses = e.response.getItemResponses();
  var timestamp = new Date().toISOString();

  // Configuration
  var projectId = "${firebaseConfig.projectId}";
  var collection = "tickets";
  var serviceMap = ${JSON.stringify(serviceMap)};
  var defaultServiceId = "${defaultServiceId}";

  // Extract Data
  var customerName = "کاربر گوگل فرم";
  var companyName = "";
  var phoneNumber = "";
  var description = "";
  var selectedServices = []; // Array of Service IDs

  for (var i = 0; i < itemResponses.length; i++) {
    var question = itemResponses[i].getItem().getTitle();
    var answer = itemResponses[i].getResponse(); // Can be string or array
    var qLower = question.toLowerCase();

    // Enhanced Detection Logic in generated script string
    var qLower = question.toLowerCase();

    // 1. Company / Brand Detection
    if (
        question.indexOf("شرکت") > -1 || 
        question.indexOf("برند") > -1 || 
        question.indexOf("تجاری") > -1 || 
        question.indexOf("موسسه") > -1 || 
        question.indexOf("تولیدی") > -1 || 
        question.indexOf("بازرگانی") > -1 || 
        question.indexOf("مجموعه") > -1 ||
        qLower.indexOf("company") > -1 || 
        qLower.indexOf("brand") > -1 || 
        qLower.indexOf("business") > -1
    ) {
        companyName = answer;
    }
    // 2. Person Name Detection
    else if (
        (question.indexOf("نام") > -1 || question.indexOf("اسم") > -1 || qLower.indexOf("name") > -1) && 
        question.indexOf("شرکت") === -1 && 
        question.indexOf("برند") === -1 && 
        question.indexOf("تجاری") === -1 &&
        question.indexOf("محصول") === -1 && // Exclude product
        question.indexOf("کالا") === -1      // Exclude goods
    ) {
        customerName = answer;
    }
    // Detect Phone
    else if (question.indexOf("تلفن") > -1 || question.indexOf("موبایل") > -1 || qLower.indexOf("phone") > -1 || qLower.indexOf("mobile") > -1) {
        phoneNumber = answer;
    }
    // Detect Service (Looking for 'service' or 'خدمت')
    else if (question.indexOf("خدمت") > -1 || question.indexOf("سرویس") > -1 || qLower.indexOf("service") > -1) {
        var answers = Array.isArray(answer) ? answer : [answer];

        for (var j = 0; j < answers.length; j++) {
            var sName = answers[j];
            var foundId = null;
            for (var key in serviceMap) {
                if (sName.indexOf(key) > -1 || key.indexOf(sName) > -1) {
                    foundId = serviceMap[key];
                    break;
                }
            }
            if (foundId) selectedServices.push(foundId);
        }
    }

    // Append to description with clear formatting
    var answerStr = Array.isArray(answer) ? answer.join(", ") : answer;
    description += "🔹 " + question + ": " + answerStr + "\\n\\n";
  }

  // Fallback if no service detected
  if (selectedServices.length === 0) {
      selectedServices.push(defaultServiceId);
  }

  // Create a Ticket for EACH selected service
  for (var k = 0; k < selectedServices.length; k++) {
      var sId = selectedServices[k];

      // Generate Friendly ID: EXP-RANDOM-GF
      var randomCode = Math.floor(1000 + Math.random() * 9000);
      var trackingId = "EXP-" + randomCode + "-GF";

      // Firestore Document Payload (REST API Format)
      var payload = {
        fields: {
          id: { stringValue: trackingId },
          status: { stringValue: "ثبت شده" },
          createdAt: { stringValue: timestamp },
          serviceId: { stringValue: sId },
          description: { stringValue: description },
          customerName: { stringValue: customerName },
          companyName: { stringValue: companyName },
          phoneNumber: { stringValue: phoneNumber },
          whatsappNumber: { stringValue: phoneNumber },
          // Empty arrays for files and subServices to prevent crashes
          files: { arrayValue: { values: [] } },
          selectedSubServices: { arrayValue: { values: [] } },
          // Proper Timeline Initialization
          timeline: {
            arrayValue: {
              values: [
                {
                  mapValue: {
                    fields: {
                      type: { stringValue: "creation" },
                      title: { stringValue: "ثبت از گوگل فرم" },
                      description: { stringValue: "درخواست توسط گوگل فرم ثبت شد." },
                      actorName: { stringValue: "Google Form" },
                      timestamp: { stringValue: timestamp },
                      visibility: { stringValue: "public" }
                    }
                  }
                }
              ]
            }
          }
        }
      };

      var url = "https://firestore.googleapis.com/v1/projects/" + projectId + "/databases/(default)/documents/" + collection + "?documentId=" + trackingId;

      var options = {
        method: "post",
        contentType: "application/json",
        payload: JSON.stringify(payload),
        muteHttpExceptions: true
      };

      try {
        var response = UrlFetchApp.fetch(url, options);
        Logger.log("Response for " + trackingId + ": " + response.getContentText());
      } catch(error) {
        Logger.log("Error sending to Firestore: " + error);
      }
  }
}
      `;
      setGeneratedScript(script.trim());
