                  <div className="bg-blue-50 border border-blue-100 rounded-xl p-4 text-sm text-blue-800 leading-relaxed mb-6">
                      با استفاده از این قابلیت، می‌توانید یک اسکریپت اختصاصی برای فرم‌های گوگل خود تولید کنید. 
                      این اسکریپت باعث می‌شود هر بار کاربری فرم را پر کرد، اطلاعات آن بلافاصله در پنل مدیریت شما ثبت شود.
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                      <div>
                          <label className="block text-sm font-bold text-gray-700 mb-2">انتخاب سرویس مرتبط</label>
                          <select 
                              className="w-full px-4 py-3 rounded-xl border border-gray-300 outline-none focus:ring-2 focus:ring-blue-500 bg-white"
                              value={selectedServiceForScript}
                              onChange={(e) => setSelectedServiceForScript(e.target.value)}
                          >
                              <option value="">-- انتخاب کنید --</option>
                              {services.map(s => (
                                  <option key={s.id} value={s.id}>{s.title}</option>
                              ))}
                          </select>
                          <p className="text-xs text-gray-500 mt-1">تیکت‌های وارده از فرم، با این سرویس ثبت خواهند شد.</p>
                      </div>
                      <div className="flex items-end">
                          <button 
                              onClick={generateGoogleScript}
                              disabled={!selectedServiceForScript}
                              className="w-full bg-blue-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-blue-200"
                          >
                              تولید کد اسکریپت
                          </button>
                      </div>
                  </div>

                  {generatedScript && (
                      <div className="mt-6 border-t border-gray-100 pt-6 animate-fade-in">
                          <div className="flex justify-between items-center mb-2">
                              <label className="text-sm font-bold text-gray-700">کد اسکریپت (Google Apps Script)</label>
                              <button 
                                  onClick={() => { navigator.clipboard.writeText(generatedScript); alert('کد کپی شد!'); }}
                                  className="text-blue-600 text-xs font-bold flex items-center gap-1 hover:bg-blue-50 px-2 py-1 rounded"
                              >
                                  <IconCopy className="w-4 h-4" /> کپی کد
                              </button>
                          </div>
                          <div className="relative">
                              <textarea 
                                  className="w-full h-64 bg-gray-900 text-green-400 font-mono text-xs p-4 rounded-xl dir-ltr text-left overflow-auto"
                                  readOnly
                                  value={generatedScript}
                              />
                          </div>

                          <div className="mt-6">
                              <h4 className="font-bold text-gray-800 mb-3">راهنمای نصب:</h4>
                              <ol className="list-decimal list-inside space-y-2 text-sm text-gray-600 bg-gray-50 p-4 rounded-xl border border-gray-200">
                                  <li>فرم گوگل خود را باز کنید.</li>
                                  <li>روی آیکون سه نقطه (بالا سمت چپ) کلیک کرده و گزینه <b>Script Editor</b> را انتخاب کنید.</li>
                                  <li>کدهای موجود را پاک کرده و کد بالا را جایگزین کنید.</li>
                                  <li>پروژه را ذخیره کنید (Ctrl+S).</li>
                                  <li>یک بار دکمه <b>Run</b> را بزنید و دسترسی‌های لازم را تایید کنید (Review Permissions -> Advanced -> Go to ... (unsafe) -> Allow).</li>
                                  <li>از منوی سمت چپ روی آیکون ساعت (Triggers) کلیک کنید.</li>
                                  <li>دکمه <b>Add Trigger</b> را بزنید.</li>
                                  <li>تنظیمات را اینگونه قرار دهید: <code>onFormSubmit</code> و <code>From form</code> و <code>On form submit</code>.</li>
                                  <li>ذخیره کنید. اکنون فرم شما متصل است!</li>
                              </ol>
                          </div>
                      </div>
                  )}
              </div>
          </div>
      )}

      {activeTab === 'daily' && (
          <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm relative overflow-hidden">
              <div className="flex items-center gap-3 mb-6">
                  <div className="p-2 bg-yellow-100 text-yellow-600 rounded-lg">
                      <IconBulb className="w-5 h-5" />
                  </div>
                  <h3 className="text-lg font-bold text-gray-800">مدیریت جملات آموزشی و انگیزشی</h3>
              </div>

              <div className="mb-6 flex items-center gap-3 bg-gray-50 p-4 rounded-xl border border-gray-100">
                  <input 
                      type="checkbox" 
                      id="show_tips" 
                      checked={showDailyTips} 
                      onChange={e => setShowDailyTips(e.target.checked)}
                      className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 cursor-pointer"
                  />
                  <label htmlFor="show_tips" className="font-bold text-gray-700 cursor-pointer select-none">
                      نمایش بخش "نکته روز" در صفحه اصلی
                  </label>
              </div>

              <div className="flex gap-2 mb-6">
                  <input 
                      className="flex-grow px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-indigo-500 outline-none"
                      placeholder="جمله جدید را وارد کنید..."
                      value={newTip}
                      onChange={e => setNewTip(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && handleAddTip()}
                  />
                  <button onClick={handleAddTip} className="bg-green-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-green-700">افزودن</button>
              </div>

              <div className="space-y-3 max-h-[400px] overflow-y-auto">
                  {dailyTips.map((tip, idx) => (
                      <div key={idx} className="flex justify-between items-center bg-gray-50 p-4 rounded-xl border border-gray-100">
                          <p className="text-gray-700 font-medium">{tip}</p>
                          <button onClick={() => handleRemoveTip(idx)} className="text-red-400 hover:text-red-600 p-2"><IconTrash className="w-4 h-4" /></button>
                      </div>
                  ))}
                  {dailyTips.length === 0 && <p className="text-center text-gray-400 py-4">هنوز جمله‌ای ثبت نشده است.</p>}
              </div>

              <div className="flex items-center justify-end border-t border-gray-100 pt-6 mt-6">
                  {saveSuccess && (
                      <span className="text-green-600 font-medium ml-4 flex items-center gap-1 animate-fade-in">
                          <IconCheck className="w-5 h-5" />
                          ذخیره شد
                      </span>
                  )}
                  <button
                      onClick={saveSettings}
                      disabled={isSaving}
                      className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 hover:scale-105 transition-all flex items-center gap-2"
                  >
                      {isSaving ? 'در حال ذخیره...' : 'ذخیره تغییرات'}
                  </button>
              </div>
          </div>
      )}

      {activeTab === 'invoice' && isMaster && (
         <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm relative overflow-hidden">
            <div className="flex items-center gap-3 mb-6">
               <div className="p-2 bg-purple-100 text-purple-600 rounded-lg">
                  <IconInvoice className="w-5 h-5" />
               </div>
               <h3 className="text-lg font-bold text-gray-800">تنظیمات قالب فاکتور</h3>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                   <label className="block text-sm font-bold text-gray-700 mb-2">نام شرکت در فاکتور</label>
                   <input className="w-full px-4 py-3 rounded-xl border border-gray-300 outline-none" value={invoiceTemplate.companyName} onChange={e => setInvoiceTemplate({...invoiceTemplate, companyName: e.target.value})} />
                </div>
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-2">لوگوی شرکت</label>
                    <div className="flex items-center gap-4">
                        <div onClick={() => logoInputRef.current?.click()} className="w-16 h-16 rounded-lg border border-gray-300 flex items-center justify-center cursor-pointer overflow-hidden bg-gray-50">
                            {invoiceTemplate.logoUrl ? <img src={invoiceTemplate.logoUrl} className="w-full h-full object-contain" /> : <IconUpload className="text-gray-400" />}
                        </div>
                        <button onClick={() => logoInputRef.current?.click()} className="text-sm text-indigo-600 hover:underline">{isProcessingLogo ? '...' : 'تغییر لوگو'}</button>
                        <input type="file" ref={logoInputRef} className="hidden" accept="image/*" onChange={handleLogoUpload} />
                    </div>
                </div>
                <div className="md:col-span-2">
                   <label className="block text-sm font-bold text-gray-700 mb-2">آدرس شرکت</label>
                   <input className="w-full px-4 py-3 rounded-xl border border-gray-300 outline-none" value={invoiceTemplate.address} onChange={e => setInvoiceTemplate({...invoiceTemplate, address: e.target.value})} />
                </div>
                <div>
                   <label className="block text-sm font-bold text-gray-700 mb-2">شماره تماس</label>
                   <input className="w-full px-4 py-3 rounded-xl border border-gray-300 outline-none dir-ltr text-right" value={invoiceTemplate.phone} onChange={e => setInvoiceTemplate({...invoiceTemplate, phone: e.target.value})} />
                </div>
                <div>
                   <label className="block text-sm font-bold text-gray-700 mb-2">نرخ مالیات پیش‌فرض (%)</label>
                   <input type="number" className="w-full px-4 py-3 rounded-xl border border-gray-300 outline-none dir-ltr text-right" value={invoiceTemplate.defaultTaxRate} onChange={e => setInvoiceTemplate({...invoiceTemplate, defaultTaxRate: parseFloat(e.target.value) || 0})} />
                </div>
                 <div className="md:col-span-2">
                   <label className="block text-sm font-bold text-gray-700 mb-2">متن پاورقی</label>
                   <input className="w-full px-4 py-3 rounded-xl border border-gray-300 outline-none" value={invoiceTemplate.footerText} onChange={e => setInvoiceTemplate({...invoiceTemplate,footerText: e.target.value})} />
                </div>
                 <div className="md:col-span-2">
                   <label className="block text-sm font-bold text-gray-700 mb-2">قوانین و شرایط فاکتور</label>
                   <textarea rows={4} className="w-full px-4 py-3 rounded-xl border border-gray-300 outline-none" value={invoiceTemplate.termsConditions} onChange={e => setInvoiceTemplate({...invoiceTemplate, termsConditions: e.target.value})} />
                </div>
                 <div>
                   <label className="block text-sm font-bold text-gray-700 mb-2">رنگ سازمانی (کد رنگ)</label>
                   <div className="flex gap-2">
                       <input type="color" className="w-12 h-12 rounded cursor-pointer border-0" value={invoiceTemplate.colorTheme} onChange={e => setInvoiceTemplate({...invoiceTemplate, colorTheme: e.target.value})} />
                       <input type="text" className="flex-grow px-4 py-3 rounded-xl border border-gray-300 outline-none dir-ltr" value={invoiceTemplate.colorTheme} onChange={e => setInvoiceTemplate({...invoiceTemplate, colorTheme: e.target.value})} />
                   </div>
                </div>
            </div>

             <div className="flex items-center justify-end border-t border-gray-100 pt-6 mt-6">
              {saveSuccess && <span className="text-green-600 font-medium ml-4">تنظیمات فاکتور ذخیره شد.</span>}
              <button onClick={saveSettings} disabled={isSaving} className="px-8 py-3 bg-purple-600 text-white rounded-xl font-bold shadow-lg shadow-purple-200 hover:bg-purple-700">
                {isSaving ? '...' : 'ذخیره قالب فاکتور'}
              </button>
           </div>
         </div>
      )}

      {/* Main Intake Form Builder */}
      {activeTab === 'form' && renderFormBuilderUI(config.formFields, false)}

      {/* Custom Forms Management */}
      {activeTab === 'custom_forms' && (
          <div>
              {showCustomFormList ? (
                  <div className="space-y-6">
                      <div className="flex justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                          <div>
                              <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                                  <IconClipboard className="w-6 h-6 text-indigo-600" />
                                  مدیریت فرم‌ها و استانداردها
                              </h3>
                              <p className="text-sm text-gray-500 mt-1">فرم‌های داخلی، چک‌لیست‌های ISO و استانداردها</p>
                          </div>
                          <button onClick={handleCreateCustomForm} className="bg-indigo-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-indigo-700 flex items-center gap-2 shadow-lg">
                              <IconPlus className="w-5 h-5" /> فرم جدید
                          </button>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                          {customForms.map(form => (
                              <div key={form.id} className="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm hover:shadow-md transition-all group relative">
                                  <div className="flex justify-between items-start mb-2">
                                      <span className="bg-indigo-50 text-indigo-700 text-xs font-bold px-2 py-1 rounded border border-indigo-100">{form.category}</span>
                                      <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                          <button onClick={() => handleEditCustomForm(form)} className="p-1.5 text-blue-500 hover:bg-blue-50 rounded"><IconEdit className="w-4 h-4" /></button>
                                          <button onClick={() => handleDeleteCustomForm(form.id)} className="p-1.5 text-red-500 hover:bg-red-50 rounded"><IconTrash className="w-4 h-4" /></button>
                                      </div>
                                  </div>
                                  <h4 className="font-bold text-gray-900 mb-1">{form.title}</h4>
                                  <p className="text-xs text-gray-500 mb-4 h-8 line-clamp-2">{form.description || 'بدون توضیحات'}</p>
                                  <div className="flex items-center justify-between text-xs text-gray-400 border-t border-gray-50 pt-3">
                                      <span className="flex items-center gap-1"><IconLayout className="w-3 h-3" /> {form.fields.length} فیلد</span>
                                      <span className="dir-ltr">{new Date(form.createdAt).toLocaleDateString('fa-IR')}</span>
                                  </div>
                              </div>
                          ))}
                          {customForms.length === 0 && <div className="col-span-full text-center py-12 text-gray-400">هنوز فرمی تعریف نشده است.</div>}
                      </div>
                  </div>
              ) : (
                  <div className="space-y-6">
                      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                          <div className="flex justify-between items-center mb-6 border-b border-gray-100 pb-4">
                              <h3 className="text-lg font-bold text-gray-800">{editingCustomForm?.id.startsWith('form-') ? 'ویرایش فرم' : 'فرم جدید'}</h3>
                              <button onClick={() => setShowCustomFormList(true)} className="text-gray-500 text-sm hover:text-gray-700">بازگشت به لیست</button>
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                              <div>
                                  <label className="block text-sm font-bold text-gray-700 mb-1">عنوان فرم</label>
                                  <input className="w-full px-3 py-2 border rounded-lg" value={editingCustomForm?.title || ''} onChange={e => setEditingCustomForm(prev => prev ? ({...prev, title: e.target.value}) : null)} />
                              </div>
                              <div>
                                  <label className="block text-sm font-bold text-gray-700 mb-1">دسته‌بندی (مثلاً: ISO, HR)</label>
                                  <input className="w-full px-3 py-2 border rounded-lg" value={editingCustomForm?.category || ''} onChange={e => setEditingCustomForm(prev => prev ? ({...prev, category: e.target.value}) : null)} placeholder="عمومی" />
                              </div>
                              <div className="md:col-span-2">
                                  <label className="block text-sm font-bold text-gray-700 mb-1">توضیحات</label>
                                  <textarea className="w-full px-3 py-2 border rounded-lg" value={editingCustomForm?.description || ''} onChange={e => setEditingCustomForm(prev => prev ? ({...prev, description: e.target.value}) : null)} rows={2} />
                              </div>
                              <div className="md:col-span-2">
                                  <label className="block text-sm font-bold text-gray-700 mb-2">دسترسی پرسنل (خالی = همه)</label>
                                  <div className="flex flex-wrap gap-2 p-3 border rounded-lg bg-gray-50">
                                      {config.personnelRoles?.map(role => (
                                          <button 
                                              key={role}
                                              onClick={() => setEditingCustomForm(prev => {
                                                  if (!prev) return null;
                                                  const newRoles = prev.allowedRoles.includes(role) 
                                                      ? prev.allowedRoles.filter(r => r !== role)
                                                      : [...prev.allowedRoles, role];
                                                  return { ...prev, allowedRoles: newRoles };
                                              })}
                                              className={`px-3 py-1 rounded-full text-xs font-bold border transition-colors ${editingCustomForm?.allowedRoles.includes(role) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-300'}`}
                                          >
                                              {role}
                                          </button>
                                      ))}
                                  </div>
                              </div>
                          </div>

                          {/* Use the shared form builder UI */}
                          {editingCustomForm && renderFormBuilderUI(editingCustomForm.fields, true)}

                          <div className="flex justify-end pt-6 border-t border-gray-100 mt-6">
                              <button onClick={handleSaveCustomForm} className="bg-green-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-green-200 hover:bg-green-700">ذخیره فرم</button>
                          </div>
                      </div>
                  </div>
              )}
          </div>
      )}
    </div>
  );
};

export enum TicketStatus {
  SUBMITTED = 'ثبت شده',
  PROCESSING = 'در حال بررسی',
  IN_PROGRESS = 'در دست اقدام',
  COMPLETED = 'تکمیل شده',
  CANCELLED = 'لغو شده'
}

export type Currency = 'IRR' | 'OMR' | 'USD';

export interface Price {
  amount: number;
  currency: Currency;
}

export interface AttachedFile {
  name: string;
  size: number;
  type: string;
  content: string; // Base64 or URL or Blob URL
  rawFile?: File; // Direct file reference for efficient upload
  // Upload Status Fields
  status?: 'pending' | 'uploading' | 'success' | 'error';
  progress?: number;
  errorMsg?: string;
}

export interface SaleRecord {
  id: string;
  agentId: string;
  agentName: string;
  amount: number;
  currency: Currency;
  depositDate: string; // YYYY-MM-DD
  targetAccount: string; // e.g., "Mellat - 1234"
  receiptFile?: AttachedFile; // Image of the receipt
  description?: string;
  createdAt: string;
  customerName?: string; // Optional: Linked customer
}

export interface SubService {
  id: string;
  title: string;
  titleEn?: string;
  price?: Price;
}

export interface ServiceOption {
  id: string;
  title: string;
  titleEn?: string; // English Title
  description: string;
  descriptionEn?: string; // English Description
  icon: string;
  price?: Price; // Updated to Price Object
  isActive: boolean;
  subServices?: SubService[]; // Nested Services
}

export interface PersonnelPermissions {
  canAssign: boolean; 
  canViewCustomers: boolean; 
  canViewTariffs: boolean; 
  canViewAllTickets: boolean;
  canIssueInvoices: boolean; // New permission for Invoicing
}

export interface PersonnelDocument {
  id: string;
  title: string;
  file: AttachedFile;
}

export interface Personnel {
  id: string;
  fullName: string;
  roles: string[]; 
  jobDescription?: string; 
  reportsTo?: string; // ID of the supervisor/manager
  email: string;
  username: string;
  password?: string;
  avatar?: string; 
  documents?: PersonnelDocument[]; 
  status: 'active' | 'inactive';
  permissions?: PersonnelPermissions; 
}

export interface Customer {
  id: string;
  fullName: string;
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string;
  email?: string;
  businessType?: string;
  firstContact: string;
  totalTickets: number;
  source?: string; 
  loyaltyCode?: string; // Unique code for discounts
}

export interface TimelineEntry {
  type: 'status_change' | 'comment' | 'assignment' | 'creation' | 'update' | 'project_update' | 'invoice_created';
  title: string;
  description?: string; 
  actorName: string; 
  timestamp: string;
  visibility?: 'public' | 'internal'; // Controls who sees this entry
}

export interface Payment {
  id: string;
  amount: number;
  currency: Currency;
  date: string;
  type: 'deposit' | 'settlement' | 'installment';
  note?: string;
}

export interface InvoiceItem {
  description: string;
  quantity: number;
  unitPrice: number;
  total: number;
}

export interface Invoice {
  id: string;
  number: string;
  date: string;
  dueDate?: string;
  customerName: string;
  companyName?: string;
  items: InvoiceItem[];
  currency: Currency;
  subTotal: number;
  taxRate: number;
  taxAmount: number;
  discount: number;
  total: number;
  note?: string;
  issuedBy: string;
}

export interface ProjectMilestone {
  id: string;
  title: string;
  isCompleted: boolean;
  dueDate?: string;
}

export interface ProjectRisk {
  id: string;
  title: string;
  impact: 'Low' | 'Medium' | 'High';
}

export interface ProjectTeamMember {
  userId: string;
  role: string; // e.g. "Head of Design"
  responsibility: string; // Specific task description
  joinedAt: string;
}

export interface ProjectDetails {
  isActive: boolean;
  tariff?: Price; // Cost/Price Object
  startDate: string;
  endDate: string;
  teamMemberIds: string[]; 
  teamMembers?: ProjectTeamMember[]; // Detailed team structure
  projectFiles: AttachedFile[];
  payments: Payment[]; // List of payments
  invoices?: Invoice[]; // List of issued invoices
  milestones?: ProjectMilestone[];
  risks?: ProjectRisk[];
  progress: number; 
  statusNote?: string;
}

export interface Ticket {
  id: string;
  customerName: string; 
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string; 
  businessType?: string; 
  serviceId: string;
  selectedSubServices?: string[]; // Array of SubService IDs or Names
  description: string;
  files?: AttachedFile[];
  status: TicketStatus;
  createdAt: string;
  aiAnalysis?: string;
  priority?: 'Low' | 'Medium' | 'High';
  assignedTo?: string;
  timeline: TimelineEntry[]; 
  customData?: Record<string, string>; 
  projectData?: ProjectDetails;
  discountApplied?: boolean; // If loyalty discount was used
}

export interface InternalMessage {
  id: string;
  senderId: string;
  senderName: string;
  senderAvatar?: string;
  recipientIds: string[];
  recipientNames: string[];
  subject: string;
  body: string;
  files?: AttachedFile[];
  createdAt: string;
  readBy: string[]; // IDs of recipients who read the message
}

export interface TaskComment {
  id: string;
  authorId: string;
  authorName: string;
  text: string;
  timestamp: string;
}

export interface TaskChecklistItem {
  id: string;
  text: string;
  isCompleted: boolean;
}

export interface Task {
  id: string;
  title: string;
  description?: string;
  creatorId: string;
  creatorName: string;
  assigneeIds: string[]; // List of personnel IDs responsible for this task
  isCompleted: boolean;
  checklist?: TaskChecklistItem[]; // Sub-tasks list
  dueDate?: string;
  priority: 'Low' | 'Medium' | 'High';
  createdAt: string;
  comments: TaskComment[];
}

export interface Meeting {
  id: string;
  title: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm
  endTime: string; // HH:mm
  location: string;
  organizerId: string;
  organizerName: string;
  attendeeIds: string[];
  description?: string;
}

export interface KPI {
  id: string;
  title: string;
  titleEn?: string;
  targetValue: number;
  currentValue: number;
  unit: 'percent' | 'count' | 'currency';
  period: 'monthly' | 'quarterly' | 'yearly';
  assignedRole?: string; // Role-based KPI
  assignedUserId?: string; // Specific User KPI
  description?: string;
}

export interface CustomForm {
  id: string;
  title: string;
  category: string; // e.g., 'ISO Standards', 'HR', 'Logistics'
  description?: string;
  fields: FormField[];
  allowedRoles: string[]; // Empty array means available to all
  createdAt: string;
  createdBy: string;
}

export interface SystemLog {
  id: string;
  actionType: 'CREATE' | 'UPDATE' | 'DELETE' | 'LOGIN' | 'OTHER';
  entity: 'Ticket' | 'Customer' | 'Personnel' | 'Project' | 'Task' | 'Meeting' | 'Message' | 'System' | 'KPI' | 'CustomForm' | 'Sale';
  entityId?: string;
  details: string;
  actorName: string;
  actorId?: string;
  timestamp: string;
  backupData?: any; // Stores the deleted data for restoration
  collectionName?: string; // Target collection for restoration
}

export interface FeaturedBusiness {
  id: string;
  name: string;
  description: string;
  imageUrl: string;
  websiteUrl?: string;
  contactNumber?: string;
  category: string;
  isGold: boolean; // Premium status for higher visibility
}

export type ViewState = 'landing' | 'new-ticket' | 'tracking' | 'admin';

export type FormFieldType = 'text' | 'textarea' | 'email' | 'tel' | 'select' | 'header' | 'date' | 'checkbox';

export interface FormField {
  id: string;
  key: string; 
  label: string;
  labelEn?: string;
  type: FormFieldType;
  required: boolean;
  placeholder?: string;
  placeholderEn?: string;
  options?: string[]; 
  isSystem?: boolean; 
  order: number;
}

export interface InvoiceTemplate {
  companyName: string;
  logoUrl?: string;
  address: string;
  phone: string;
  website?: string;
  footerText: string;
  termsConditions: string;
  defaultTaxRate: number; // Percentage
  colorTheme: string; // Hex Code
}

export interface AppConfig {
  appTitle: string;
  appTitleEn: string;
  appSubtitle: string;
  appSubtitleEn: string;

  // Landing Page Content
  landingHeroTitle?: string;
  landingHeroSubtitle?: string;
  footerText?: string;

  // Daily Content
  dailyTips?: string[];
  showDailyTips?: boolean;

  // Featured Businesses (Ads)
  featuredBusinesses?: FeaturedBusiness[];

  formFields: FormField[];
  personnelRoles?: string[]; 
  invoiceTemplate?: InvoiceTemplate;
}

