                  <div className="flex justify-between items-center p-6 border-b border-gray-100 bg-white z-10">
                      <div className="flex items-center gap-4">
                          <div className="bg-indigo-50 text-indigo-600 p-3 rounded-xl">
                              <IconBriefcase className="w-6 h-6" />
                          </div>
                          <div>
                              <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                                  {selectedTicket.customerName}
                                  <span className={`text-xs px-2 py-1 rounded-full ${getStatusBadge(selectedTicket.status)}`}>{selectedTicket.status}</span>
                              </h2>
                              <p className="text-sm text-gray-500 font-mono mt-1">{selectedTicket.id} | {new Date(selectedTicket.createdAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</p>
                          </div>
                      </div>
                      <button onClick={() => setSelectedTicketId(null)} className="p-2 hover:bg-gray-100 rounded-full transition-colors">✕</button>
                  </div>

                  <div className="flex border-b border-gray-100 px-6">
                      <button onClick={() => setActiveModalTab('info')} className={`px-6 py-4 font-bold text-sm border-b-2 transition-colors ${activeModalTab === 'info' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>{t.ticketInfo}</button>
                      <button onClick={() => setActiveModalTab('project')} className={`px-6 py-4 font-bold text-sm border-b-2 transition-colors ${activeModalTab === 'project' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>{t.projectMgmt}</button>
                  </div>

                  <div className="flex-grow overflow-y-auto p-6 bg-gray-50">
                      {activeModalTab === 'info' ? (
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                              <div className="md:col-span-1 space-y-6">
                                  <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                                      <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2"><IconUsers className="w-5 h-5 text-indigo-500" /> {t.customerInfo}</h3>
                                      <div className="space-y-3 text-sm">
                                          <div className="flex justify-between"><span className="text-gray-500">{t.fullName}</span><span className="font-medium">{selectedTicket.customerName}</span></div>
                                          <div className="flex justify-between"><span className="text-gray-500">{t.company}</span><span className="font-medium">{selectedTicket.companyName || '-'}</span></div>
                                          <div className="flex justify-between"><span className="text-gray-500">{t.mobile}</span><span className="font-medium dir-ltr">{selectedTicket.phoneNumber}</span></div>
                                          {selectedTicket.whatsappNumber && <div className="flex justify-between"><span className="text-gray-500">{t.whatsapp}</span><span className="font-medium dir-ltr">{selectedTicket.whatsappNumber}</span></div>}
                                          <div className="flex justify-between"><span className="text-gray-500">{t.location}</span><span className="font-medium">{selectedTicket.location}</span></div>
                                          <div className="flex justify-between"><span className="text-gray-500">{t.bizType}</span><span className="font-medium">{selectedTicket.businessType}</span></div>
                                      </div>
                                  </div>

                                  <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                                      <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2"><IconShield className="w-5 h-5 text-purple-500" /> {t.expert}</h3>
                                      {canAssign ? (
                                          <div className="flex gap-2">
                                              <select 
                                                  className="flex-grow p-2 border rounded-lg bg-gray-50 text-sm outline-none"
                                                  value={tempAssignedTo || selectedTicket.assignedTo || ''}
                                                  onChange={(e) => setTempAssignedTo(e.target.value)}
                                              >
                                                  <option value="">{t.notAssigned}</option>
                                                  {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName} - {p.roles.join(', ')}</option>)}
                                              </select>
                                              <button 
                                                  onClick={() => {
                                                      if(tempAssignedTo && tempAssignedTo !== selectedTicket.assignedTo) {
                                                          const expertName = personnel.find(p => p.id === tempAssignedTo)?.fullName || 'Unknown';
                                                          onUpdateTicket(selectedTicket.id, { assignedTo: tempAssignedTo, status: TicketStatus.PROCESSING }, currentUser.fullName, `پرونده به ${expertName} ارجاع شد.`);
                                                      }
                                                  }}
                                                  className="bg-purple-600 text-white px-3 rounded-lg text-sm font-bold hover:bg-purple-700"
                                              >
                                                  {t.assign}
                                              </button>
                                          </div>
                                      ) : (
                                          <div className="text-sm font-medium text-gray-700">
                                              {selectedTicket.assignedTo ? personnel.find(p => p.id === selectedTicket.assignedTo)?.fullName : t.notAssigned}
                                          </div>
                                      )}
                                  </div>
                              </div>

                              <div className="md:col-span-2 space-y-6">
                                  <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                                      <div className="flex justify-between items-start mb-4">
                                          <h3 className="font-bold text-gray-800 flex items-center gap-2"><IconFile className="w-5 h-5 text-blue-500" /> {t.description}</h3>
                                          <select 
                                              className="bg-gray-100 text-gray-700 text-xs font-bold px-3 py-1.5 rounded-lg border-transparent focus:border-gray-300 outline-none"
                                              value={selectedTicket.status}
                                              onChange={(e) => onUpdateTicket(selectedTicket.id, { status: e.target.value as TicketStatus }, currentUser.fullName)}
                                          >
                                              {Object.values(TicketStatus).map(s => <option key={s} value={s}>{s}</option>)}
                                          </select>
                                      </div>
                                      <p className="text-gray-700 leading-relaxed text-sm whitespace-pre-wrap">{selectedTicket.description}</p>

                                      {selectedTicket.selectedSubServices && selectedTicket.selectedSubServices.length > 0 && (
                                          <div className="mt-4 pt-4 border-t border-gray-100">
                                              <span className="block text-xs font-bold text-gray-500 mb-2">{t.subServices}</span>
                                              <div className="flex flex-wrap gap-2">
                                                  {selectedTicket.selectedSubServices.map((subId, idx) => {
                                                      const service = services.find(s => s.id === selectedTicket.serviceId);
                                                      const sub = service?.subServices?.find(ss => ss.id === subId);
                                                      const title = sub ? (lang === 'en' && sub.titleEn ? sub.titleEn : sub.title) : subId;
                                                      return (
                                                          <span key={idx} className="bg-blue-50 text-blue-700 px-2 py-1 rounded text-xs border border-blue-100">
                                                              {title}
                                                          </span>
                                                      );
                                                  })}
                                              </div>
                                          </div>
                                      )}

                                      {selectedTicket.files && selectedTicket.files.length > 0 && (
                                          <div className="mt-6">
                                              <h4 className="text-sm font-bold text-gray-800 mb-2">{t.files}</h4>
                                              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                                                  {selectedTicket.files.map((file, idx) => (
                                                      <a key={idx} href={file.content} target="_blank" rel="noreferrer" className="flex items-center gap-2 p-3 rounded-xl border border-gray-200 hover:bg-gray-50 transition-colors group">
                                                          <div className="p-2 bg-gray-100 rounded-lg text-gray-500 group-hover:text-blue-500 transition-colors"><IconPaperclip className="w-4 h-4" /></div>
                                                          <div className="overflow-hidden">
                                                              <div className="text-xs font-bold text-gray-700 truncate">{file.name}</div>
                                                              <div className="text-[10px] text-gray-400">{(file.size / 1024).toFixed(0)} KB</div>
                                                          </div>
                                                      </a>
                                                  ))}
                                              </div>
                                          </div>
                                      )}
                                  </div>

                                  <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                                      <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2"><IconActivity className="w-5 h-5 text-orange-500" /> {t.events}</h3>
                                      <div className="space-y-6 max-h-80 overflow-y-auto pr-2 custom-scrollbar">
                                          {selectedTicket.timeline.map((entry, idx) => (
                                              <div key={idx} className={`relative flex gap-4 ${entry.visibility === 'internal' ? 'bg-yellow-50/50 p-2 rounded-lg -mx-2' : ''}`}>
                                                  <div className="flex flex-col items-center">
                                                      <div className={`w-3 h-3 rounded-full mt-1.5 ring-4 ring-white ${entry.type === 'creation' ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                                                      {idx !== selectedTicket.timeline.length - 1 && <div className="w-0.5 flex-grow bg-gray-200 my-1"></div>}
                                                  </div>
                                                  <div className="flex-grow">
                                                      <div className="flex justify-between items-start">
                                                          <span className="text-xs font-bold text-gray-800">{entry.title} <span className="text-gray-400 font-normal">by {entry.actorName}</span></span>
                                                          <span className="text-[10px] text-gray-400 dir-ltr">{new Date(entry.timestamp).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span>
                                                      </div>
                                                      {entry.description && <p className="text-sm text-gray-600 mt-1">{entry.description}</p>}
                                                      {entry.visibility === 'internal' && <span className="text-[10px] bg-yellow-200 text-yellow-800 px-1.5 rounded ml-2">Internal</span>}
                                                  </div>
                                              </div>
                                          ))}
                                          <div ref={commentsEndRef}></div>
                                      </div>
                                      <div className="mt-4 pt-4 border-t border-gray-100">
                                          <div className="flex gap-2 mb-2">
                                              <button onClick={() => setCommentVisibility('public')} className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-colors ${commentVisibility === 'public' ? 'bg-blue-100 text-blue-700' : 'bg-gray-50 text-gray-500'}`}>{t.publicReport}</button>
                                              <button onClick={() => setCommentVisibility('internal')} className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-colors ${commentVisibility === 'internal' ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-50 text-gray-500'}`}>{t.internalNote}</button>
                                          </div>
                                          <div className="relative">
                                              <textarea 
                                                  className={`w-full p-3 rounded-xl border outline-none text-sm min-h-[80px] ${commentVisibility === 'internal' ? 'bg-yellow-50 border-yellow-200 focus:ring-yellow-500' : 'bg-white border-gray-200 focus:ring-blue-500'} focus:ring-2`}
                                                  placeholder={t.writeMsg}
                                                  value={newComment}
                                                  onChange={(e) => setNewComment(e.target.value)}
                                                  onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), onUpdateTicket(selectedTicket.id, {}, currentUser.fullName, newComment, commentVisibility), setNewComment(''))} 
                                              />
                                              <div className="flex justify-between items-center mt-2">
                                                  <button onClick={() => setShowMentionList(!showMentionList)} className="text-gray-400 hover:text-blue-600 p-1 rounded hover:bg-blue-50">@ Mention</button>
                                                  <button 
                                                      onClick={() => {
                                                          if(newComment.trim()) {
                                                              onUpdateTicket(selectedTicket.id, {}, currentUser.fullName, newComment, commentVisibility);
                                                              setNewComment('');
                                                          }
                                                      }}
                                                      disabled={!newComment.trim()}
                                                      className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-indigo-700 disabled:opacity-50"
                                                  >
                                                      {t.send}
                                                  </button>
                                              </div>
                                              {showMentionList && (
                                                  <div className="absolute bottom-full left-0 mb-2 w-48 bg-white border border-gray-200 rounded-xl shadow-xl max-h-40 overflow-y-auto z-20">
                                                      {personnel.map(p => (
                                                          <button 
                                                              key={p.id} 
                                                              className="w-full text-start px-3 py-2 text-xs hover:bg-gray-50 text-gray-700 border-b border-gray-50 last:border-0"
                                                              onClick={() => {
                                                                  setNewComment(prev => prev + `@${p.username} `);
                                                                  setShowMentionList(false);
                                                              }}
                                                          >
                                                              {p.fullName}
                                                          </button>
                                                      ))}
                                                  </div>
                                              )}
                                          </div>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      ) : (
                          <div className="space-y-6">
                              <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 text-center">
                                  <IconProject className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                                  <h3 className="text-lg font-bold text-gray-800">Project Management Module</h3>
                                  <p className="text-gray-500">This section allows detailed project tracking, milestones, and financial management.</p>
                              </div>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      );
  };

  return (
    <div className="flex flex-col md:flex-row gap-6 min-h-[calc(100vh-100px)]">
      {/* ... (Invoice Modal & New Project Modal logic remains same) */}
      {showInvoiceModal && selectedTicket && (
          <InvoiceModal 
             customer={{ id: selectedTicket.customerName, fullName: selectedTicket.customerName, companyName: selectedTicket.companyName, location: selectedTicket.location, phoneNumber: selectedTicket.phoneNumber, whatsappNumber: selectedTicket.whatsappNumber, firstContact: '', totalTickets: 0 }}
             template={config.invoiceTemplate || { companyName: config.appTitle, address: '', phone: '', footerText: '', termsConditions: '', defaultTaxRate: 0, colorTheme: '#4f46e5' }}
             initialData={editingInvoice}
             onSave={handleSaveInvoice}
             onClose={() => setShowInvoiceModal(false)}
          />
      )}

      {showNewProjectModal && (
          // ... (Existing New Project Modal Code)
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
              <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in overflow-hidden">
                  <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-purple-50">
                      <h3 className="font-bold text-lg text-purple-900 flex items-center gap-2"><IconProject className="w-5 h-5" />{t.newProject}</h3>
                      <button onClick={handleProjectModalClose} className="text-gray-400 hover:text-gray-600">✕</button>
                  </div>
                  {createdProjectId ? (
                      <div className="p-8 text-center"><div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4"><IconCheck className="w-8 h-8 text-green-600" /></div><h3 className="text-xl font-bold text-gray-800 mb-2">{t.successProject}</h3><p className="text-gray-500 text-sm mb-6">Tracking Code:</p><div className="bg-gray-50 border-2 border-dashed border-purple-200 rounded-xl p-4 flex items-center justify-between gap-3 mb-6"><span className="font-mono font-black text-2xl text-purple-700 tracking-wider">{createdProjectId}</span><button onClick={() => { navigator.clipboard.writeText(createdProjectId); alert(t.copyCode); }} className="bg-white border border-gray-200 text-gray-600 hover:text-purple-600 hover:border-purple-300 p-2 rounded-lg transition-colors"><IconCopy className="w-5 h-5" /></button></div><button onClick={handleProjectModalClose} className="w-full py-3 bg-purple-600 text-white rounded-xl font-bold hover:bg-purple-700 transition-colors">{t.understand}</button></div>
                  ) : (
                      <form onSubmit={handleCreateProject} className="p-6 space-y-4">
                          <div><label className="block text-sm font-bold text-gray-700 mb-1">{t.projectTitle}</label><input required className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" value={newProjectData.title} onChange={e => setNewProjectData({...newProjectData, title: e.target.value})} /></div>
                          <div><label className="block text-sm font-bold text-gray-700 mb-1">{t.relatedService}</label><select className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500 bg-white" required value={newProjectData.serviceId} onChange={e => setNewProjectData({...newProjectData, serviceId: e.target.value})}><option value="">...</option>{services.map(s => <option key={s.id} value={s.id}>{lang === 'en' && s.titleEn ? s.titleEn : s.title}</option>)}</select></div>
                          <div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.customer}</label><input required className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" value={newProjectData.customerName} onChange={e => setNewProjectData({...newProjectData, customerName: e.target.value})} /></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.phone}</label><input required className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500 dir-ltr text-right" value={newProjectData.phoneNumber} onChange={e => setNewProjectData({...newProjectData, phoneNumber: e.target.value})} /></div></div>
                          <div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.startDate}</label><input type="date" className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" value={newProjectData.startDate} onChange={e => setNewProjectData({...newProjectData, startDate: e.target.value})} /></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.endDate}</label><input type="date" className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" value={newProjectData.endDate} onChange={e => setNewProjectData({...newProjectData, endDate: e.target.value})} /></div></div>
                          <div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.contractAmount}</label><div className="flex gap-2"><input className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" placeholder="0" value={newProjectData.tariffAmount} onChange={e => setNewProjectData({...newProjectData, tariffAmount: formatNumberInput(e.target.value)})} /><select className="px-2 py-2 rounded-lg border border-gray-300 bg-white" value={newProjectData.tariffCurrency} onChange={e => setNewProjectData({...newProjectData, tariffCurrency: e.target.value as Currency})}><option value="IRR">IRR</option><option value="USD">USD</option><option value="OMR">OMR</option></select></div></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.priority}</label><select className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500 bg-white" value={newProjectData.priority} onChange={e => setNewProjectData({...newProjectData, priority: e.target.value as any})}><option value="Low">Low</option><option value="Medium">Medium</option><option value="High">High</option></select></div></div>
                          <div className="flex gap-3 pt-4"><button type="button" onClick={handleProjectModalClose} className="flex-1 py-2.5 bg-gray-100 text-gray-700 rounded-xl font-bold hover:bg-gray-200">{t.cancel}</button><button type="submit" className="flex-1 py-2.5 bg-purple-600 text-white rounded-xl font-bold hover:bg-purple-700 shadow-lg shadow-purple-200">{t.create}</button></div>
                      </form>
                  )}
              </div>
          </div>
      )}

      <div className="w-full md:w-72 shrink-0 space-y-6">
         <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center text-center sticky top-24">
            <div className="relative w-24 h-24 mb-4"><div className="w-full h-full rounded-full overflow-hidden border-2 border-indigo-100 shadow-md">{currentUser.avatar ? (<img src={currentUser.avatar} alt={currentUser.fullName} className="w-full h-full object-cover" />) : (<div className="w-full h-full bg-gray-100 flex items-center justify-center text-gray-400 text-2xl font-bold">{currentUser.fullName.charAt(0)}</div>)}</div><div className="absolute bottom-0 right-0 bg-green-500 w-4 h-4 rounded-full border-2 border-white"></div></div>
            <h3 className="font-bold text-gray-900 text-lg">{currentUser.fullName}</h3>
            <div className="flex flex-wrap justify-center gap-1 mt-1 mb-2">{(currentUser.roles || []).map((r, i) => (<span key={i} className="text-xs text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-100">{r}</span>))}</div>
            {directManager && (<div className="text-xs text-gray-500 mb-4 bg-gray-50 px-2 py-1 rounded inline-flex items-center gap-1"><IconLayout className="w-3 h-3" /> {t.manager}: {directManager.fullName}</div>)}
            <div className="w-full space-y-2">
                <button onClick={() => setActiveTab('overview')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'overview' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconActivity className="w-5 h-5" /><span className="font-medium">{t.overview}</span></button>
                <button onClick={() => setActiveTab('tasks')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all relative ${activeTab === 'tasks' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconList className="w-5 h-5" /><span className="font-medium">{t.tasks}</span>{pendingTasksCount > 0 && <span className="absolute rtl:left-4 ltr:right-4 bg-amber-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{pendingTasksCount}</span>}</button>
                <button onClick={() => setActiveTab('meetings')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'meetings' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconCalendarClock className="w-5 h-5" /><span className="font-medium">{t.meetings}</span></button>
                <button onClick={() => setActiveTab('messages')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all relative ${activeTab === 'messages' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconMail className="w-5 h-5" /><span className="font-medium">{t.messages}</span>{unreadMessagesCount > 0 && <span className="absolute rtl:left-4 ltr:right-4 bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{unreadMessagesCount}</span>}</button>
                {canAccessSales && (<button onClick={() => setActiveTab('sales')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'sales' ? 'bg-emerald-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconTag className="w-5 h-5" /><span className="font-medium">{t.sales}</span></button>)}
                <button onClick={() => setActiveTab('projects')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'projects' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconProject className="w-5 h-5" /><span className="font-medium">{t.projects}</span></button>
                <button onClick={() => setActiveTab('forms')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'forms' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconClipboard className="w-5 h-5" /><span className="font-medium">{t.forms}</span></button>
                {(isAdmin || isMaster) && (<button onClick={() => setActiveTab('financial')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'financial' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconChart className="w-5 h-5" /><span className="font-medium">{t.financial}</span></button>)}
                {hasCustomerAccess && (<button onClick={() => setActiveTab('customers')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'customers' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconUsers className="w-5 h-5" /><span className="font-medium">{t.customers}</span></button>)}
                {hasTariffAccess && (<button onClick={() => setActiveTab('services')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'services' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconBriefcase className="w-5 h-5" /><span className="font-medium">{t.services}</span></button>)}
                {isAdmin && (<><div className="px-4 py-2 text-xs font-bold text-gray-400 mt-4 border-t border-gray-100 pt-4">Admin</div><button onClick={() => setActiveTab('personnel')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconShield className="w-5 h-5" /><span className="font-medium">{t.personnel}</span></button><button onClick={() => setActiveTab('settings')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconSettings className="w-5 h-5" /><span className="font-medium">{t.settings}</span></button></>)}
                {isMaster && (<><button onClick={() => setActiveTab('logs')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'logs' ? 'bg-gray-800 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconHistory className="w-5 h-5" /><span className="font-medium">{t.logs}</span></button><button onClick={() => setActiveTab('reports')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconBarChart2 className="w-5 h-5" /><span className="font-medium">{t.reports}</span></button><button onClick={() => setActiveTab('kpi')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'kpi' ? 'bg-pink-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconTarget className="w-5 h-5" /><span className="font-medium">{t.kpi}</span></button></>)}
            </div>
            <button onClick={onLogout} className="w-full text-sm font-medium text-red-600 bg-red-50 hover:bg-red-100 py-3 rounded-xl transition-colors mt-6">{t.logout}</button>
        </div>
      </div>

      <div className="flex-grow">
        {/* ... (Overview, Projects, Forms content remains same) ... */}
        {activeTab === 'overview' && (
            <div className="space-y-8 animate-fade-in">
                 <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.myTasks}</div><div className="text-2xl font-black text-indigo-600">{myTasks.filter(t => t.status !== 'تکمیل شده' && t.status !== 'لغو شده').length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.allRequests}</div><div className="text-2xl font-black text-gray-800">{tickets.filter(t => t.status !== 'تکمیل شده').length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.activeProjects}</div><div className="text-2xl font-black text-purple-600">{tickets.filter(t => t.projectData?.isActive).length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.newMessages}</div><div className="text-2xl font-black text-blue-600">{unreadMessagesCount}</div></div>
                 </div>

                 {userKPIs.length > 0 && (
                     <div className="bg-pink-50 border border-pink-100 rounded-2xl p-6 shadow-sm">
                         <h3 className="font-bold text-pink-900 flex items-center gap-2 mb-4"><IconTarget className="w-5 h-5" /> {t.kpiWidget}</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                             {userKPIs.map(k => {
                                 const progress = Math.min(100, Math.round((k.currentValue / k.targetValue) * 100));
                                 return (
                                     <div key={k.id} className="bg-white p-4 rounded-xl border border-pink-100 shadow-sm">
                                         <div className="flex justify-between items-center mb-1">
                                             <span className="text-sm font-bold text-gray-800">{k.title}</span>
                                             <span className="text-xs bg-gray-100 text-gray-500 px-2 py-0.5 rounded">{k.period}</span>
                                         </div>
                                         <div className="text-xs text-gray-500 mb-2">{k.currentValue} / {k.targetValue} {k.unit}</div>
                                         <div className="w-full bg-gray-100 rounded-full h-1.5 overflow-hidden">
                                             <div className={`h-full rounded-full ${progress >= 100 ? 'bg-green-500' : progress >= 70 ? 'bg-blue-500' : 'bg-pink-500'}`} style={{ width: `${progress}%` }}></div>
                                         </div>
                                     </div>
                                 );
                             })}
                         </div>
                     </div>
                 )}

                 {myPendingTasks.length > 0 && (
                     <div className="bg-amber-50 border border-amber-200 rounded-2xl p-6 shadow-sm">
                         <div className="flex justify-between items-center mb-4"><h3 className="font-bold text-amber-900 flex items-center gap-2"><IconList className="w-5 h-5 text-amber-600" /> {t.pendingTasks} ({myPendingTasks.length})</h3><button onClick={() => setActiveTab('tasks')} className="text-amber-700 hover:text-amber-900 text-sm font-bold underline">{t.viewAll}</button></div>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">{myPendingTasks.slice(0, 4).map(task => (<div key={task.id} className="bg-white p-4 rounded-xl border border-amber-100 flex justify-between items-center shadow-sm hover:shadow-md transition-shadow"><div><div className="font-bold text-gray-800 text-sm mb-1">{task.title}</div><div className="text-xs text-gray-500 flex items-center gap-2"><span className={`px-2 py-0.5 rounded ${task.priority === 'High' ? 'bg-red-100 text-red-600' : 'bg-gray-100'}`}>{task.priority}</span><span>{task.creatorName}</span></div></div><button onClick={() => setActiveTab('tasks')} className="bg-amber-100 text-amber-800 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-amber-200">{t.doTask}</button></div>))}</div>
                     </div>
                 )}
                 <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                     <div className="flex flex-col md:flex-row justify-between items-center mb-4 gap-4">
                         <div className="flex gap-2">
                             {canViewAllTickets && <div className="flex bg-gray-100 p-1 rounded-lg"><button onClick={() => setFilterMode('my')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'my' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.myCartable}</button><button onClick={() => setFilterMode('all')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'all' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.allCompany}</button></div>}
                             <select className="bg-gray-100 text-gray-600 text-sm font-bold px-3 py-1.5 rounded-lg border-transparent focus:border-gray-300 outline-none" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as any)}><option value="all">{t.allStatuses}</option>{Object.values(TicketStatus).map(s => <option key={s} value={s}>{s}</option>)}</select>
                         </div>
                         <div className="relative w-full md:w-64">
                             <input type="text" className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-100" placeholder={t.searchPlaceholder} value={globalSearch} onChange={e => setGlobalSearch(e.target.value)} />
                             <IconSearch className="w-4 h-4 text-gray-400 absolute left-3 top-2.5" />
                         </div>
                     </div>
                     <div className="overflow-x-auto"><table className="w-full text-start"><thead className="bg-gray-50 text-gray-500 text-sm"><tr><th className="px-4 py-3 rounded-tr-lg">{t.code}</th><th className="px-4 py-3">{t.service}</th><th className="px-4 py-3">{t.status}</th><th className="px-4 py-3 text-center rounded-tl-lg">{t.action}</th></tr></thead><tbody className="divide-y divide-gray-100">{paginatedTickets.map(ticket => (
                        <tr key={ticket.id} className="hover:bg-gray-50 transition-colors">
                            <td className="px-4 py-3">
                                <div className="flex flex-col">
                                    <span className="font-mono text-[10px] text-gray-400 mb-0.5">{ticket.id}</span>
                                    <span className="font-bold text-gray-800 text-sm" title={ticket.customerName}>{ticket.customerName}</span>
                                    {ticket.companyName && (
                                        <span className="text-xs text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded w-fit mt-0.5 border border-indigo-100 flex items-center gap-1">
                                           <IconBriefcase className="w-3 h-3" /> {ticket.companyName}
                                        </span>
                                    )}
                                </div>
                            </td>
                            <td className="px-4 py-3">
                                <div className="text-sm font-medium text-gray-700">{getServiceTitle(ticket.serviceId)}</div>
                                <div className="text-[10px] text-gray-400 dir-ltr">{new Date(ticket.createdAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })}</div>
                            </td>
                            <td className="px-4 py-3"><span className={`px-2 py-1 rounded text-xs font-bold ${getStatusBadge(ticket.status)}`}>{ticket.status}</span></td>
                            <td className="px-4 py-3 text-center"><button onClick={() => setSelectedTicketId(ticket.id)} className="bg-indigo-50 text-indigo-600 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-indigo-100 transition-colors">{t.check}</button></td>
                        </tr>
                     ))}</tbody></table>{paginatedTickets.length === 0 && <div className="text-center py-8 text-gray-400 text-sm">{t.notFound}</div>}</div>
                     {totalPages > 1 && (
                        <div className="flex justify-center items-center p-4 border-t border-gray-100 gap-4">
                            <button 
                                onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                                disabled={currentPage === 1}
                                className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed transition-colors text-sm font-bold"
                            >
                                {t.prev}
                            </button>
                            <span className="text-sm text-gray-600 font-medium">
                                {currentPage} / {totalPages}
                            </span>
                            <button 
                                onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                                disabled={currentPage === totalPages}
                                className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed transition-colors text-sm font-bold"
                            >
                                {t.next}
                            </button>
                        </div>
                     )}
                 </div>
            </div>
        )}
        {activeTab === 'projects' && (
            <div className="space-y-6 animate-fade-in">
                <div className="flex justify-between items-center"><h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><div className="bg-purple-100 text-purple-600 p-2 rounded-lg"><IconProject className="w-6 h-6" /></div>{t.projectDashboard}</h2><button onClick={() => setShowNewProjectModal(true)} className="bg-purple-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-purple-700 flex items-center gap-2 shadow-lg shadow-purple-200"><IconPlus className="w-5 h-5" /> {t.newProject}</button></div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">{activeProjects.map(project => (<div key={project.id} className="bg-white rounded-2xl border border-gray-200 p-5 shadow-sm hover:shadow-lg transition-all cursor-pointer group relative overflow-hidden" onClick={() => setSelectedTicketId(project.id)}><div className="absolute top-0 left-0 w-1 h-full bg-purple-500"></div><div className="flex justify-between items-start mb-3"><span className="text-xs font-bold text-gray-400">#{project.id}</span><span className={`text-[10px] px-2 py-0.5 rounded border ${getStatusBadge(project.status)}`}>{project.status}</span></div><h3 className="font-bold text-gray-900 mb-1">{project.customerName}</h3><p className="text-xs text-gray-500 mb-4">{getServiceTitle(project.serviceId)}</p><div className="mb-4"><div className="flex justify-between text-xs text-gray-500 mb-1"><span>{t.progress}</span><span className="font-bold text-purple-600">{project.projectData?.progress}%</span></div><div className="w-full bg-gray-100 rounded-full h-1.5"><div className="bg-purple-500 h-1.5 rounded-full transition-all" style={{ width: `${project.projectData?.progress}%` }}></div></div></div><div className="flex items-center justify-between text-xs text-gray-400"><span>{new Date(project.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span><span className="group-hover:text-purple-600 font-bold transition-colors">{t.view} →</span></div></div>))} {activeProjects.length === 0 && <div className="col-span-full py-12 text-center text-gray-400 bg-white rounded-2xl border border-dashed border-gray-200">{t.notFound}</div>}</div>
            </div>
        )}

        {activeTab === 'forms' && (
            <div className="space-y-6 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex items-center justify-between">
                    <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                        <div className="bg-indigo-100 text-indigo-600 p-2 rounded-lg"><IconClipboard className="w-6 h-6" /></div>
                        {t.formsTitle}
                    </h2>
                </div>

                {selectedCustomForm ? (
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden animate-fade-in">
                        <div className="p-6 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
                            <div>
                                <span className="text-xs text-indigo-600 font-bold bg-indigo-50 px-2 py-1 rounded border border-indigo-100">{selectedCustomForm.category}</span>
                                <h3 className="text-xl font-bold text-gray-900 mt-2">{selectedCustomForm.title}</h3>
                                {selectedCustomForm.description && <p className="text-sm text-gray-500 mt-1">{selectedCustomForm.description}</p>}
                            </div>
                            <button onClick={() => setSelectedCustomForm(null)} className="text-gray-500 hover:text-gray-700 bg-white px-4 py-2 rounded-lg border border-gray-200 hover:bg-gray-50">بازگشت</button>
                        </div>
                        <div className="p-8 max-w-3xl mx-auto space-y-6">
                            {selectedCustomForm.fields.map(field => (
                                <div key={field.id} className="space-y-2">
                                    {field.type === 'header' ? (
                                        <h4 className="font-bold text-lg text-gray-800 border-b border-gray-200 pb-2 mt-6">{field.label}</h4>
                                    ) : (
                                        <>
                                            <label className="block text-sm font-bold text-gray-700">
                                                {field.label} {field.required && <span className="text-red-500">*</span>}
                                            </label>
                                            {field.type === 'textarea' ? (
                                                <textarea className="w-full border border-gray-300 rounded-lg p-3 outline-none focus:ring-2 focus:ring-indigo-500" rows={4} placeholder={field.placeholder} />
                                            ) : field.type === 'select' ? (
                                                <select className="w-full border border-gray-300 rounded-lg p-3 outline-none focus:ring-2 focus:ring-indigo-500 bg-white">
                                                    <option value="">-</option>
                                                    {field.options?.map((opt, i) => <option key={i} value={opt}>{opt}</option>)}
                                                </select>
                                            ) : field.type === 'checkbox' ? (
                                                <input type="checkbox" className="w-5 h-5 text-indigo-600 rounded" />
                                            ) : (
                                                <input 
                                                    type={field.type} 
                                                    className="w-full border border-gray-300 rounded-lg p-3 outline-none focus:ring-2 focus:ring-indigo-500" 
                                                    placeholder={field.placeholder} 
                                                />
                                            )}
                                        </>
                                    )}
                                </div>
                            ))}
                            <div className="pt-6 border-t border-gray-100 flex justify-end">
                                <button className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700">ثبت فرم</button>
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {customForms.length > 0 ? customForms.map(form => (
                            <div key={form.id} onClick={() => setSelectedCustomForm(form)} className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm hover:shadow-lg hover:border-indigo-300 transition-all cursor-pointer group">
                                <div className="flex items-start justify-between mb-4">
                                    <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                                        <IconFolder className="w-6 h-6" />
                                    </div>
                                    <span className="text-xs font-bold text-gray-400 bg-gray-50 px-2 py-1 rounded">{form.category}</span>
                                </div>
                                <h3 className="text-lg font-bold text-gray-900 mb-2 group-hover:text-indigo-600 transition-colors">{form.title}</h3>
                                <p className="text-sm text-gray-500 line-clamp-2 h-10">{form.description || 'بدون توضیحات'}</p>
                                <div className="mt-4 pt-4 border-t border-gray-50 flex justify-between items-center text-xs text-gray-400">
                                    <span>{form.fields.length} فیلد</span>
                                    <span className="text-indigo-500 font-bold opacity-0 group-hover:opacity-100 transition-opacity">{t.selectForm} →</span>
                                </div>
                            </div>
                        )) : (
                            <div className="col-span-full py-12 text-center bg-white rounded-2xl border border-dashed border-gray-300">
                                <IconClipboard className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                                <p className="text-gray-500 font-bold">هیچ فرمی برای نمایش وجود ندارد.</p>
                                <p className="text-xs text-gray-400 mt-1">فرم‌های جدید را می‌توانید از بخش تنظیمات ایجاد کنید.</p>
                            </div>
                        )}
                    </div>
                )}
            </div>
        )}

        {activeTab === 'sales' && canAccessSales && <SalesDashboard currentUser={currentUser} personnel={personnel} lang={lang} />}

        {activeTab === 'messages' && <InternalMessenger currentUser={currentUser} personnel={personnel} messages={messages} lang={lang} />}
        {activeTab === 'tasks' && <TaskManager currentUser={currentUser} personnel={personnel} tasks={tasks} lang={lang} />}
        {activeTab === 'meetings' && <MeetingCalendar meetings={meetings} currentUser={currentUser} personnel={personnel} lang={lang} />}
        {activeTab === 'customers' && hasCustomerAccess && <CustomerManager customers={customers} currentUser={currentUser} onUpdate={onUpdateCustomers} onEdit={onEditCustomer} onDelete={onDeleteCustomer} lang={lang} />}
        {activeTab === 'services' && hasTariffAccess && <ServiceManager services={services} onUpdate={onUpdateServices} readonly={!isAdmin && !isMaster} lang={lang} />}
        {activeTab === 'personnel' && isAdmin && <PersonnelManager personnel={personnel} config={config} onUpdate={onUpdatePersonnel} onUpdateConfig={onUpdateConfig} lang={lang} />}
        {activeTab === 'settings' && isAdmin && <SettingsManager config={config} onUpdate={onUpdateConfig} isMaster={isMaster} />}
        {activeTab === 'reports' && isMaster && <PerformanceReports personnel={personnel} tickets={tickets} tasks={tasks} lang={lang} />}
        {activeTab === 'kpi' && isMaster && <KPIManager kpis={kpis} personnel={personnel} lang={lang} />}
        {activeTab === 'logs' && isMaster && (
            <div className="space-y-4 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm"><h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><IconHistory className="w-6 h-6" /> {t.auditLogs}</h2></div>
                <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden"><table className="w-full text-start text-sm"><thead className="bg-gray-50 text-gray-500"><tr><th className="px-4 py-3">{t.time}</th><th className="px-4 py-3">{t.user}</th><th className="px-4 py-3">{t.operation}</th><th className="px-4 py-3">{t.entity}</th><th className="px-4 py-3">{t.details}</th><th className="px-4 py-3">{t.action}</th></tr></thead><tbody className="divide-y divide-gray-100">{systemLogs.map(log => (<tr key={log.id} className="hover:bg-gray-50"><td className="px-4 py-3 text-gray-500 dir-ltr text-right">{new Date(log.timestamp).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</td><td className="px-4 py-3 font-bold text-gray-700">{log.actorName}</td><td className="px-4 py-3"><span className={`px-2 py-1 rounded text-xs font-bold ${log.actionType === 'DELETE' ? 'bg-red-100 text-red-700' : (log.actionType === 'CREATE' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700')}`}>{log.actionType}</span></td><td className="px-4 py-3">{log.entity}</td><td className="px-4 py-3 text-gray-600 truncate max-w-xs" title={log.details}>{log.details}</td><td className="px-4 py-3">{log.actionType === 'DELETE' && log.backupData && (<button onClick={() => handleRestore(log)} className="text-blue-600 hover:bg-blue-50 px-2 py-1 rounded flex items-center gap-1 font-bold text-xs"><IconRefreshCw className="w-3 h-3" /> {t.restore}</button>)}</td></tr>))}</tbody></table>{systemLogs.length === 0 && <div className="p-8 text-center text-gray-400">{t.noLogs}</div>}</div>
            </div>
        )}
        {activeTab === 'financial' && (isAdmin || isMaster) && renderFinancialReport()}
      </div>

      {selectedTicket && renderTicketModal()}
    </div>
  );
};

export enum TicketStatus {
  SUBMITTED = 'ثبت شده',
  PROCESSING = 'در حال بررسی',
  IN_PROGRESS = 'در دست اقدام',
  COMPLETED = 'تکمیل شده',
  CANCELLED = 'لغو شده'
}

export type Currency = 'IRR' | 'OMR' | 'USD';

export interface Price {
  amount: number;
  currency: Currency;
}

export interface AttachedFile {
  name: string;
  size: number;
  type: string;
  content: string; // Base64 or URL or Blob URL
  rawFile?: File; // Direct file reference for efficient upload
  // Upload Status Fields
  status?: 'pending' | 'uploading' | 'success' | 'error';
  progress?: number;
  errorMsg?: string;
}

export interface SaleRecord {
  id: string;
  agentId: string;
  agentName: string;
  amount: number; // Total Sales Amount
  currency: Currency;
  depositDate: string; // YYYY-MM-DD
  targetAccount: string; // e.g., "Mellat - 1234"
  receiptFile?: AttachedFile; // Image of the receipt
  description?: string;
  createdAt: string;
  customerName?: string; 
  // New Calculation Fields
  serviceId?: string;
  serviceName?: string;
  commissionPercentage?: number; // Snapshot of the % at the time of sale
  commissionAmount?: number; // Calculated earnings for the agent/company based on logic
}

export interface SubService {
  id: string;
  title: string;
  titleEn?: string;
  price?: Price;
}

export interface ServiceOption {
  id: string;
  title: string;
  titleEn?: string; // English Title
  description: string;
  descriptionEn?: string; // English Description
  icon: string;
  price?: Price; // Updated to Price Object
  isActive: boolean;
  subServices?: SubService[]; // Nested Services
  commissionPercentage?: number; // New: Default commission/share percentage for this service
}

export interface PersonnelPermissions {
  canAssign: boolean; 
  canViewCustomers: boolean; 
  canViewTariffs: boolean; 
  canViewAllTickets: boolean;
  canIssueInvoices: boolean; // New permission for Invoicing
}

export interface PersonnelDocument {
  id: string;
  title: string;
