import React, { useState } from 'react';
import { ServiceOption, Currency, SubService } from '../types';
import { IconPlus, IconEdit, IconTrash, IconCheck, IconMoney, IconList } from './Icons';
import { Language } from '../App';

interface Props {
  services: ServiceOption[];
  onUpdate: (services: ServiceOption[]) => void;
  readonly?: boolean;
  lang: Language;
}

export const ServiceManager: React.FC<Props> = ({ services, onUpdate, readonly = false, lang }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<ServiceOption>>({ title: '', titleEn: '', description: '', descriptionEn: '', icon: '', price: { amount: 0, currency: 'IRR' }, isActive: true, subServices: [], commissionPercentage: 0 });

  // Sub Service State
  const [newSubTitle, setNewSubTitle] = useState('');
  const [newSubTitleEn, setNewSubTitleEn] = useState('');
  const [newSubPrice, setNewSubPrice] = useState(0);

  const t = {
      fa: {
          title: 'لیست خدمات و تعرفه‌ها',
          add: 'افزودن سرویس و تعرفه جدید',
          edit: 'ویرایش سرویس / تعرفه',
          serviceTitle: 'عنوان سرویس (فارسی)',
          serviceTitleEn: 'عنوان سرویس (انگلیسی)',
          desc: 'توضیحات (فارسی)',
          descEn: 'توضیحات (انگلیسی)',
          icon: 'آیکون (ایموجی)',
          price: 'تعرفه پایه',
          commission: 'درصد کمیسیون/سهم فروش',
          active: 'فعال در فرم مشتری',
          save: 'ذخیره تغییرات',
          create: 'افزودن به لیست',
          cancel: 'انصراف',
          deleteConfirm: 'آیا از حذف این سرویس اطمینان دارید؟',
          tableOrder: 'ترتیب',
          tableIcon: 'آیکون',
          tableTitle: 'عنوان',
          tablePrice: 'تعرفه پایه',
          tableComm: 'کمیسیون',
          tableDesc: 'توضیحات',
          tableStatus: 'وضعیت',
          tableAction: 'عملیات',
          activeLabel: 'فعال',
          inactiveLabel: 'غیرفعال',
          empty: 'لیست خدمات خالی است.',
          subServices: 'زیرمجموعه خدمات (اختیاری)',
          subPlaceholder: 'عنوان زیرمجموعه (مثلا: طراحی لوگو)',
          subPlaceholderEn: 'Sub-service (e.g. Logo)',
          addSub: 'افزودن زیرمجموعه',
          subList: 'لیست زیرمجموعه‌ها'
      },
      en: {
          title: 'Services & Tariffs List',
          add: 'Add New Service',
          edit: 'Edit Service',
          serviceTitle: 'Service Title (Farsi)',
          serviceTitleEn: 'Service Title (English)',
          desc: 'Description (Farsi)',
          descEn: 'Description (English)',
          icon: 'Icon (Emoji)',
          price: 'Base Price',
          commission: 'Commission %',
          active: 'Active in Customer Form',
          save: 'Save Changes',
          create: 'Add to List',
          cancel: 'Cancel',
          deleteConfirm: 'Are you sure you want to delete this service?',
          tableOrder: 'Order',
          tableIcon: 'Icon',
          tableTitle: 'Title',
          tablePrice: 'Base Price',
          tableComm: 'Comm %',
          tableDesc: 'Description',
          tableStatus: 'Status',
          tableAction: 'Action',
          activeLabel: 'Active',
          inactiveLabel: 'Inactive',
          empty: 'Service list is empty.',
          subServices: 'Sub-Services (Optional)',
          subPlaceholder: 'Sub-service title (e.g. Logo Design)',
          subPlaceholderEn: 'Sub-service (EN)',
          addSub: 'Add Sub-service',
          subList: 'Sub-services List'
      }
  }[lang];

  const handleEdit = (service: ServiceOption) => { setEditingId(service.id); setFormData({ ...service, subServices: service.subServices || [] }); };
  const handleDelete = (id: string) => { if (window.confirm(t.deleteConfirm)) { onUpdate(services.filter(s => s.id !== id)); } };
  const handleReset = () => { 
      setEditingId(null); 
      setFormData({ title: '', titleEn: '', description: '', descriptionEn: '', icon: '', price: { amount: 0, currency: 'IRR' }, isActive: true, subServices: [], commissionPercentage: 0 }); 
      setNewSubTitle(''); setNewSubTitleEn(''); setNewSubPrice(0);
  };

  const handleAddSubService = () => {
      if (!newSubTitle.trim()) return;
      const newSub: SubService = {
          id: `sub-${Date.now()}`,
          title: newSubTitle,
          titleEn: newSubTitleEn,
          price: { amount: newSubPrice, currency: formData.price?.currency || 'IRR' }
      };
      setFormData(prev => ({ ...prev, subServices: [...(prev.subServices || []), newSub] }));
      setNewSubTitle('');
      setNewSubTitleEn('');
      setNewSubPrice(0);
  };

  const handleRemoveSubService = (id: string) => {
      setFormData(prev => ({ ...prev, subServices: prev.subServices?.filter(s => s.id !== id) }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.description) return;
    if (editingId) {
      onUpdate(services.map(s => s.id === editingId ? { ...s, ...formData } as ServiceOption : s));
    } else {
      const newService: ServiceOption = { 
          id: `s-${Date.now()}`, 
          title: formData.title!, 
          titleEn: formData.titleEn || formData.title, 
          description: formData.description!, 
          descriptionEn: formData.descriptionEn || formData.description, 
          icon: formData.icon || '✨', 
          price: formData.price, 
          isActive: formData.isActive ?? true,
          subServices: formData.subServices || [],
          commissionPercentage: formData.commissionPercentage || 0
      };
      onUpdate([...services, newService]);
    }
    handleReset();
  };

  const moveService = (index: number, direction: 'up' | 'down') => {
    const newServices = [...services];
    if (direction === 'up' && index > 0) {
      [newServices[index], newServices[index - 1]] = [newServices[index - 1], newServices[index]];
    } else if (direction === 'down' && index < newServices.length - 1) {
      [newServices[index], newServices[index + 1]] = [newServices[index + 1], newServices[index]];
    }
    onUpdate(newServices);
  };

  const formatPrice = (amount: number, currency: Currency) => {
      const currLabel = currency === 'IRR' ? (lang === 'fa' ? 'ریال' : 'IRR') : (currency === 'OMR' ? (lang === 'fa' ? 'عمان' : 'OMR') : (lang === 'fa' ? 'دلار' : 'USD'));
      return `${amount.toLocaleString()} ${currLabel}`;
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {!readonly && (
        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
          <div className="flex items-center gap-3 mb-6"><div className="p-2 bg-blue-100 text-blue-600 rounded-lg">{editingId ? <IconEdit className="w-5 h-5" /> : <IconPlus className="w-5 h-5" />}</div><h3 className="text-lg font-bold text-gray-800">{editingId ? t.edit : t.add}</h3></div>
          <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div><label className="block text-sm font-medium text-gray-700 mb-1">{t.serviceTitle}</label><input type="text" required className="w-full px-4 py-2 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} /></div>
            <div><label className="block text-sm font-medium text-gray-700 mb-1">{t.serviceTitleEn}</label><input type="text" className="w-full px-4 py-2 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none dir-ltr" value={formData.titleEn} onChange={e => setFormData({...formData, titleEn: e.target.value})} /></div>
            <div><label className="block text-sm font-medium text-gray-700 mb-1">{t.icon}</label><input type="text" className="w-full px-4 py-2 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none" placeholder="emoji" value={formData.icon} onChange={e => setFormData({...formData, icon: e.target.value})} /></div>
            <div className="grid grid-cols-2 gap-2">
                <div><label className="block text-sm font-medium text-gray-700 mb-1">{t.price}</label><div className="flex gap-2"><div className="relative flex-grow"><IconMoney className="absolute rtl:right-3 ltr:left-3 top-2.5 w-5 h-5 text-gray-400" /><input type="number" className="w-full rtl:pl-4 rtl:pr-10 ltr:pr-4 ltr:pl-10 py-2 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none" placeholder="0" value={formData.price?.amount || ''} onChange={e => setFormData({ ...formData, price: { amount: parseInt(e.target.value) || 0, currency: formData.price?.currency || 'IRR' } })} /></div></div></div>
                <div><label className="block text-sm font-medium text-gray-700 mb-1">{t.commission}</label><div className="relative"><input type="number" className="w-full px-4 py-2 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none text-center" placeholder="%" value={formData.commissionPercentage || ''} onChange={e => setFormData({ ...formData, commissionPercentage: parseFloat(e.target.value) || 0 })} /><span className="absolute left-3 top-2 text-gray-400">%</span></div></div>
            </div>
            <div className="md:col-span-2"><label className="block text-sm font-medium text-gray-700 mb-1">{t.desc}</label><input type="text" required className="w-full px-4 py-2 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} /></div>
            <div className="md:col-span-2"><label className="block text-sm font-medium text-gray-700 mb-1">{t.descEn}</label><input type="text" className="w-full px-4 py-2 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none dir-ltr" value={formData.descriptionEn} onChange={e => setFormData({...formData, descriptionEn: e.target.value})} /></div>

            {/* Sub Services Section */}
            <div className="md:col-span-2 bg-gray-50 p-4 rounded-xl border border-gray-200">
                <h4 className="font-bold text-gray-700 mb-3 flex items-center gap-2 text-sm"><IconList className="w-4 h-4" /> {t.subServices}</h4>
                <div className="flex flex-wrap gap-2 mb-3">
                    <input className="flex-grow px-3 py-2 rounded-lg border border-gray-300 text-sm outline-none" placeholder={t.subPlaceholder} value={newSubTitle} onChange={e => setNewSubTitle(e.target.value)} />
                    <input className="flex-grow px-3 py-2 rounded-lg border border-gray-300 text-sm outline-none dir-ltr" placeholder={t.subPlaceholderEn} value={newSubTitleEn} onChange={e => setNewSubTitleEn(e.target.value)} />
                    <input type="number" className="w-24 px-3 py-2 rounded-lg border border-gray-300 text-sm outline-none" placeholder="Price" value={newSubPrice || ''} onChange={e => setNewSubPrice(parseInt(e.target.value))} />
                    <button type="button" onClick={handleAddSubService} className="bg-indigo-600 text-white px-3 rounded-lg text-sm font-bold hover:bg-indigo-700">{t.addSub}</button>
                </div>
                <div className="space-y-2">
                    {formData.subServices?.map((sub) => (
                        <div key={sub.id} className="flex justify-between items-center bg-white p-2 rounded border border-gray-200 text-sm">
                            <span>{sub.title} {sub.titleEn ? `(${sub.titleEn})` : ''} {sub.price?.amount ? ` - ${formatPrice(sub.price.amount, sub.price.currency)}` : ''}</span>
                            <button type="button" onClick={() => handleRemoveSubService(sub.id)} className="text-red-500 hover:text-red-700"><IconTrash className="w-4 h-4" /></button>
                        </div>
                    ))}
                </div>
            </div>

            <div className="flex items-center gap-4 mt-2"><label className="flex items-center gap-2 cursor-pointer"><input type="checkbox" checked={formData.isActive} onChange={e => setFormData({...formData, isActive: e.target.checked})} className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"/><span className="text-sm text-gray-700">{t.active}</span></label></div>
            <div className="md:col-span-2 flex justify-end gap-3 mt-4">{editingId && (<button type="button" onClick={handleReset} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg transition-colors">{t.cancel}</button>)}<button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200">{editingId ? t.save : t.create}</button></div>
          </form>
        </div>
      )}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex justify-between items-center"><h3 className="font-bold text-gray-800">{t.title}</h3>{readonly && <span className="text-xs bg-gray-100 text-gray-500 px-2 py-1 rounded">Read-only</span>}</div>
        <div className="overflow-x-auto"><table className="w-full text-start"><thead className="bg-gray-50 text-gray-500 text-sm"><tr>{!readonly && <th className="px-6 py-3 w-16 text-center">{t.tableOrder}</th>}<th className="px-6 py-3">{t.tableIcon}</th><th className="px-6 py-3">{t.tableTitle}</th><th className="px-6 py-3">{t.tablePrice}</th><th className="px-6 py-3 text-center">{t.tableComm}</th><th className="px-6 py-3">{t.tableDesc}</th><th className="px-6 py-3">{t.tableStatus}</th>{!readonly && <th className="px-6 py-3">{t.tableAction}</th>}</tr></thead><tbody className="divide-y divide-gray-100">{services.map((service, index) => (<tr key={service.id} className="hover:bg-gray-50 group">
            {!readonly && (
                <td className="px-6 py-4 text-center">
                    <div className="flex flex-col items-center gap-1">
                        <button onClick={() => moveService(index, 'up')} disabled={index === 0} className="w-6 h-6 flex items-center justify-center rounded hover:bg-gray-200 text-gray-400 hover:text-indigo-600 disabled:opacity-20 transition-colors">▲</button>
                        <button onClick={() => moveService(index, 'down')} disabled={index === services.length - 1} className="w-6 h-6 flex items-center justify-center rounded hover:bg-gray-200 text-gray-400 hover:text-indigo-600 disabled:opacity-20 transition-colors">▼</button>
                    </div>
                </td>
            )}
            <td className="px-6 py-4 text-2xl">{service.icon}</td><td className="px-6 py-4"><div className="font-bold text-gray-800">{lang === 'en' ? service.titleEn : service.title}</div>{service.subServices && service.subServices.length > 0 && <span className="text-xs text-gray-400">{service.subServices.length} sub-services</span>}</td><td className="px-6 py-4 font-mono font-bold text-indigo-600">{formatPrice(service.price?.amount || 0, service.price?.currency || 'IRR')}</td><td className="px-6 py-4 text-center"><span className="bg-amber-100 text-amber-800 px-2 py-1 rounded text-xs font-bold">{service.commissionPercentage || 0}%</span></td><td className="px-6 py-4 text-sm text-gray-600 max-w-xs truncate">{lang === 'en' ? service.descriptionEn : service.description}</td><td className="px-6 py-4"><span className={`px-2 py-1 rounded text-xs ${service.isActive ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{service.isActive ? t.activeLabel : t.inactiveLabel}</span></td>{!readonly && (<td className="px-6 py-4"><div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleEdit(service)} className="p-2 bg-blue-50 text-blue-600 rounded hover:bg-blue-100"><IconEdit className="w-4 h-4" /></button><button onClick={() => handleDelete(service.id)} className="p-2 bg-red-50 text-red-600 rounded hover:bg-red-100"><IconTrash className="w-4 h-4" /></button></div></td>)}</tr>))}</tbody></table>{services.length === 0 && <div className="p-8 text-center text-gray-400">{t.empty}</div>}</div></div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { SaleRecord, Personnel, Currency, AttachedFile, ServiceOption } from '../types';
import { IconTag, IconPlus, IconTrophy, IconMoney, IconCalendar, IconEdit, IconTrash, IconReceipt, IconCheck, IconBriefcase } from './Icons';
import { saveSaleToCloud, updateSaleInCloud, deleteSaleFromCloud, subscribeToSales, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  services: ServiceOption[]; // Add services prop
  lang: Language;
}

export const SalesDashboard: React.FC<Props> = ({ currentUser, personnel, services, lang }) => {
  const [sales, setSales] = useState<SaleRecord[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [activeTab, setActiveTab] = useState<'leaderboard' | 'history'>('leaderboard');
  const [isEditing, setIsEditing] = useState(false);

  // Form State
  const [formData, setFormData] = useState<Partial<SaleRecord>>({
      amount: 0,
      currency: 'IRR',
      depositDate: new Date().toISOString().split('T')[0],
      targetAccount: '',
      description: '',
      customerName: '',
      serviceId: '',
      serviceName: '',
      commissionPercentage: 0,
      commissionAmount: 0
  });
  const [receiptFile, setReceiptFile] = useState<AttachedFile | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isMaster = currentUser.username === 'master';

  const t = {
      fa: {
          title: 'داشبورد فروش و عملکرد',
          leaderboard: 'لیدربورد (برترین‌ها)',
          history: 'سوابق فروش',
          add: 'ثبت فروش جدید',
          edit: 'ویرایش فروش',
          deleteConfirm: 'آیا از حذف این رکورد اطمینان دارید؟',
          amount: 'مبلغ فروش',
          date: 'تاریخ واریز',
          account: 'حساب مقصد (شماره کارت/شبا)',
          desc: 'توضیحات تکمیلی',
          customer: 'نام مشتری',
          receipt: 'تصویر فیش واریزی',
          upload: 'آپلود فیش',
          save: 'ثبت نهایی',
          cancel: 'انصراف',
          totalSales: 'فروش کل',
          count: 'تعداد',
          rial: 'ریال',
          rank: 'رتبه',
          agent: 'فروشنده',
          viewReceipt: 'مشاهده فیش',
          noSales: 'هنوز فروشی ثبت نشده است.',
          masterOnly: 'فقط مدیریت ارشد امکان ویرایش دارد',
          selectService: 'انتخاب سرویس مرتبط',
          service: 'سرویس',
          commissionInfo: 'محاسبات سهم/کمیسیون',
          commPercent: 'درصد سهم',
          commAmount: 'مبلغ سهم'
      },
      en: {
          title: 'Sales Performance Dashboard',
          leaderboard: 'Leaderboard',
          history: 'Sales History',
          add: 'Record New Sale',
          edit: 'Edit Sale',
          deleteConfirm: 'Are you sure you want to delete this record?',
          amount: 'Sale Amount',
          date: 'Deposit Date',
          account: 'Target Account',
          desc: 'Description',
          customer: 'Customer Name',
          receipt: 'Receipt Image',
          upload: 'Upload Receipt',
          save: 'Save Record',
          cancel: 'Cancel',
          totalSales: 'Total Revenue',
          count: 'Count',
          rial: 'IRR',
          rank: 'Rank',
          agent: 'Agent',
          viewReceipt: 'View Receipt',
          noSales: 'No sales recorded yet.',
          masterOnly: 'Edit restricted to Master Admin',
          selectService: 'Select Related Service',
          service: 'Service',
          commissionInfo: 'Commission/Share Calculation',
          commPercent: 'Share %',
          commAmount: 'Share Amount'
      }
  }[lang];

  useEffect(() => {
      const unsub = subscribeToSales(setSales);
      return () => unsub();
  }, []);

  // Auto-calculate commission when amount or percentage changes
  useEffect(() => {
      if (formData.amount && formData.commissionPercentage !== undefined) {
          const comm = Math.round(formData.amount * (formData.commissionPercentage / 100));
          setFormData(prev => ({ ...prev, commissionAmount: comm }));
      }
  }, [formData.amount, formData.commissionPercentage]);

  const handleServiceChange = (serviceId: string) => {
      const service = services.find(s => s.id === serviceId);
      if (service) {
          setFormData(prev => ({
              ...prev,
              serviceId: service.id,
              serviceName: service.title,
              commissionPercentage: service.commissionPercentage || 0
          }));
      } else {
          setFormData(prev => ({ ...prev, serviceId: '', serviceName: '', commissionPercentage: 0 }));
      }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      if (file.size > 5 * 1024 * 1024) { alert('Max 5MB'); return; }

      const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
      setReceiptFile(newFile);

      uploadFileWithProgress(
          file,
          (p) => setReceiptFile(prev => prev ? { ...prev, progress: p } : null),
          (url) => setReceiptFile(prev => prev ? { ...prev, content: url, status: 'success', progress: 100 } : null),
          (err) => setReceiptFile(prev => prev ? { ...prev, status: 'error' } : null)
      );
  };

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.amount || !formData.targetAccount || !receiptFile || receiptFile.status !== 'success') {
          alert('Please fill all fields and upload receipt.');
          return;
      }

      const saleData: SaleRecord = {
          id: formData.id || `sale-${Date.now()}`,
          agentId: formData.agentId || currentUser.id,
          agentName: formData.agentName || currentUser.fullName,
          amount: Number(formData.amount),
          currency: formData.currency || 'IRR',
          depositDate: formData.depositDate!,
          targetAccount: formData.targetAccount!,
          description: formData.description,
          customerName: formData.customerName,
          receiptFile: receiptFile,
          createdAt: formData.createdAt || new Date().toISOString(),
          // New Fields
          serviceId: formData.serviceId,
          serviceName: formData.serviceName,
          commissionPercentage: formData.commissionPercentage,
          commissionAmount: formData.commissionAmount
      };

      if (isEditing && isMaster && formData.id) {
          await updateSaleInCloud(formData.id, saleData, currentUser.fullName);
      } else {
          await saveSaleToCloud(saleData);
      }

      setShowModal(false);
      resetForm();
  };

  const handleEdit = (sale: SaleRecord) => {
      if (!isMaster) return; // double check
      setFormData(sale);
      setReceiptFile(sale.receiptFile || null);
      setIsEditing(true);
      setShowModal(true);
  };

  const handleDelete = async (id: string) => {
      if (!isMaster) return;
      if (window.confirm(t.deleteConfirm)) {
          await deleteSaleFromCloud(id, currentUser.fullName);
      }
  };

  const resetForm = () => {
      setFormData({ amount: 0, currency: 'IRR', depositDate: new Date().toISOString().split('T')[0], targetAccount: '', description: '', customerName: '', serviceId: '', serviceName: '', commissionPercentage: 0, commissionAmount: 0 });
      setReceiptFile(null);
      setIsEditing(false);
  };

  // Logic for Leaderboard
  const calculateLeaderboard = () => {
      const stats: Record<string, { name: string, total: number, count: number }> = {};
      sales.forEach(sale => {
          if (!stats[sale.agentId]) {
              stats[sale.agentId] = { name: sale.agentName, total: 0, count: 0 };
          }
          // Assuming IRR for basic sorting, advanced version would convert currencies
          stats[sale.agentId].total += sale.amount;
          stats[sale.agentId].count += 1;
      });
      return Object.values(stats).sort((a, b) => b.total - a.total);
  };

  const leaderboard = calculateLeaderboard();

  return (
    <div className="space-y-6 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4">
            <div>
                <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                    <div className="bg-emerald-100 text-emerald-600 p-2 rounded-lg"><IconTag className="w-6 h-6" /></div>
                    {t.title}
                </h2>
            </div>
            <div className="flex gap-2">
                <div className="flex bg-gray-100 p-1 rounded-lg">
                    <button onClick={() => setActiveTab('leaderboard')} className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'leaderboard' ? 'bg-white shadow text-emerald-600' : 'text-gray-500'}`}><IconTrophy className="w-4 h-4" /> {t.leaderboard}</button>
                    <button onClick={() => setActiveTab('history')} className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'history' ? 'bg-white shadow text-emerald-600' : 'text-gray-500'}`}><IconCalendar className="w-4 h-4" /> {t.history}</button>
                </div>
                <button onClick={() => { resetForm(); setShowModal(true); }} className="bg-emerald-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-emerald-700 flex items-center gap-2 shadow-lg shadow-emerald-200">
                    <IconPlus className="w-5 h-5" /> {t.add}
                </button>
            </div>
        </div>

        {activeTab === 'leaderboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Top 3 Cards */}
                {leaderboard.slice(0, 3).map((agent, index) => (
                    <div key={index} className={`relative overflow-hidden rounded-3xl p-6 shadow-lg border-2 ${index === 0 ? 'bg-gradient-to-br from-yellow-50 to-amber-100 border-amber-300' : index === 1 ? 'bg-gradient-to-br from-gray-50 to-gray-200 border-gray-300' : 'bg-gradient-to-br from-orange-50 to-orange-100 border-orange-200'}`}>
                        <div className="absolute top-0 right-0 p-4 opacity-20"><IconTrophy className={`w-24 h-24 ${index === 0 ? 'text-amber-500' : index === 1 ? 'text-gray-500' : 'text-orange-600'}`} /></div>
                        <div className="relative z-10 text-center">
                            <div className={`w-12 h-12 mx-auto rounded-full flex items-center justify-center text-xl font-bold mb-3 ${index === 0 ? 'bg-amber-400 text-white' : index === 1 ? 'bg-gray-400 text-white' : 'bg-orange-400 text-white'}`}>{index + 1}</div>
                            <h3 className="text-xl font-black text-gray-800 mb-1">{agent.name}</h3>
                            <div className="text-3xl font-black text-gray-900 my-4">{agent.total.toLocaleString()} <span className="text-sm text-gray-500 font-normal">{t.rial}</span></div>
                            <div className="inline-block bg-white/50 px-3 py-1 rounded-lg text-sm font-bold text-gray-600">{agent.count} {t.count}</div>
                        </div>
                    </div>
                ))}

                {/* Rest of the list */}
                {leaderboard.length > 3 && (
                    <div className="col-span-full bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-50 text-gray-500">
                                <tr>
                                    <th className="px-4 py-3 text-start">{t.rank}</th>
                                    <th className="px-4 py-3 text-start">{t.agent}</th>
                                    <th className="px-4 py-3 text-center">{t.count}</th>
                                    <th className="px-4 py-3 text-end">{t.totalSales}</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {leaderboard.slice(3).map((agent, idx) => (
                                    <tr key={idx}>
                                        <td className="px-4 py-3 font-bold text-gray-400">#{idx + 4}</td>
                                        <td className="px-4 py-3 font-bold text-gray-800">{agent.name}</td>
                                        <td className="px-4 py-3 text-center">{agent.count}</td>
                                        <td className="px-4 py-3 text-end font-mono font-bold text-gray-700">{agent.total.toLocaleString()}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {leaderboard.length === 0 && <div className="col-span-full text-center py-12 text-gray-400">{t.noSales}</div>}
            </div>
        )}

        {activeTab === 'history' && (
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-start text-sm">
                        <thead className="bg-gray-50 text-gray-500">
                            <tr>
                                <th className="px-6 py-4">{t.date}</th>
                                <th className="px-6 py-4">{t.agent}</th>
                                <th className="px-6 py-4">{t.customer}</th>
                                <th className="px-6 py-4">{t.service}</th>
                                <th className="px-6 py-4">{t.amount}</th>
                                <th className="px-6 py-4">{t.account}</th>
                                <th className="px-6 py-4 text-center">{t.receipt}</th>
                                {isMaster && <th className="px-6 py-4 text-center">Action</th>}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {sales.map((sale) => (
                                <tr key={sale.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 font-mono dir-ltr text-right text-gray-600">{new Date(sale.depositDate).toLocaleDateString('fa-IR')}</td>
                                    <td className="px-6 py-4 font-bold text-gray-800">{sale.agentName}</td>
                                    <td className="px-6 py-4 text-gray-600">{sale.customerName || '-'}</td>
                                    <td className="px-6 py-4">
                                        {sale.serviceName ? (
                                            <span className="inline-flex items-center gap-1 bg-indigo-50 text-indigo-700 px-2 py-1 rounded text-xs font-bold border border-indigo-100">
                                                <IconBriefcase className="w-3 h-3" /> {sale.serviceName}
                                            </span>
                                        ) : '-'}
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="font-black text-emerald-600">{sale.amount.toLocaleString()} <span className="text-[10px] font-normal text-gray-400">{sale.currency}</span></div>
                                        {sale.commissionAmount ? (
                                            <div className="text-[10px] text-gray-400 mt-1">Share: {sale.commissionAmount.toLocaleString()} ({sale.commissionPercentage}%)</div>
                                        ) : null}
                                    </td>
                                    <td className="px-6 py-4 text-gray-600 font-mono text-xs">{sale.targetAccount}</td>
                                    <td className="px-6 py-4 text-center">
                                        {sale.receiptFile ? (
                                            <a href={sale.receiptFile.content} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-blue-600 bg-blue-50 px-2 py-1 rounded text-xs hover:bg-blue-100">
                                                <IconReceipt className="w-3 h-3" /> {t.viewReceipt}
                                            </a>
                                        ) : '-'}
                                    </td>
                                    {isMaster && (
                                        <td className="px-6 py-4 text-center">
                                            <div className="flex justify-center gap-2">
                                                <button onClick={() => handleEdit(sale)} className="text-gray-400 hover:text-blue-600"><IconEdit className="w-4 h-4" /></button>
                                                <button onClick={() => handleDelete(sale.id)} className="text-gray-400 hover:text-red-600"><IconTrash className="w-4 h-4" /></button>
                                            </div>
                                        </td>
                                    )}
                                </tr>
                            ))}
                            {sales.length === 0 && <tr><td colSpan={8} className="text-center py-8 text-gray-400">{t.noSales}</td></tr>}
                        </tbody>
                    </table>
                </div>
            </div>
        )}

        {/* Modal */}
        {showModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in flex flex-col max-h-[90vh]">
                    <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-emerald-50 rounded-t-2xl">
                        <h3 className="font-bold text-emerald-900">{isEditing ? t.edit : t.add}</h3>
                        <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600">✕</button>
                    </div>
