                                </div>
                            </div>
                        </form>
                    </div>
                    <div className="p-4 border-t border-gray-100 flex justify-end gap-3 bg-gray-50 rounded-b-2xl">
                        <button onClick={() => setShowModal(false)} className="px-4 py-2 text-gray-600 font-bold hover:bg-gray-200 rounded-lg transition-colors">{t.cancel}</button>
                        <button type="submit" form="sales-form" disabled={!receiptFile || receiptFile.status === 'uploading'} className="bg-emerald-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-emerald-700 disabled:opacity-50 shadow-lg shadow-emerald-200">{t.save}</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

