          case TicketStatus.PROCESSING: return 'bg-yellow-100 text-yellow-700';
          case TicketStatus.IN_PROGRESS: return 'bg-purple-100 text-purple-700';
          case TicketStatus.COMPLETED: return 'bg-green-100 text-green-700';
          case TicketStatus.CANCELLED: return 'bg-red-100 text-red-700';
          default: return 'bg-gray-100 text-gray-700';
      }
  };

  const formatNumberInput = (val: string) => val.replace(/[^0-9]/g, '');

  // Event Handlers
  const handleSaveInvoice = async (invoice: Invoice) => {
      if (!selectedTicket) return;

      const currentProjectData = selectedTicket.projectData || {
          isActive: false,
          tariff: { amount: 0, currency: 'IRR' },
          startDate: '',
          endDate: '',
          teamMemberIds: [],
          projectFiles: [],
          payments: [],
          invoices: [],
          progress: 0
      } as ProjectDetails;

      const updatedInvoices = [...(currentProjectData.invoices || [])];
      const existingIndex = updatedInvoices.findIndex(inv => inv.id === invoice.id);

      if (existingIndex >= 0) {
          updatedInvoices[existingIndex] = invoice;
      } else {
          updatedInvoices.push(invoice);
      }

      await onUpdateTicket(selectedTicket.id, { 
          projectData: { ...currentProjectData, invoices: updatedInvoices } 
      }, currentUser.fullName, `فاکتور ${invoice.number} صادر/ویرایش شد.`);

      setShowInvoiceModal(false);
  };

  const handleProjectModalClose = () => {
      setShowNewProjectModal(false);
      setCreatedProjectId(null);
      setNewProjectData({
          title: '',
          serviceId: '',
          customerName: '',
          phoneNumber: '',
          startDate: '',
          endDate: '',
          tariffAmount: '',
          tariffCurrency: 'IRR',
          priority: 'Medium'
      });
  };

  const handleCreateProject = async (e: React.FormEvent) => {
      e.preventDefault();

      const newId = `PRJ-${Math.floor(1000 + Math.random() * 9000)}`;

      const newTicket: Ticket = {
          id: newId,
          customerName: newProjectData.customerName,
          phoneNumber: newProjectData.phoneNumber,
          whatsappNumber: newProjectData.phoneNumber,
          location: '',
          serviceId: newProjectData.serviceId,
          status: TicketStatus.IN_PROGRESS,
          description: `پروژه جدید: ${newProjectData.title}`,
          createdAt: new Date().toISOString(),
          priority: newProjectData.priority,
          timeline: [
              {
                  type: 'creation',
                  title: 'ایجاد پروژه',
                  description: `پروژه با عنوان "${newProjectData.title}" ایجاد شد.`,
                  actorName: currentUser.fullName,
                  timestamp: new Date().toISOString(),
                  visibility: 'public'
              }
          ],
          projectData: {
              isActive: true,
              tariff: { amount: parseInt(newProjectData.tariffAmount) || 0, currency: newProjectData.tariffCurrency },
              startDate: newProjectData.startDate,
              endDate: newProjectData.endDate,
              teamMemberIds: [currentUser.id],
              projectFiles: [],
              payments: [],
              progress: 0,
              milestones: [],
              risks: [],
              teamMembers: []
          },
          selectedSubServices: []
      };

      await onCreateTicket(newTicket);
      setCreatedProjectId(newId);
  };

  const handleRestore = async (log: SystemLog) => {
      if (window.confirm(t.deleteConfirm)) {
          const success = await restoreEntityFromLog(log);
          if (success) {
              alert('بازیابی با موفقیت انجام شد.');
          } else {
              alert('خطا در بازیابی.');
          }
      }
  };

  const renderFinancialReport = () => {
      const totalRevenue = tickets.reduce((acc, t) => {
          if (t.projectData?.invoices) {
              return acc + t.projectData.invoices.reduce((sum, inv) => sum + inv.total, 0);
          }
          return acc;
      }, 0);

      return (
          <div className="space-y-6 animate-fade-in">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                      <h3 className="text-gray-500 text-sm font-bold mb-2">{t.revenueTotal}</h3>
                      <div className="text-3xl font-black text-indigo-600">{totalRevenue.toLocaleString()} <span className="text-sm font-normal text-gray-400">IRR (Approx)</span></div>
                  </div>
              </div>
              <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                  <h3 className="font-bold text-gray-800 mb-4">{t.revenueByService}</h3>
                  <div className="text-center text-gray-400 py-8">Chart Placeholder</div>
              </div>
          </div>
      );
  };

  const renderTicketModal = () => {
      if (!selectedTicket) return null;

      return (
