                  <div className="flex justify-between items-center p-6 border-b border-gray-100 bg-white z-10">
                      <div className="flex items-center gap-4">
                          <div className="bg-indigo-50 text-indigo-600 p-3 rounded-xl">
                              <IconBriefcase className="w-6 h-6" />
                          </div>
                          <div>
                              <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                                  {selectedTicket.customerName}
                                  <span className={`text-xs px-2 py-1 rounded-full ${getStatusBadge(selectedTicket.status)}`}>{selectedTicket.status}</span>
                              </h2>
                              <p className="text-sm text-gray-500 font-mono mt-1">{selectedTicket.id} | {new Date(selectedTicket.createdAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</p>
                          </div>
                      </div>
                      <button onClick={() => setSelectedTicketId(null)} className="p-2 hover:bg-gray-100 rounded-full transition-colors">✕</button>
                  </div>

                  <div className="flex border-b border-gray-100 px-6">
                      <button onClick={() => setActiveModalTab('info')} className={`px-6 py-4 font-bold text-sm border-b-2 transition-colors ${activeModalTab === 'info' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>{t.ticketInfo}</button>
                      <button onClick={() => setActiveModalTab('project')} className={`px-6 py-4 font-bold text-sm border-b-2 transition-colors ${activeModalTab === 'project' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>{t.projectMgmt}</button>
                  </div>

