                          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                              <div className="md:col-span-1 space-y-6">
                                  <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                                      <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2"><IconUsers className="w-5 h-5 text-indigo-500" /> {t.customerInfo}</h3>
                                      <div className="space-y-3 text-sm">
                                          <div className="flex justify-between"><span className="text-gray-500">{t.fullName}</span><span className="font-medium">{selectedTicket.customerName}</span></div>
                                          <div className="flex justify-between"><span className="text-gray-500">{t.company}</span><span className="font-medium">{selectedTicket.companyName || '-'}</span></div>
                                          <div className="flex justify-between"><span className="text-gray-500">{t.mobile}</span><span className="font-medium dir-ltr">{selectedTicket.phoneNumber}</span></div>
                                          {selectedTicket.whatsappNumber && <div className="flex justify-between"><span className="text-gray-500">{t.whatsapp}</span><span className="font-medium dir-ltr">{selectedTicket.whatsappNumber}</span></div>}
                                          <div className="flex justify-between"><span className="text-gray-500">{t.location}</span><span className="font-medium">{selectedTicket.location}</span></div>
                                          <div className="flex justify-between"><span className="text-gray-500">{t.bizType}</span><span className="font-medium">{selectedTicket.businessType}</span></div>
                                      </div>
                                  </div>

                                  <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                                      <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2"><IconShield className="w-5 h-5 text-purple-500" /> {t.expert}</h3>
                                      {canAssign ? (
                                          <div className="flex gap-2">
                                              <select 
