                                              </select>
                                              <button 
                                                  onClick={() => {
                                                      if(tempAssignedTo && tempAssignedTo !== selectedTicket.assignedTo) {
                                                          const expertName = personnel.find(p => p.id === tempAssignedTo)?.fullName || 'Unknown';
                                                          onUpdateTicket(selectedTicket.id, { assignedTo: tempAssignedTo, status: TicketStatus.PROCESSING }, currentUser.fullName, `پرونده به ${expertName} ارجاع شد.`);
                                                      }
                                                  }}
                                                  className="bg-purple-600 text-white px-3 rounded-lg text-sm font-bold hover:bg-purple-700"
                                              >
                                                  {t.assign}
                                              </button>
                                          </div>
                                      ) : (
                                          <div className="text-sm font-medium text-gray-700">
                                              {selectedTicket.assignedTo ? personnel.find(p => p.id === selectedTicket.assignedTo)?.fullName : t.notAssigned}
                                          </div>
                                      )}
                                  </div>
                              </div>

                              <div className="md:col-span-2 space-y-6">
                                  <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                                      <div className="flex justify-between items-start mb-4">
                                          <h3 className="font-bold text-gray-800 flex items-center gap-2"><IconFile className="w-5 h-5 text-blue-500" /> {t.description}</h3>
                                          <select 
                                              className="bg-gray-100 text-gray-700 text-xs font-bold px-3 py-1.5 rounded-lg border-transparent focus:border-gray-300 outline-none"
