                                      </div>
                                      <p className="text-gray-700 leading-relaxed text-sm whitespace-pre-wrap">{selectedTicket.description}</p>

                                      {selectedTicket.selectedSubServices && selectedTicket.selectedSubServices.length > 0 && (
