                                      <div className="mt-4 pt-4 border-t border-gray-100">
                                          <div className="flex gap-2 mb-2">
                                              <button onClick={() => setCommentVisibility('public')} className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-colors ${commentVisibility === 'public' ? 'bg-blue-100 text-blue-700' : 'bg-gray-50 text-gray-500'}`}>{t.publicReport}</button>
                                              <button onClick={() => setCommentVisibility('internal')} className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition-colors ${commentVisibility === 'internal' ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-50 text-gray-500'}`}>{t.internalNote}</button>
                                          </div>
                                          <div className="relative">
                                              <textarea 
                                                  className={`w-full p-3 rounded-xl border outline-none text-sm min-h-[80px] ${commentVisibility === 'internal' ? 'bg-yellow-50 border-yellow-200 focus:ring-yellow-500' : 'bg-white border-gray-200 focus:ring-blue-500'} focus:ring-2`}
                                                  placeholder={t.writeMsg}
                                                  value={newComment}
                                                  onChange={(e) => setNewComment(e.target.value)}
                                                  onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), onUpdateTicket(selectedTicket.id, {}, currentUser.fullName, newComment, commentVisibility), setNewComment(''))} 
                                              />
                                              <div className="flex justify-between items-center mt-2">
                                                  <button onClick={() => setShowMentionList(!showMentionList)} className="text-gray-400 hover:text-blue-600 p-1 rounded hover:bg-blue-50">@ Mention</button>
                                                  <button 
                                                      onClick={() => {
                                                          if(newComment.trim()) {
                                                              onUpdateTicket(selectedTicket.id, {}, currentUser.fullName, newComment, commentVisibility);
                                                              setNewComment('');
                                                          }
                                                      }}
                                                      disabled={!newComment.trim()}
                                                      className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-indigo-700 disabled:opacity-50"
                                                  >
                                                      {t.send}
                                                  </button>
                                              </div>
                                              {showMentionList && (
                                                  <div className="absolute bottom-full left-0 mb-2 w-48 bg-white border border-gray-200 rounded-xl shadow-xl max-h-40 overflow-y-auto z-20">
                                                      {personnel.map(p => (
                                                          <button 
                                                              key={p.id} 
                                                              className="w-full text-start px-3 py-2 text-xs hover:bg-gray-50 text-gray-700 border-b border-gray-50 last:border-0"
                                                              onClick={() => {
                                                                  setNewComment(prev => prev + `@${p.username} `);
                                                                  setShowMentionList(false);
                                                              }}
                                                          >
                                                              {p.fullName}
                                                          </button>
                                                      ))}
                                                  </div>
                                              )}
                                          </div>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      ) : (
                          <div className="space-y-6">
                              <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 text-center">
                                  <IconProject className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                                  <h3 className="text-lg font-bold text-gray-800">Project Management Module</h3>
                                  <p className="text-gray-500">This section allows detailed project tracking, milestones, and financial management.</p>
                              </div>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      );
  };

  return (
    <div className="flex flex-col md:flex-row gap-6 min-h-[calc(100vh-100px)]">
      {/* ... (Invoice Modal & New Project Modal logic remains same) */}
      {showInvoiceModal && selectedTicket && (
          <InvoiceModal 
             customer={{ id: selectedTicket.customerName, fullName: selectedTicket.customerName, companyName: selectedTicket.companyName, location: selectedTicket.location, phoneNumber: selectedTicket.phoneNumber, whatsappNumber: selectedTicket.whatsappNumber, firstContact: '', totalTickets: 0 }}
             template={config.invoiceTemplate || { companyName: config.appTitle, address: '', phone: '', footerText: '', termsConditions: '', defaultTaxRate: 0, colorTheme: '#4f46e5' }}
             initialData={editingInvoice}
             onSave={handleSaveInvoice}
             onClose={() => setShowInvoiceModal(false)}
          />
      )}

      {showNewProjectModal && (
          // ... (Existing New Project Modal Code)
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
              <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in overflow-hidden">
