        {activeTab === 'settings' && isAdmin && <SettingsManager config={config} onUpdate={onUpdateConfig} isMaster={isMaster} />}
        {activeTab === 'reports' && isMaster && <PerformanceReports personnel={personnel} tickets={tickets} tasks={tasks} lang={lang} />}
        {activeTab === 'kpi' && isMaster && <KPIManager kpis={kpis} personnel={personnel} lang={lang} />}
        {activeTab === 'logs' && isMaster && (
            <div className="space-y-4 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm"><h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><IconHistory className="w-6 h-6" /> {t.auditLogs}</h2></div>
                <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden"><table className="w-full text-start text-sm"><thead className="bg-gray-50 text-gray-500"><tr><th className="px-4 py-3">{t.time}</th><th className="px-4 py-3">{t.user}</th><th className="px-4 py-3">{t.operation}</th><th className="px-4 py-3">{t.entity}</th><th className="px-4 py-3">{t.details}</th><th className="px-4 py-3">{t.action}</th></tr></thead><tbody className="divide-y divide-gray-100">{systemLogs.map(log => (<tr key={log.id} className="hover:bg-gray-50"><td className="px-4 py-3 text-gray-500 dir-ltr text-right">{new Date(log.timestamp).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</td><td className="px-4 py-3 font-bold text-gray-700">{log.actorName}</td><td className="px-4 py-3"><span className={`px-2 py-1 rounded text-xs font-bold ${log.actionType === 'DELETE' ? 'bg-red-100 text-red-700' : (log.actionType === 'CREATE' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700')}`}>{log.actionType}</span></td><td className="px-4 py-3">{log.entity}</td><td className="px-4 py-3 text-gray-600 truncate max-w-xs" title={log.details}>{log.details}</td><td className="px-4 py-3">{log.actionType === 'DELETE' && log.backupData && (<button onClick={() => handleRestore(log)} className="text-blue-600 hover:bg-blue-50 px-2 py-1 rounded flex items-center gap-1 font-bold text-xs"><IconRefreshCw className="w-3 h-3" /> {t.restore}</button>)}</td></tr>))}</tbody></table>{systemLogs.length === 0 && <div className="p-8 text-center text-gray-400">{t.noLogs}</div>}</div>
            </div>
        )}
        {activeTab === 'financial' && (isAdmin || isMaster) && renderFinancialReport()}
      </div>

      {selectedTicket && renderTicketModal()}
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { SaleRecord, Personnel, Currency, AttachedFile, ServiceOption } from '../types';
import { IconTag, IconPlus, IconTrophy, IconMoney, IconCalendar, IconEdit, IconTrash, IconReceipt, IconCheck, IconBriefcase, IconUsers, IconChart, IconSearch } from './Icons';
import { saveSaleToCloud, updateSaleInCloud, deleteSaleFromCloud, subscribeToSales, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  services: ServiceOption[];
  lang: Language;
}

export const SalesDashboard: React.FC<Props> = ({ currentUser, personnel, services, lang }) => {
  const [allSales, setAllSales] = useState<SaleRecord[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [activeTab, setActiveTab] = useState<'leaderboard' | 'history'>('leaderboard');
  const [isEditing, setIsEditing] = useState(false);
  const [agentFilter, setAgentFilter] = useState<string>('all'); // For Master view

  // Permissions
  const isMasterOrAdmin = currentUser.username === 'master' || currentUser.roles.includes('مدیر') || currentUser.roles.includes('Admin');

  // Filter Personnel to find eligible Sales Agents (Anyone with Sales related role + Admins)
  const salesAgents = useMemo(() => {
      return personnel.filter(p => 
          p.roles.some(r => r.includes('فروش') || r.includes('Sales') || r.includes('مدیر') || r.includes('Admin') || r.includes('Export')) || p.username === 'master'
      );
  }, [personnel]);

  // Form State
  const [formData, setFormData] = useState<Partial<SaleRecord>>({
      amount: 0,
      currency: 'IRR',
      depositDate: new Date().toISOString().split('T')[0],
      targetAccount: '',
      description: '',
      customerName: '',
      serviceId: '',
      serviceName: '',
      agentId: currentUser.id, // Default to current user
      agentName: currentUser.fullName,
      commissionPercentage: 0,
      commissionAmount: 0
  });

  const [receiptFile, setReceiptFile] = useState<AttachedFile | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = {
      fa: {
          title: 'داشبورد جامع فروش',
          leaderboard: 'لیدربورد (رتبه‌بندی)',
          history: 'گزارشات و سوابق',
          add: 'ثبت فروش جدید',
          edit: 'ویرایش جزئیات فروش',
          deleteConfirm: 'آیا از حذف این رکورد و کسر کمیسیون اطمینان دارید؟',
          amount: 'مبلغ کل فاکتور',
          date: 'تاریخ واریز',
          account: 'حساب مقصد',
          desc: 'توضیحات تکمیلی',
          customer: 'نام مشتری / طرف حساب',
          receipt: 'تصویر فیش واریزی',
          upload: 'آپلود مدرک',
          save: 'ثبت نهایی',
          cancel: 'انصراف',
          totalSales: 'فروش کل',
          mySales: 'عملکرد من',
          count: 'فقره',
          rial: 'ریال',
          rank: 'رتبه',
          agent: 'کارشناس فروش',
          viewReceipt: 'مشاهده فیش',
          noSales: 'داده‌ای برای نمایش وجود ندارد.',
          selectService: 'انتخاب سرویس فروخته شده',
          service: 'خدمت / محصول',
          commissionSection: 'تنظیمات پورسانت و سهم (مدیریت)',
          commPercent: 'درصد پورسانت',
          commAmount: 'مبلغ پورسانت',
          selectAgent: 'انتخاب فروشنده (Agent)',
          filterAgent: 'فیلتر بر اساس کارشناس:',
          allAgents: 'همه کارشناسان',
          totalComm: 'مجموع پورسانت پرداختی',
          uploadHint: 'فقط فایل‌های تصویری یا PDF'
      },
      en: {
          title: 'Comprehensive Sales Dashboard',
          leaderboard: 'Leaderboard',
          history: 'Reports & History',
          add: 'Record New Sale',
          edit: 'Edit Sale Details',
          deleteConfirm: 'Are you sure you want to delete this record?',
          amount: 'Total Invoice Amount',
          date: 'Deposit Date',
          account: 'Target Account',
          desc: 'Description',
          customer: 'Customer Name',
          receipt: 'Receipt Image',
          upload: 'Upload Doc',
          save: 'Submit',
          cancel: 'Cancel',
          totalSales: 'Total Revenue',
          mySales: 'My Performance',
          count: 'Count',
          rial: 'IRR',
          rank: 'Rank',
          agent: 'Sales Agent',
          viewReceipt: 'View Receipt',
          noSales: 'No data to display.',
          selectService: 'Select Sold Service',
          service: 'Service / Product',
          commissionSection: 'Commission & Share Settings (Admin)',
          commPercent: 'Commission %',
          commAmount: 'Commission Amount',
          selectAgent: 'Select Agent',
          filterAgent: 'Filter by Agent:',
          allAgents: 'All Agents',
          totalComm: 'Total Commission Paid',
          uploadHint: 'Images or PDF only'
      }
  }[lang];

  useEffect(() => {
      const unsub = subscribeToSales(setAllSales);
      return () => unsub();
  }, []);

  // Auto-calculate commission
  useEffect(() => {
      if (formData.amount && formData.commissionPercentage !== undefined) {
          const comm = Math.round(formData.amount * (formData.commissionPercentage / 100));
          setFormData(prev => ({ ...prev, commissionAmount: comm }));
      }
  }, [formData.amount, formData.commissionPercentage]);

  // Handle Service Selection
  const handleServiceChange = (serviceId: string) => {
      const service = services.find(s => s.id === serviceId);
      if (service) {
          setFormData(prev => ({
              ...prev,
              serviceId: service.id,
              serviceName: lang === 'en' && service.titleEn ? service.titleEn : service.title,
              // Only set default percentage if it hasn't been manually overridden or if it's 0
              commissionPercentage: prev.commissionPercentage === 0 ? (service.commissionPercentage || 0) : prev.commissionPercentage
          }));
      } else {
          setFormData(prev => ({ ...prev, serviceId: '', serviceName: '' }));
      }
  };

  // Handle Agent Change (Admin Only)
  const handleAgentChange = (agentId: string) => {
      const agent = personnel.find(p => p.id === agentId);
      if (agent) {
          setFormData(prev => ({ ...prev, agentId: agent.id, agentName: agent.fullName }));
      }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      if (file.size > 5 * 1024 * 1024) { alert('Max 5MB'); return; }

      const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
      setReceiptFile(newFile);

      uploadFileWithProgress(
          file,
          (p) => setReceiptFile(prev => prev ? { ...prev, progress: p } : null),
          (url) => setReceiptFile(prev => prev ? { ...prev, content: url, status: 'success', progress: 100 } : null),
          (err) => setReceiptFile(prev => prev ? { ...prev, status: 'error' } : null)
      );
  };

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.amount || !formData.targetAccount || !receiptFile || receiptFile.status !== 'success') {
          alert(lang === 'fa' ? 'لطفا تمام فیلدها را پر کنید و منتظر آپلود فیش باشید.' : 'Please complete all fields and wait for upload.');
          return;
      }

      const saleData: SaleRecord = {
          id: formData.id || `sale-${Date.now()}`,
          agentId: formData.agentId!, // Assumed set by state init
          agentName: formData.agentName!, // Assumed set by state init
          amount: Number(formData.amount),
          currency: formData.currency || 'IRR',
          depositDate: formData.depositDate!,
          targetAccount: formData.targetAccount!,
          description: formData.description,
          customerName: formData.customerName,
          receiptFile: receiptFile,
          createdAt: formData.createdAt || new Date().toISOString(),
          serviceId: formData.serviceId,
          serviceName: formData.serviceName,
          commissionPercentage: formData.commissionPercentage,
          commissionAmount: formData.commissionAmount
      };

      if (isEditing && isMasterOrAdmin && formData.id) {
          await updateSaleInCloud(formData.id, saleData, currentUser.fullName);
      } else {
          await saveSaleToCloud(saleData);
      }

      setShowModal(false);
      resetForm();
  };

  const handleEdit = (sale: SaleRecord) => {
      if (!isMasterOrAdmin) return;
      setFormData(sale);
      setReceiptFile(sale.receiptFile || null);
      setIsEditing(true);
      setShowModal(true);
  };

  const handleDelete = async (id: string) => {
      if (!isMasterOrAdmin) return;
      if (window.confirm(t.deleteConfirm)) {
          await deleteSaleFromCloud(id, currentUser.fullName);
      }
  };

  const resetForm = () => {
      setFormData({ 
          amount: 0, currency: 'IRR', depositDate: new Date().toISOString().split('T')[0], 
          targetAccount: '', description: '', customerName: '', serviceId: '', serviceName: '', 
          agentId: currentUser.id, agentName: currentUser.fullName, 
          commissionPercentage: 0, commissionAmount: 0 
      });
      setReceiptFile(null);
      setIsEditing(false);
  };

  // --- Filtering Logic ---

  // 1. Visible Sales List (History Tab)
  // Master sees ALL (filtered by dropdown). Regular User sees ONLY THEIR OWN.
  const visibleSales = useMemo(() => {
      if (isMasterOrAdmin) {
          return agentFilter === 'all' ? allSales : allSales.filter(s => s.agentId === agentFilter);
      } else {
          return allSales.filter(s => s.agentId === currentUser.id);
      }
  }, [allSales, agentFilter, currentUser.id, isMasterOrAdmin]);

  // 2. Leaderboard Logic (Always shows everyone for motivation, or restricted?)
  // Let's show everyone to everyone for motivation, but Master can see details.
  const leaderboard = useMemo(() => {
      const stats: Record<string, { name: string, total: number, count: number, comm: number }> = {};
      allSales.forEach(sale => {
          if (!stats[sale.agentId]) {
              stats[sale.agentId] = { name: sale.agentName, total: 0, count: 0, comm: 0 };
          }
          stats[sale.agentId].total += sale.amount;
          stats[sale.agentId].comm += (sale.commissionAmount || 0);
          stats[sale.agentId].count += 1;
      });
      return Object.values(stats).sort((a, b) => b.total - a.total);
  }, [allSales]);

  // Totals for the current view
  const viewTotals = visibleSales.reduce((acc, curr) => ({
      sales: acc.sales + curr.amount,
      comm: acc.comm + (curr.commissionAmount || 0)
  }), { sales: 0, comm: 0 });

  return (
    <div className="space-y-6 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4">
            <div>
                <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                    <div className="bg-emerald-100 text-emerald-600 p-2 rounded-lg"><IconTag className="w-6 h-6" /></div>
                    {t.title}
                </h2>
            </div>
            <div className="flex gap-2">
                <div className="flex bg-gray-100 p-1 rounded-lg">
                    <button onClick={() => setActiveTab('leaderboard')} className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'leaderboard' ? 'bg-white shadow text-emerald-600' : 'text-gray-500'}`}><IconTrophy className="w-4 h-4" /> {t.leaderboard}</button>
                    <button onClick={() => setActiveTab('history')} className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'history' ? 'bg-white shadow text-emerald-600' : 'text-gray-500'}`}><IconCalendar className="w-4 h-4" /> {t.history}</button>
                </div>
                <button onClick={() => { resetForm(); setShowModal(true); }} className="bg-emerald-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-emerald-700 flex items-center gap-2 shadow-lg shadow-emerald-200">
                    <IconPlus className="w-5 h-5" /> {t.add}
                </button>
            </div>
        </div>

        {/* Stats Summary Cards (Visible for Master or Current User Stats) */}
        {activeTab === 'history' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-5 shadow-sm">
                    <div className="text-emerald-800 text-sm font-bold mb-1 flex items-center gap-2"><IconMoney className="w-4 h-4" /> {isMasterOrAdmin && agentFilter === 'all' ? t.totalSales : t.mySales}</div>
                    <div className="text-2xl font-black text-gray-800">{viewTotals.sales.toLocaleString()} <span className="text-xs font-medium text-gray-500">{t.rial}</span></div>
                </div>
                <div className="bg-indigo-50 border border-indigo-100 rounded-2xl p-5 shadow-sm">
                    <div className="text-indigo-800 text-sm font-bold mb-1 flex items-center gap-2"><IconChart className="w-4 h-4" /> {t.totalComm}</div>
                    <div className="text-2xl font-black text-gray-800">{viewTotals.comm.toLocaleString()} <span className="text-xs font-medium text-gray-500">{t.rial}</span></div>
                </div>
                <div className="bg-orange-50 border border-orange-100 rounded-2xl p-5 shadow-sm">
                    <div className="text-orange-800 text-sm font-bold mb-1 flex items-center gap-2"><IconBriefcase className="w-4 h-4" /> {t.count}</div>
                    <div className="text-2xl font-black text-gray-800">{visibleSales.length} <span className="text-xs font-medium text-gray-500">{t.count}</span></div>
                </div>
            </div>
        )}

        {activeTab === 'leaderboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Top 3 Cards */}
                {leaderboard.slice(0, 3).map((agent, index) => (
                    <div key={index} className={`relative overflow-hidden rounded-3xl p-6 shadow-lg border-2 ${index === 0 ? 'bg-gradient-to-br from-yellow-50 to-amber-100 border-amber-300' : index === 1 ? 'bg-gradient-to-br from-gray-50 to-gray-200 border-gray-300' : 'bg-gradient-to-br from-orange-50 to-orange-100 border-orange-200'}`}>
                        <div className="absolute top-0 right-0 p-4 opacity-20"><IconTrophy className={`w-24 h-24 ${index === 0 ? 'text-amber-500' : index === 1 ? 'text-gray-500' : 'text-orange-600'}`} /></div>
                        <div className="relative z-10 text-center">
                            <div className={`w-12 h-12 mx-auto rounded-full flex items-center justify-center text-xl font-bold mb-3 ${index === 0 ? 'bg-amber-400 text-white' : index === 1 ? 'bg-gray-400 text-white' : 'bg-orange-400 text-white'}`}>{index + 1}</div>
                            <h3 className="text-xl font-black text-gray-800 mb-1">{agent.name}</h3>
                            <div className="text-3xl font-black text-gray-900 my-4">{agent.total.toLocaleString()} <span className="text-sm text-gray-500 font-normal">{t.rial}</span></div>
                            <div className="flex justify-center gap-2">
                                <span className="inline-block bg-white/50 px-3 py-1 rounded-lg text-xs font-bold text-gray-700">{agent.count} {t.count}</span>
                                {isMasterOrAdmin && <span className="inline-block bg-green-100/80 px-3 py-1 rounded-lg text-xs font-bold text-green-800">Comm: {agent.comm.toLocaleString()}</span>}
                            </div>
                        </div>
                    </div>
                ))}

                {/* Rest of the list */}
                {leaderboard.length > 3 && (
                    <div className="col-span-full bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-50 text-gray-500">
                                <tr>
                                    <th className="px-4 py-3 text-start">{t.rank}</th>
                                    <th className="px-4 py-3 text-start">{t.agent}</th>
                                    <th className="px-4 py-3 text-center">{t.count}</th>
                                    <th className="px-4 py-3 text-end">{t.totalSales}</th>
                                    {isMasterOrAdmin && <th className="px-4 py-3 text-end">{t.commAmount}</th>}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {leaderboard.slice(3).map((agent, idx) => (
                                    <tr key={idx}>
                                        <td className="px-4 py-3 font-bold text-gray-400">#{idx + 4}</td>
                                        <td className="px-4 py-3 font-bold text-gray-800">{agent.name}</td>
                                        <td className="px-4 py-3 text-center">{agent.count}</td>
                                        <td className="px-4 py-3 text-end font-mono font-bold text-gray-700">{agent.total.toLocaleString()}</td>
                                        {isMasterOrAdmin && <td className="px-4 py-3 text-end font-mono text-green-600">{agent.comm.toLocaleString()}</td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {leaderboard.length === 0 && <div className="col-span-full text-center py-12 text-gray-400">{t.noSales}</div>}
            </div>
        )}

        {activeTab === 'history' && (
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                {isMasterOrAdmin && (
                    <div className="p-4 border-b border-gray-100 bg-gray-50 flex items-center gap-3">
                        <IconSearch className="w-5 h-5 text-gray-400" />
                        <span className="text-sm font-bold text-gray-600">{t.filterAgent}</span>
                        <select 
                            className="bg-white border border-gray-300 text-gray-700 text-sm rounded-lg focus:ring-emerald-500 focus:border-emerald-500 block p-2 outline-none"
                            value={agentFilter}
                            onChange={(e) => setAgentFilter(e.target.value)}
                        >
                            <option value="all">{t.allAgents}</option>
                            {salesAgents.map(p => (
                                <option key={p.id} value={p.id}>{p.fullName}</option>
                            ))}
                        </select>
                    </div>
                )}

                <div className="overflow-x-auto">
                    <table className="w-full text-start text-sm">
                        <thead className="bg-gray-50 text-gray-500">
                            <tr>
                                <th className="px-6 py-4">{t.date}</th>
                                <th className="px-6 py-4">{t.agent}</th>
                                <th className="px-6 py-4">{t.customer}</th>
                                <th className="px-6 py-4">{t.service}</th>
                                <th className="px-6 py-4">{t.amount}</th>
                                <th className="px-6 py-4 text-center">{t.commPercent}</th>
                                <th className="px-6 py-4 text-center">{t.receipt}</th>
                                {isMasterOrAdmin && <th className="px-6 py-4 text-center">Action</th>}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {visibleSales.map((sale) => (
                                <tr key={sale.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 font-mono dir-ltr text-right text-gray-600">{new Date(sale.depositDate).toLocaleDateString('fa-IR')}</td>
                                    <td className="px-6 py-4 font-bold text-gray-800 flex items-center gap-2">
                                        <div className="w-6 h-6 bg-gray-200 rounded-full flex items-center justify-center text-[10px] text-gray-600">{sale.agentName.charAt(0)}</div>
                                        {sale.agentName}
                                    </td>
                                    <td className="px-6 py-4 text-gray-600">{sale.customerName || '-'}</td>
                                    <td className="px-6 py-4">
                                        {sale.serviceName ? (
                                            <span className="inline-flex items-center gap-1 bg-indigo-50 text-indigo-700 px-2 py-1 rounded text-xs font-bold border border-indigo-100">
                                                <IconBriefcase className="w-3 h-3" /> {sale.serviceName}
                                            </span>
                                        ) : '-'}
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="font-black text-emerald-600">{sale.amount.toLocaleString()} <span className="text-[10px] font-normal text-gray-400">{sale.currency}</span></div>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className="bg-orange-50 text-orange-700 px-2 py-1 rounded-lg text-xs font-bold">{sale.commissionPercentage}%</span>
                                        {isMasterOrAdmin && sale.commissionAmount && (
                                            <div className="text-[10px] text-gray-400 mt-1">{sale.commissionAmount.toLocaleString()}</div>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        {sale.receiptFile ? (
                                            <a href={sale.receiptFile.content} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-blue-600 bg-blue-50 px-2 py-1 rounded text-xs hover:bg-blue-100">
                                                <IconReceipt className="w-3 h-3" /> {t.viewReceipt}
                                            </a>
                                        ) : '-'}
                                    </td>
                                    {isMasterOrAdmin && (
                                        <td className="px-6 py-4 text-center">
                                            <div className="flex justify-center gap-2">
                                                <button onClick={() => handleEdit(sale)} className="text-gray-400 hover:text-blue-600"><IconEdit className="w-4 h-4" /></button>
                                                <button onClick={() => handleDelete(sale.id)} className="text-gray-400 hover:text-red-600"><IconTrash className="w-4 h-4" /></button>
                                            </div>
                                        </td>
                                    )}
                                </tr>
                            ))}
                            {visibleSales.length === 0 && <tr><td colSpan={9} className="text-center py-8 text-gray-400">{t.noSales}</td></tr>}
                        </tbody>
                    </table>
                </div>
            </div>
        )}

        {/* Modal */}
        {showModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in flex flex-col max-h-[90vh]">
                    <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-emerald-50 rounded-t-2xl">
                        <h3 className="font-bold text-emerald-900">{isEditing ? t.edit : t.add}</h3>
                        <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600">✕</button>
                    </div>
                    <div className="overflow-y-auto p-6 flex-grow">
                        <form id="sales-form" onSubmit={handleSubmit} className="space-y-4">

                            {/* Agent Selection - Only for Admins */}
                            {isMasterOrAdmin && (
                                <div className="bg-indigo-50 p-3 rounded-lg border border-indigo-100">
                                    <label className="block text-sm font-bold text-indigo-900 mb-1 flex items-center gap-2">
                                        <IconUsers className="w-4 h-4" /> {t.selectAgent}
                                    </label>
                                    <select 
                                        className="w-full px-3 py-2 border border-indigo-200 rounded-lg bg-white outline-none focus:ring-2 focus:ring-indigo-500"
                                        value={formData.agentId}
                                        onChange={(e) => handleAgentChange(e.target.value)}
                                    >
                                        {salesAgents.map(p => (
                                            <option key={p.id} value={p.id}>{p.fullName} ({p.roles.join(', ')})</option>
                                        ))}
                                    </select>
                                </div>
                            )}

                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">{t.selectService}</label>
                                <select 
                                    className="w-full px-3 py-2 border rounded-lg bg-white outline-none focus:ring-2 focus:ring-emerald-500"
                                    value={formData.serviceId}
                                    onChange={(e) => handleServiceChange(e.target.value)}
                                >
                                    <option value="">-- {t.service} --</option>
                                    {services.map(s => (
                                        <option key={s.id} value={s.id}>{s.title}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">{t.amount}</label>
                                    <input type="number" required className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.amount || ''} onChange={e => setFormData({...formData, amount: parseInt(e.target.value)})} />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">Currency</label>
                                    <select className="w-full px-3 py-2 border rounded-lg bg-white" value={formData.currency} onChange={e => setFormData({...formData, currency: e.target.value as any})}>
                                        <option value="IRR">IRR</option><option value="USD">USD</option><option value="OMR">OMR</option>
                                    </select>
                                </div>
                            </div>

                            {/* Commission Calculation Display - Editable for Master */}
                            <div className="bg-orange-50 p-3 rounded-lg border border-orange-200 grid grid-cols-2 gap-4 text-sm relative">
                                {!isMasterOrAdmin && <div className="absolute inset-0 bg-white/20 z-10 cursor-not-allowed" />}
                                <div className="text-orange-800 font-bold col-span-2 border-b border-orange-200 pb-1 mb-1 flex items-center gap-1">
                                    <IconBriefcase className="w-4 h-4" /> {t.commissionSection}
                                </div>
                                <div>
                                    <label className="block text-xs text-orange-600 mb-1">{t.commPercent}</label>
                                    <div className="relative">
                                        <input 
                                            type="number" 
                                            className="w-full px-2 py-1 rounded border border-orange-300 font-bold text-gray-800 text-center focus:ring-2 focus:ring-orange-500 outline-none"
                                            value={formData.commissionPercentage}
                                            onChange={(e) => setFormData({...formData, commissionPercentage: parseFloat(e.target.value)})}
                                            disabled={!isMasterOrAdmin}
                                        />
                                        <span className="absolute left-2 top-1.5 text-xs text-gray-400">%</span>
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs text-orange-600 mb-1">{t.commAmount}</label>
                                    <div className="font-bold text-emerald-600 bg-white px-2 py-1.5 rounded border border-orange-200 text-center">
                                        {formData.commissionAmount?.toLocaleString()}
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">{t.date}</label>
                                    <input type="date" required className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.depositDate} onChange={e => setFormData({...formData, depositDate: e.target.value})} />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">{t.customer}</label>
                                    <input className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.customerName} onChange={e => setFormData({...formData, customerName: e.target.value})} placeholder="Optional" />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">{t.account}</label>
                                <input required className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.targetAccount} onChange={e => setFormData({...formData, targetAccount: e.target.value})} placeholder="Card No / IBAN / Bank Name" />
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">{t.desc}</label>
                                <textarea className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" rows={2} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                            </div>

                            <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
                                <label className="block text-sm font-bold text-gray-700 mb-2">{t.receipt} *</label>
                                <div className="flex items-center gap-4">
                                    <button type="button" onClick={() => fileInputRef.current?.click()} className="bg-white border border-gray-300 px-4 py-2 rounded-lg text-sm font-bold hover:bg-gray-100">
                                        {receiptFile ? 'Change File' : t.upload}
                                    </button>
                                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf" onChange={handleFileUpload} />

                                    {receiptFile && (
                                        <div className="flex items-center gap-2 text-sm text-gray-600 bg-white px-2 py-1 rounded border">
                                            <span className="truncate max-w-[100px]">{receiptFile.name}</span>
                                            {receiptFile.status === 'uploading' && <span className="text-blue-500">{Math.round(receiptFile.progress || 0)}%</span>}
                                            {receiptFile.status === 'success' && <IconCheck className="w-4 h-4 text-green-500" />}
                                        </div>
                                    )}
                                </div>
                                <p className="text-[10px] text-gray-400 mt-1">{t.uploadHint}</p>
                            </div>
                        </form>
                    </div>
                    <div className="p-4 border-t border-gray-100 flex justify-end gap-3 bg-gray-50 rounded-b-2xl">
                        <button onClick={() => setShowModal(false)} className="px-4 py-2 text-gray-600 font-bold hover:bg-gray-200 rounded-lg transition-colors">{t.cancel}</button>
                        <button type="submit" form="sales-form" disabled={!receiptFile || receiptFile.status === 'uploading'} className="bg-emerald-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-emerald-700 disabled:opacity-50 shadow-lg shadow-emerald-200">{t.save}</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { SaleRecord, Personnel, Currency, AttachedFile, ServiceOption } from '../types';
import { IconTag, IconPlus, IconTrophy, IconMoney, IconCalendar, IconEdit, IconTrash, IconReceipt, IconCheck, IconBriefcase, IconUsers, IconChart, IconSearch, IconShield } from './Icons';
import { saveSaleToCloud, updateSaleInCloud, deleteSaleFromCloud, subscribeToSales, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  services: ServiceOption[];
  lang: Language;
}

export const SalesDashboard: React.FC<Props> = ({ currentUser, personnel, services, lang }) => {
  const [allSales, setAllSales] = useState<SaleRecord[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [activeTab, setActiveTab] = useState<'leaderboard' | 'history'>('leaderboard');
  const [isEditing, setIsEditing] = useState(false);
  const [agentFilter, setAgentFilter] = useState<string>('all'); // For Master view

  // --- PERMISSION LOGIC ---
  // "Master", "Admin", or "Sales Manager" (مدیر فروش) have full access.
  // "Sales Expert" (کارشناس فروش) sees only their own data.
  const hasFullAccess = useMemo(() => {
      const r = currentUser.roles || [];
      return (
          currentUser.username === 'master' || 
          r.includes('مدیر') || 
          r.includes('Admin') || 
          r.includes('مدیر فروش') || 
          r.includes('Sales Manager')
      );
  }, [currentUser]);

  // List of eligible agents to show in dropdown (Anyone with sales role + Admins)
  const salesAgents = useMemo(() => {
      return personnel.filter(p => 
          p.roles.some(r => 
              r.includes('فروش') || r.includes('Sales') || 
              r.includes('مدیر') || r.includes('Admin') || 
              r.includes('Export') || r.includes('کارشناس')
          ) || p.username === 'master'
      );
  }, [personnel]);

  // Form State
  const [formData, setFormData] = useState<Partial<SaleRecord>>({
      amount: 0,
      currency: 'IRR',
      depositDate: new Date().toISOString().split('T')[0],
      targetAccount: '',
      description: '',
      customerName: '',
      serviceId: '',
      serviceName: '',
      agentId: currentUser.id, // Default to current user
      agentName: currentUser.fullName,
      commissionPercentage: 0,
      commissionAmount: 0
  });

  const [receiptFile, setReceiptFile] = useState<AttachedFile | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = {
      fa: {
          title: 'داشبورد جامع فروش',
          leaderboard: 'لیدربورد (رتبه‌بندی)',
          history: 'گزارشات و سوابق',
          add: 'ثبت فروش جدید',
          edit: 'ویرایش جزئیات فروش',
          deleteConfirm: 'آیا از حذف این رکورد و کسر کمیسیون اطمینان دارید؟',
          amount: 'مبلغ کل فاکتور',
          date: 'تاریخ واریز',
          account: 'حساب مقصد',
          desc: 'توضیحات تکمیلی',
          customer: 'نام مشتری / طرف حساب',
          receipt: 'تصویر فیش واریزی',
          upload: 'آپلود مدرک',
          save: 'ثبت نهایی',
          cancel: 'انصراف',
          totalSales: 'فروش کل',
          mySales: 'عملکرد من',
          count: 'فقره',
          rial: 'ریال',
          rank: 'رتبه',
          agent: 'کارشناس فروش',
          viewReceipt: 'مشاهده فیش',
          noSales: 'داده‌ای برای نمایش وجود ندارد.',
          selectService: 'انتخاب سرویس فروخته شده',
          service: 'خدمت / محصول',
          commissionSection: 'تنظیمات پورسانت و سهم (مدیریت)',
          commPercent: 'درصد پورسانت',
          commAmount: 'مبلغ پورسانت',
          selectAgent: 'انتخاب فروشنده (Agent)',
          filterAgent: 'فیلتر بر اساس کارشناس:',
          allAgents: 'همه کارشناسان',
          totalComm: 'مجموع پورسانت پرداختی',
          uploadHint: 'فقط فایل‌های تصویری یا PDF',
          accessLevel: 'سطح دسترسی',
          managerView: 'مدیریت کل',
          expertView: 'پنل شخصی'
      },
      en: {
          title: 'Comprehensive Sales Dashboard',
          leaderboard: 'Leaderboard',
          history: 'Reports & History',
          add: 'Record New Sale',
          edit: 'Edit Sale Details',
          deleteConfirm: 'Are you sure you want to delete this record?',
          amount: 'Total Invoice Amount',
          date: 'Deposit Date',
          account: 'Target Account',
          desc: 'Description',
          customer: 'Customer Name',
          receipt: 'Receipt Image',
          upload: 'Upload Doc',
          save: 'Submit',
          cancel: 'Cancel',
          totalSales: 'Total Revenue',
          mySales: 'My Performance',
          count: 'Count',
          rial: 'IRR',
          rank: 'Rank',
          agent: 'Sales Agent',
          viewReceipt: 'View Receipt',
          noSales: 'No data to display.',
          selectService: 'Select Sold Service',
          service: 'Service / Product',
          commissionSection: 'Commission & Share Settings (Admin)',
          commPercent: 'Commission %',
          commAmount: 'Commission Amount',
          selectAgent: 'Select Agent',
          filterAgent: 'Filter by Agent:',
          allAgents: 'All Agents',
          totalComm: 'Total Commission Paid',
          uploadHint: 'Images or PDF only',
          accessLevel: 'Access Level',
          managerView: 'Manager View',
          expertView: 'Personal View'
      }
  }[lang];

  useEffect(() => {
      const unsub = subscribeToSales(setAllSales);
      return () => unsub();
  }, []);

  // Auto-calculate commission
  useEffect(() => {
      if (formData.amount && formData.commissionPercentage !== undefined) {
          const comm = Math.round(formData.amount * (formData.commissionPercentage / 100));
          setFormData(prev => ({ ...prev, commissionAmount: comm }));
      }
  }, [formData.amount, formData.commissionPercentage]);

  // Handle Service Selection
  const handleServiceChange = (serviceId: string) => {
      const service = services.find(s => s.id === serviceId);
      if (service) {
          setFormData(prev => ({
              ...prev,
              serviceId: service.id,
              serviceName: lang === 'en' && service.titleEn ? service.titleEn : service.title,
              // Only update percentage if it's 0 or user is NOT a manager (managers can override, so we don't auto-reset if they typed something)
              // But for UX, let's auto-set it if it's the first selection
              commissionPercentage: (prev.commissionPercentage === 0 || !hasFullAccess) ? (service.commissionPercentage || 0) : prev.commissionPercentage
          }));
      } else {
          setFormData(prev => ({ ...prev, serviceId: '', serviceName: '' }));
      }
  };

  // Handle Agent Change (Manager Only)
  const handleAgentChange = (agentId: string) => {
      const agent = personnel.find(p => p.id === agentId);
      if (agent) {
          setFormData(prev => ({ ...prev, agentId: agent.id, agentName: agent.fullName }));
      }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      if (file.size > 5 * 1024 * 1024) { alert('Max 5MB'); return; }

      const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
      setReceiptFile(newFile);

      uploadFileWithProgress(
          file,
          (p) => setReceiptFile(prev => prev ? { ...prev, progress: p } : null),
          (url) => setReceiptFile(prev => prev ? { ...prev, content: url, status: 'success', progress: 100 } : null),
          (err) => setReceiptFile(prev => prev ? { ...prev, status: 'error' } : null)
      );
  };

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.amount || !formData.targetAccount || !receiptFile || receiptFile.status !== 'success') {
          alert(lang === 'fa' ? 'لطفا تمام فیلدها را پر کنید و منتظر آپلود فیش باشید.' : 'Please complete all fields and wait for upload.');
          return;
      }

      const saleData: SaleRecord = {
          id: formData.id || `sale-${Date.now()}`,
          agentId: formData.agentId!, // Assumed set by state init
          agentName: formData.agentName!, // Assumed set by state init
          amount: Number(formData.amount),
          currency: formData.currency || 'IRR',
          depositDate: formData.depositDate!,
          targetAccount: formData.targetAccount!,
          description: formData.description,
          customerName: formData.customerName,
          receiptFile: receiptFile,
          createdAt: formData.createdAt || new Date().toISOString(),
          serviceId: formData.serviceId,
          serviceName: formData.serviceName,
          commissionPercentage: formData.commissionPercentage,
          commissionAmount: formData.commissionAmount
      };

      if (isEditing && hasFullAccess && formData.id) {
          await updateSaleInCloud(formData.id, saleData, currentUser.fullName);
      } else {
          await saveSaleToCloud(saleData);
      }

      setShowModal(false);
      resetForm();
  };

  const handleEdit = (sale: SaleRecord) => {
      if (!hasFullAccess) return;
      setFormData(sale);
      setReceiptFile(sale.receiptFile || null);
      setIsEditing(true);
      setShowModal(true);
  };

  const handleDelete = async (id: string) => {
      if (!hasFullAccess) return;
      if (window.confirm(t.deleteConfirm)) {
          await deleteSaleFromCloud(id, currentUser.fullName);
      }
  };

  const resetForm = () => {
      setFormData({ 
          amount: 0, currency: 'IRR', depositDate: new Date().toISOString().split('T')[0], 
          targetAccount: '', description: '', customerName: '', serviceId: '', serviceName: '', 
          agentId: currentUser.id, agentName: currentUser.fullName, 
          commissionPercentage: 0, commissionAmount: 0 
      });
      setReceiptFile(null);
      setIsEditing(false);
  };

  // --- FILTERING LOGIC ---
  // If Manager: Can see ALL or filter by specific agent.
  // If Agent: Can ONLY see their own.
  const visibleSales = useMemo(() => {
      if (hasFullAccess) {
          return agentFilter === 'all' ? allSales : allSales.filter(s => s.agentId === agentFilter);
      } else {
          return allSales.filter(s => s.agentId === currentUser.id);
      }
  }, [allSales, agentFilter, currentUser.id, hasFullAccess]);

  // --- LEADERBOARD LOGIC ---
  // If Manager: Sees everyone.
  // If Agent: Sees everyone (for competition) OR only themselves? Usually Leaderboard shows everyone.
  // Let's show everyone, but detailed commission info is hidden for non-managers.
  const leaderboard = useMemo(() => {
      // Filter the source data for leaderboard based on access
      // Managers see all stats. Agents see all stats BUT we can optionally restrict it if needed.
      // Standard practice: Leaderboard shows everyone's Sales Volume, but hides Earnings/Commission for others.

      const stats: Record<string, { name: string, total: number, count: number, comm: number }> = {};

      // We calculate stats from ALL sales, so the ranking is global
      allSales.forEach(sale => {
          if (!stats[sale.agentId]) {
              stats[sale.agentId] = { name: sale.agentName, total: 0, count: 0, comm: 0 };
          }
          stats[sale.agentId].total += sale.amount;
          stats[sale.agentId].comm += (sale.commissionAmount || 0);
          stats[sale.agentId].count += 1;
      });
      return Object.values(stats).sort((a, b) => b.total - a.total);
  }, [allSales]);

  // Totals for the current view (History Tab)
  const viewTotals = visibleSales.reduce((acc, curr) => ({
      sales: acc.sales + curr.amount,
      comm: acc.comm + (curr.commissionAmount || 0)
  }), { sales: 0, comm: 0 });

  return (
    <div className="space-y-6 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4">
            <div>
                <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                    <div className="bg-emerald-100 text-emerald-600 p-2 rounded-lg"><IconTag className="w-6 h-6" /></div>
                    {t.title}
                </h2>
                <div className="flex items-center gap-2 mt-2">
                    <span className={`text-xs px-2 py-1 rounded border ${hasFullAccess ? 'bg-purple-50 text-purple-700 border-purple-200' : 'bg-gray-50 text-gray-600 border-gray-200'}`}>
                        {t.accessLevel}: {hasFullAccess ? t.managerView : t.expertView}
                    </span>
                </div>
            </div>
            <div className="flex gap-2">
                <div className="flex bg-gray-100 p-1 rounded-lg">
                    <button onClick={() => setActiveTab('leaderboard')} className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'leaderboard' ? 'bg-white shadow text-emerald-600' : 'text-gray-500'}`}><IconTrophy className="w-4 h-4" /> {t.leaderboard}</button>
                    <button onClick={() => setActiveTab('history')} className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'history' ? 'bg-white shadow text-emerald-600' : 'text-gray-500'}`}><IconCalendar className="w-4 h-4" /> {t.history}</button>
                </div>
                <button onClick={() => { resetForm(); setShowModal(true); }} className="bg-emerald-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-emerald-700 flex items-center gap-2 shadow-lg shadow-emerald-200">
                    <IconPlus className="w-5 h-5" /> {t.add}
                </button>
            </div>
        </div>

        {/* Stats Summary Cards */}
        {activeTab === 'history' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-5 shadow-sm">
                    <div className="text-emerald-800 text-sm font-bold mb-1 flex items-center gap-2"><IconMoney className="w-4 h-4" /> {hasFullAccess && agentFilter === 'all' ? t.totalSales : t.mySales}</div>
                    <div className="text-2xl font-black text-gray-800">{viewTotals.sales.toLocaleString()} <span className="text-xs font-medium text-gray-500">{t.rial}</span></div>
                </div>
                <div className="bg-indigo-50 border border-indigo-100 rounded-2xl p-5 shadow-sm">
                    <div className="text-indigo-800 text-sm font-bold mb-1 flex items-center gap-2"><IconChart className="w-4 h-4" /> {t.totalComm}</div>
                    <div className="text-2xl font-black text-gray-800">{viewTotals.comm.toLocaleString()} <span className="text-xs font-medium text-gray-500">{t.rial}</span></div>
                </div>
                <div className="bg-orange-50 border border-orange-100 rounded-2xl p-5 shadow-sm">
                    <div className="text-orange-800 text-sm font-bold mb-1 flex items-center gap-2"><IconBriefcase className="w-4 h-4" /> {t.count}</div>
                    <div className="text-2xl font-black text-gray-800">{visibleSales.length} <span className="text-xs font-medium text-gray-500">{t.count}</span></div>
                </div>
            </div>
        )}

        {activeTab === 'leaderboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Top 3 Cards */}
                {leaderboard.slice(0, 3).map((agent, index) => (
                    <div key={index} className={`relative overflow-hidden rounded-3xl p-6 shadow-lg border-2 ${index === 0 ? 'bg-gradient-to-br from-yellow-50 to-amber-100 border-amber-300' : index === 1 ? 'bg-gradient-to-br from-gray-50 to-gray-200 border-gray-300' : 'bg-gradient-to-br from-orange-50 to-orange-100 border-orange-200'}`}>
                        <div className="absolute top-0 right-0 p-4 opacity-20"><IconTrophy className={`w-24 h-24 ${index === 0 ? 'text-amber-500' : index === 1 ? 'text-gray-500' : 'text-orange-600'}`} /></div>
                        <div className="relative z-10 text-center">
                            <div className={`w-12 h-12 mx-auto rounded-full flex items-center justify-center text-xl font-bold mb-3 ${index === 0 ? 'bg-amber-400 text-white' : index === 1 ? 'bg-gray-400 text-white' : 'bg-orange-400 text-white'}`}>{index + 1}</div>
                            <h3 className="text-xl font-black text-gray-800 mb-1">{agent.name}</h3>
                            <div className="text-3xl font-black text-gray-900 my-4">{agent.total.toLocaleString()} <span className="text-sm text-gray-500 font-normal">{t.rial}</span></div>
                            <div className="flex justify-center gap-2">
                                <span className="inline-block bg-white/50 px-3 py-1 rounded-lg text-xs font-bold text-gray-700">{agent.count} {t.count}</span>
                                {/* Only show Commission total if User is Manager */}
                                {hasFullAccess && <span className="inline-block bg-green-100/80 px-3 py-1 rounded-lg text-xs font-bold text-green-800">Comm: {agent.comm.toLocaleString()}</span>}
                            </div>
                        </div>
                    </div>
                ))}

                {/* Rest of the list */}
                {leaderboard.length > 3 && (
                    <div className="col-span-full bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-50 text-gray-500">
                                <tr>
                                    <th className="px-4 py-3 text-start">{t.rank}</th>
                                    <th className="px-4 py-3 text-start">{t.agent}</th>
                                    <th className="px-4 py-3 text-center">{t.count}</th>
                                    <th className="px-4 py-3 text-end">{t.totalSales}</th>
                                    {hasFullAccess && <th className="px-4 py-3 text-end">{t.commAmount}</th>}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {leaderboard.slice(3).map((agent, idx) => (
                                    <tr key={idx}>
                                        <td className="px-4 py-3 font-bold text-gray-400">#{idx + 4}</td>
                                        <td className="px-4 py-3 font-bold text-gray-800">{agent.name}</td>
                                        <td className="px-4 py-3 text-center">{agent.count}</td>
                                        <td className="px-4 py-3 text-end font-mono font-bold text-gray-700">{agent.total.toLocaleString()}</td>
                                        {hasFullAccess && <td className="px-4 py-3 text-end font-mono text-green-600">{agent.comm.toLocaleString()}</td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {leaderboard.length === 0 && <div className="col-span-full text-center py-12 text-gray-400">{t.noSales}</div>}
            </div>
        )}

        {activeTab === 'history' && (
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                {hasFullAccess && (
                    <div className="p-4 border-b border-gray-100 bg-gray-50 flex items-center gap-3">
                        <IconSearch className="w-5 h-5 text-gray-400" />
                        <span className="text-sm font-bold text-gray-600">{t.filterAgent}</span>
                        <select 
                            className="bg-white border border-gray-300 text-gray-700 text-sm rounded-lg focus:ring-emerald-500 focus:border-emerald-500 block p-2 outline-none"
                            value={agentFilter}
                            onChange={(e) => setAgentFilter(e.target.value)}
                        >
                            <option value="all">{t.allAgents}</option>
                            {salesAgents.map(p => (
                                <option key={p.id} value={p.id}>{p.fullName}</option>
                            ))}
                        </select>
                    </div>
                )}

                <div className="overflow-x-auto">
                    <table className="w-full text-start text-sm">
                        <thead className="bg-gray-50 text-gray-500">
                            <tr>
                                <th className="px-6 py-4">{t.date}</th>
                                <th className="px-6 py-4">{t.agent}</th>
                                <th className="px-6 py-4">{t.customer}</th>
                                <th className="px-6 py-4">{t.service}</th>
                                <th className="px-6 py-4">{t.amount}</th>
                                <th className="px-6 py-4 text-center">{t.commPercent}</th>
                                <th className="px-6 py-4 text-center">{t.receipt}</th>
                                {hasFullAccess && <th className="px-6 py-4 text-center">Action</th>}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {visibleSales.map((sale) => (
                                <tr key={sale.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 font-mono dir-ltr text-right text-gray-600">{new Date(sale.depositDate).toLocaleDateString('fa-IR')}</td>
                                    <td className="px-6 py-4 font-bold text-gray-800 flex items-center gap-2">
                                        <div className="w-6 h-6 bg-gray-200 rounded-full flex items-center justify-center text-[10px] text-gray-600">{sale.agentName.charAt(0)}</div>
                                        {sale.agentName}
                                    </td>
                                    <td className="px-6 py-4 text-gray-600">{sale.customerName || '-'}</td>
                                    <td className="px-6 py-4">
                                        {sale.serviceName ? (
                                            <span className="inline-flex items-center gap-1 bg-indigo-50 text-indigo-700 px-2 py-1 rounded text-xs font-bold border border-indigo-100">
                                                <IconBriefcase className="w-3 h-3" /> {sale.serviceName}
                                            </span>
                                        ) : '-'}
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="font-black text-emerald-600">{sale.amount.toLocaleString()} <span className="text-[10px] font-normal text-gray-400">{sale.currency}</span></div>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className="bg-orange-50 text-orange-700 px-2 py-1 rounded-lg text-xs font-bold">{sale.commissionPercentage}%</span>
                                        {/* Managers can see amount */}
                                        {(hasFullAccess || sale.agentId === currentUser.id) && sale.commissionAmount && (
                                            <div className="text-[10px] text-gray-400 mt-1">{sale.commissionAmount.toLocaleString()}</div>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        {sale.receiptFile ? (
                                            <a href={sale.receiptFile.content} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-blue-600 bg-blue-50 px-2 py-1 rounded text-xs hover:bg-blue-100">
                                                <IconReceipt className="w-3 h-3" /> {t.viewReceipt}
                                            </a>
                                        ) : '-'}
                                    </td>
                                    {hasFullAccess && (
                                        <td className="px-6 py-4 text-center">
                                            <div className="flex justify-center gap-2">
                                                <button onClick={() => handleEdit(sale)} className="text-gray-400 hover:text-blue-600"><IconEdit className="w-4 h-4" /></button>
                                                <button onClick={() => handleDelete(sale.id)} className="text-gray-400 hover:text-red-600"><IconTrash className="w-4 h-4" /></button>
                                            </div>
                                        </td>
                                    )}
                                </tr>
                            ))}
                            {visibleSales.length === 0 && <tr><td colSpan={9} className="text-center py-8 text-gray-400">{t.noSales}</td></tr>}
                        </tbody>
                    </table>
                </div>
            </div>
        )}

        {/* Modal */}
        {showModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in flex flex-col max-h-[90vh]">
                    <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-emerald-50 rounded-t-2xl">
                        <h3 className="font-bold text-emerald-900">{isEditing ? t.edit : t.add}</h3>
                        <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600">✕</button>
                    </div>
                    <div className="overflow-y-auto p-6 flex-grow">
                        <form id="sales-form" onSubmit={handleSubmit} className="space-y-4">

                            {/* Agent Selection - Only for Managers/Admins */}
                            {hasFullAccess && (
                                <div className="bg-indigo-50 p-3 rounded-lg border border-indigo-100">
                                    <label className="block text-sm font-bold text-indigo-900 mb-1 flex items-center gap-2">
                                        <IconUsers className="w-4 h-4" /> {t.selectAgent}
                                    </label>
                                    <select 
                                        className="w-full px-3 py-2 border border-indigo-200 rounded-lg bg-white outline-none focus:ring-2 focus:ring-indigo-500"
                                        value={formData.agentId}
                                        onChange={(e) => handleAgentChange(e.target.value)}
                                    >
                                        {salesAgents.map(p => (
                                            <option key={p.id} value={p.id}>{p.fullName} ({p.roles.join(', ')})</option>
                                        ))}
                                    </select>
                                </div>
                            )}

                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">{t.selectService}</label>
                                <select 
                                    className="w-full px-3 py-2 border rounded-lg bg-white outline-none focus:ring-2 focus:ring-emerald-500"
                                    value={formData.serviceId}
                                    onChange={(e) => handleServiceChange(e.target.value)}
                                >
                                    <option value="">-- {t.service} --</option>
                                    {services.map(s => (
                                        <option key={s.id} value={s.id}>{s.title}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">{t.amount}</label>
                                    <input type="number" required className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.amount || ''} onChange={e => setFormData({...formData, amount: parseInt(e.target.value)})} />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">Currency</label>
                                    <select className="w-full px-3 py-2 border rounded-lg bg-white" value={formData.currency} onChange={e => setFormData({...formData, currency: e.target.value as any})}>
                                        <option value="IRR">IRR</option><option value="USD">USD</option><option value="OMR">OMR</option>
                                    </select>
                                </div>
                            </div>

                            {/* Commission Calculation Display - Editable ONLY for Managers */}
                            <div className="bg-orange-50 p-3 rounded-lg border border-orange-200 grid grid-cols-2 gap-4 text-sm relative">
                                {/* Mask for non-managers to prevent editing */}
                                {!hasFullAccess && <div className="absolute inset-0 bg-white/20 z-10 cursor-not-allowed" title="فقط مدیران امکان تغییر درصد را دارند" />}

                                <div className="text-orange-800 font-bold col-span-2 border-b border-orange-200 pb-1 mb-1 flex items-center gap-1">
                                    <IconBriefcase className="w-4 h-4" /> {t.commissionSection}
                                    {!hasFullAccess && <IconShield className="w-3 h-3 text-gray-400 ml-auto" />}
                                </div>
                                <div>
                                    <label className="block text-xs text-orange-600 mb-1">{t.commPercent}</label>
                                    <div className="relative">
                                        <input 
                                            type="number" 
                                            className="w-full px-2 py-1 rounded border border-orange-300 font-bold text-gray-800 text-center focus:ring-2 focus:ring-orange-500 outline-none disabled:bg-gray-100 disabled:text-gray-500"
                                            value={formData.commissionPercentage}
                                            onChange={(e) => setFormData({...formData, commissionPercentage: parseFloat(e.target.value)})}
                                            disabled={!hasFullAccess}
                                        />
                                        <span className="absolute left-2 top-1.5 text-xs text-gray-400">%</span>
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs text-orange-600 mb-1">{t.commAmount}</label>
                                    <div className="font-bold text-emerald-600 bg-white px-2 py-1.5 rounded border border-orange-200 text-center">
                                        {formData.commissionAmount?.toLocaleString()}
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">{t.date}</label>
                                    <input type="date" required className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.depositDate} onChange={e => setFormData({...formData, depositDate: e.target.value})} />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">{t.customer}</label>
                                    <input className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.customerName} onChange={e => setFormData({...formData, customerName: e.target.value})} placeholder="Optional" />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">{t.account}</label>
                                <input required className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.targetAccount} onChange={e => setFormData({...formData, targetAccount: e.target.value})} placeholder="Card No / IBAN / Bank Name" />
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">{t.desc}</label>
                                <textarea className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" rows={2} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                            </div>

                            <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
                                <label className="block text-sm font-bold text-gray-700 mb-2">{t.receipt} *</label>
                                <div className="flex items-center gap-4">
                                    <button type="button" onClick={() => fileInputRef.current?.click()} className="bg-white border border-gray-300 px-4 py-2 rounded-lg text-sm font-bold hover:bg-gray-100">
                                        {receiptFile ? 'Change File' : t.upload}
                                    </button>
                                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf" onChange={handleFileUpload} />

                                    {receiptFile && (
                                        <div className="flex items-center gap-2 text-sm text-gray-600 bg-white px-2 py-1 rounded border">
                                            <span className="truncate max-w-[100px]">{receiptFile.name}</span>
                                            {receiptFile.status === 'uploading' && <span className="text-blue-500">{Math.round(receiptFile.progress || 0)}%</span>}
                                            {receiptFile.status === 'success' && <IconCheck className="w-4 h-4 text-green-500" />}
                                        </div>
                                    )}
                                </div>
                                <p className="text-[10px] text-gray-400 mt-1">{t.uploadHint}</p>
                            </div>
                        </form>
                    </div>
                    <div className="p-4 border-t border-gray-100 flex justify-end gap-3 bg-gray-50 rounded-b-2xl">
                        <button onClick={() => setShowModal(false)} className="px-4 py-2 text-gray-600 font-bold hover:bg-gray-200 rounded-lg transition-colors">{t.cancel}</button>
                        <button type="submit" form="sales-form" disabled={!receiptFile || receiptFile.status === 'uploading'} className="bg-emerald-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-emerald-700 disabled:opacity-50 shadow-lg shadow-emerald-200">{t.save}</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

export enum TicketStatus {
  SUBMITTED = 'ثبت شده',
  PROCESSING = 'در حال بررسی',
  IN_PROGRESS = 'در دست اقدام',
  COMPLETED = 'تکمیل شده',
  CANCELLED = 'لغو شده'
}

export type Currency = 'IRR' | 'OMR' | 'USD';

export interface Price {
  amount: number;
  currency: Currency;
}

export interface AttachedFile {
  name: string;
  size: number;
  type: string;
  content: string; // Base64 or URL or Blob URL
  rawFile?: File; // Direct file reference for efficient upload
  // Upload Status Fields
  status?: 'pending' | 'uploading' | 'success' | 'error';
  progress?: number;
  errorMsg?: string;
}

export interface SaleRecord {
  id: string;
  agentId: string;
  agentName: string;
  amount: number; // Total Sales Amount
  currency: Currency;
  depositDate: string; // YYYY-MM-DD
  targetAccount: string; // e.g., "Mellat - 1234"
  receiptFile?: AttachedFile; // Image of the receipt (Optional/Legacy)
  description?: string;
  createdAt: string;
  customerName?: string; 
  // New Calculation Fields
  serviceId?: string;
  serviceName?: string;
  commissionPercentage?: number; // Snapshot of the % at the time of sale
  commissionAmount?: number; // Calculated earnings for the agent/company based on logic
}

export interface SubService {
  id: string;
  title: string;
  titleEn?: string;
  price?: Price;
}

export interface ServiceOption {
  id: string;
  title: string;
  titleEn?: string; // English Title
  description: string;
  descriptionEn?: string; // English Description
  icon: string;
  price?: Price; // Updated to Price Object
  isActive: boolean;
  subServices?: SubService[]; // Nested Services
  commissionPercentage?: number; // New: Default commission/share percentage for this service
}

export interface PersonnelPermissions {
  canAssign: boolean; 
  canViewCustomers: boolean; 
  canViewTariffs: boolean; 
  canViewAllTickets: boolean;
  canIssueInvoices: boolean; 
  // Sales Permissions
  canViewSales: boolean; // Can access Sales Dashboard (view own)
  canManageSales: boolean; // Can view all, edit commissions, delete
}

export interface PersonnelDocument {
  id: string;
  title: string;
  file: AttachedFile;
}

export interface Personnel {
  id: string;
  fullName: string;
  roles: string[]; 
  jobDescription?: string; 
  reportsTo?: string; // ID of the supervisor/manager
  email: string;
  username: string;
  password?: string;
  avatar?: string; 
  documents?: PersonnelDocument[]; 
  status: 'active' | 'inactive';
  permissions?: PersonnelPermissions; 
}

export interface Customer {
  id: string;
  fullName: string;
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string;
  email?: string;
  businessType?: string;
  firstContact: string;
  totalTickets: number;
  source?: string; 
  loyaltyCode?: string; // Unique code for discounts
}

export interface TimelineEntry {
  type: 'status_change' | 'comment' | 'assignment' | 'creation' | 'update' | 'project_update' | 'invoice_created';
  title: string;
  description?: string; 
  actorName: string; 
  timestamp: string;
  visibility?: 'public' | 'internal'; // Controls who sees this entry
}

export interface Payment {
  id: string;
  amount: number;
  currency: Currency;
  date: string;
  type: 'deposit' | 'settlement' | 'installment';
  note?: string;
}

export interface InvoiceItem {
  description: string;
  quantity: number;
  unitPrice: number;
  total: number;
}

export interface Invoice {
  id: string;
  number: string;
  date: string;
  dueDate?: string;
  customerName: string;
  companyName?: string;
  items: InvoiceItem[];
  currency: Currency;
  subTotal: number;
  taxRate: number;
  taxAmount: number;
  discount: number;
  total: number;
  note?: string;
  issuedBy: string;
}

export interface ProjectMilestone {
  id: string;
  title: string;
  isCompleted: boolean;
  dueDate?: string;
}

export interface ProjectRisk {
  id: string;
  title: string;
  impact: 'Low' | 'Medium' | 'High';
}

export interface ProjectTeamMember {
  userId: string;
  role: string; // e.g. "Head of Design"
  responsibility: string; // Specific task description
  joinedAt: string;
}

export interface ProjectDetails {
  isActive: boolean;
  tariff?: Price; // Cost/Price Object
  startDate: string;
  endDate: string;
  teamMemberIds: string[]; 
  teamMembers?: ProjectTeamMember[]; // Detailed team structure
  projectFiles: AttachedFile[];
  payments: Payment[]; // List of payments
  invoices?: Invoice[]; // List of issued invoices
  milestones?: ProjectMilestone[];
  risks?: ProjectRisk[];
  progress: number; 
  statusNote?: string;
}

export interface Ticket {
  id: string;
  customerName: string; 
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string; 
  businessType?: string; 
  serviceId: string;
  selectedSubServices?: string[]; // Array of SubService IDs or Names
  description: string;
  files?: AttachedFile[];
  status: TicketStatus;
  createdAt: string;
  aiAnalysis?: string;
  priority?: 'Low' | 'Medium' | 'High';
  assignedTo?: string;
  timeline: TimelineEntry[]; 
  customData?: Record<string, string>; 
  projectData?: ProjectDetails;
  discountApplied?: boolean; // If loyalty discount was used
}

export interface InternalMessage {
  id: string;
  senderId: string;
  senderName: string;
  senderAvatar?: string;
  recipientIds: string[];
  recipientNames: string[];
  subject: string;
  body: string;
  files?: AttachedFile[];
  createdAt: string;
  readBy: string[]; // IDs of recipients who read the message
}

export interface TaskComment {
  id: string;
  authorId: string;
  authorName: string;
  text: string;
  timestamp: string;
}

export interface TaskChecklistItem {
  id: string;
  text: string;
  isCompleted: boolean;
}

export interface Task {
  id: string;
  title: string;
  description?: string;
  creatorId: string;
  creatorName: string;
  assigneeIds: string[]; // List of personnel IDs responsible for this task
  isCompleted: boolean;
  checklist?: TaskChecklistItem[]; // Sub-tasks list
  dueDate?: string;
  priority: 'Low' | 'Medium' | 'High';
  createdAt: string;
  comments: TaskComment[];
}

export interface Meeting {
  id: string;
  title: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm
  endTime: string; // HH:mm
  location: string;
  organizerId: string;
  organizerName: string;
  attendeeIds: string[];
  description?: string;
}

export interface KPI {
  id: string;
  title: string;
  titleEn?: string;
  targetValue: number;
  currentValue: number;
  unit: 'percent' | 'count' | 'currency';
  period: 'monthly' | 'quarterly' | 'yearly';
  assignedRole?: string; // Role-based KPI
  assignedUserId?: string; // Specific User KPI
  description?: string;
}

export interface CustomForm {
  id: string;
  title: string;
  category: string; // e.g., 'ISO Standards', 'HR', 'Logistics'
  description?: string;
  fields: FormField[];
  allowedRoles: string[]; // Empty array means available to all
  createdAt: string;
  createdBy: string;
}

export interface SystemLog {
  id: string;
  actionType: 'CREATE' | 'UPDATE' | 'DELETE' | 'LOGIN' | 'OTHER';
  entity: 'Ticket' | 'Customer' | 'Personnel' | 'Project' | 'Task' | 'Meeting' | 'Message' | 'System' | 'KPI' | 'CustomForm' | 'Sale';
  entityId?: string;
  details: string;
  actorName: string;
  actorId?: string;
  timestamp: string;
  backupData?: any; // Stores the deleted data for restoration
  collectionName?: string; // Target collection for restoration
}

export interface FeaturedBusiness {
  id: string;
  name: string;
  description: string;
  imageUrl: string;
  websiteUrl?: string;
  contactNumber?: string;
  category: string;
  isGold: boolean; // Premium status for higher visibility
}

export type ViewState = 'landing' | 'new-ticket' | 'tracking' | 'admin';

export type FormFieldType = 'text' | 'textarea' | 'email' | 'tel' | 'select' | 'header' | 'date' | 'checkbox';

export interface FormField {
  id: string;
  key: string; 
  label: string;
  labelEn?: string;
  type: FormFieldType;
  required: boolean;
  placeholder?: string;
  placeholderEn?: string;
  options?: string[]; 
  isSystem?: boolean; 
  order: number;
}

export interface InvoiceTemplate {
  companyName: string;
  logoUrl?: string;
  address: string;
  phone: string;
  website?: string;
  footerText: string;
  termsConditions: string;
  defaultTaxRate: number; // Percentage
  colorTheme: string; // Hex Code
}

export interface AppConfig {
  appTitle: string;
  appTitleEn: string;
  appSubtitle: string;
  appSubtitleEn: string;

  // Landing Page Content
  landingHeroTitle?: string;
  landingHeroSubtitle?: string;
  footerText?: string;

  // Daily Content
  dailyTips?: string[];
  showDailyTips?: boolean;

  // Featured Businesses (Ads)
  featuredBusinesses?: FeaturedBusiness[];

  formFields: FormField[];
  personnelRoles?: string[]; 
  invoiceTemplate?: InvoiceTemplate;
}

import React, { useState, useRef } from 'react';
import { Personnel, AppConfig, PersonnelDocument, AttachedFile } from '../types';
import { IconPlus, IconTrash, IconShield, IconEdit, IconCheck, IconSettings, IconUsers, IconMoney, IconBriefcase, IconUpload, IconFile, IconPaperclip, IconLayout, IconInvoice } from './Icons';
import { uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  personnel: Personnel[];
  config: AppConfig;
  onUpdate: (list: Personnel[]) => void;
  onUpdateConfig: (config: AppConfig) => void;
  lang: Language;
}

export const PersonnelManager: React.FC<Props> = ({ personnel, config, onUpdate, onUpdateConfig, lang }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newRoleName, setNewRoleName] = useState('');
  const [showRoleManager, setShowRoleManager] = useState(false);

  const [formData, setFormData] = useState({
    fullName: '', roles: [] as string[], jobDescription: '', reportsTo: '', email: '', username: '', password: '', avatar: '', documents: [] as PersonnelDocument[],
    canAssign: false, canViewCustomers: false, canViewTariffs: false, canViewAllTickets: false, canIssueInvoices: false,
    canViewSales: false, canManageSales: false
  });

  const [newDocTitle, setNewDocTitle] = useState('');
  const [newDocFile, setNewDocFile] = useState<AttachedFile | null>(null);
  const avatarInputRef = useRef<HTMLInputElement>(null);
  const docInputRef = useRef<HTMLInputElement>(null);
  const [isProcessingImage, setIsProcessingImage] = useState(false);

  const availableRoles = config.personnelRoles || ['مدیر', 'کارشناس صادرات', 'طراح گرافیک/بسته بندی', 'پشتیبانی', 'کارشناس آموزش'];

  const t = {
      fa: {
          rolesTitle: 'مدیریت سمت‌ها',
          rolePlaceholder: 'عنوان سمت جدید',
          add: 'افزودن',
          editUser: 'ویرایش اطلاعات پرسنل',
          newUser: 'تعریف حساب کاربری و پرسنل جدید',
          uploadPhoto: 'افزودن عکس',
          uploading: 'در حال آپلود...',
          name: 'نام و نام خانوادگی',
          email: 'ایمیل سازمانی',
          roles: 'سمت‌های سازمانی',
          manager: 'مدیر مستقیم / گزارش‌دهی به',
          jobDesc: 'شرح شغل',
          permissions: 'دسترسی‌ها و مجوزها',
          permAssign: 'مجوز ارجاع کار',
          permAllTickets: 'مشاهده کل درخواست‌ها',
          permCustomers: 'دسترسی بانک مشتریان',
          permTariffs: 'مشاهده تعرفه‌ها',
          permInvoice: 'مجوز صدور فاکتور',
          permViewSales: 'مشاهده داشبرد فروش',
          permManageSales: 'مدیریت کل فروش (مستر)',
          docs: 'پرونده پرسنلی و مدارک',
          docTitle: 'عنوان مدرک',
          docFile: 'فایل',
          selectFile: 'انتخاب فایل',
          loginInfo: 'اطلاعات ورود به سامانه',
          username: 'نام کاربری',
          password: 'رمز عبور',
          save: 'ذخیره تغییرات',
          create: 'ایجاد حساب کاربری',
          cancel: 'انصراف',
          deleteConfirm: 'آیا از حذف این پرسنل اطمینان دارید؟',
          emailLbl: 'ایمیل:',
          usernameLbl: 'نام کاربری:',
          docsLbl: 'مدارک:'
      },
      en: {
          rolesTitle: 'Manage Roles',
          rolePlaceholder: 'New Role Title',
          add: 'Add',
          editUser: 'Edit Staff Info',
          newUser: 'New Staff Account',
          uploadPhoto: 'Upload Photo',
          uploading: 'Uploading...',
          name: 'Full Name',
          email: 'Work Email',
          roles: 'Organizational Roles',
          manager: 'Direct Manager / Reports To',
          jobDesc: 'Job Description',
          permissions: 'Permissions',
          permAssign: 'Can Assign Tasks',
          permAllTickets: 'View All Requests',
          permCustomers: 'View Customer Bank',
          permTariffs: 'View Tariffs',
          permInvoice: 'Can Issue Invoices',
          permViewSales: 'Access Sales Dashboard',
          permManageSales: 'Manage All Sales (Master)',
          docs: 'Personnel Documents',
          docTitle: 'Document Title',
          docFile: 'File',
          selectFile: 'Select File',
          loginInfo: 'Login Credentials',
          username: 'Username',
          password: 'Password',
          save: 'Save Changes',
          create: 'Create Account',
          cancel: 'Cancel',
          deleteConfirm: 'Are you sure you want to delete this staff member?',
          emailLbl: 'Email:',
          usernameLbl: 'Username:',
          docsLbl: 'Docs:'
      }
  }[lang];

  const handleEdit = (person: Personnel) => {
    setEditingId(person.id);
    setFormData({
        fullName: person.fullName, roles: person.roles || [], jobDescription: person.jobDescription || '', reportsTo: person.reportsTo || '',
        email: person.email, username: person.username, password: person.password || '', avatar: person.avatar || '', documents: person.documents || [],
        canAssign: person.permissions?.canAssign || false, canViewCustomers: person.permissions?.canViewCustomers || false,
        canViewTariffs: person.permissions?.canViewTariffs || false, canViewAllTickets: person.permissions?.canViewAllTickets || false,
        canIssueInvoices: person.permissions?.canIssueInvoices || false,
        canViewSales: person.permissions?.canViewSales || false,
        canManageSales: person.permissions?.canManageSales || false
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCancelEdit = () => {
      setEditingId(null);
      setFormData({ 
          fullName: '', roles: [], jobDescription: '', reportsTo: '', email: '', username: '', password: '', avatar: '', documents: [], 
          canAssign: false, canViewCustomers: false, canViewTariffs: false, canViewAllTickets: false, canIssueInvoices: false,
          canViewSales: false, canManageSales: false
      });
      setNewDocTitle(''); setNewDocFile(null);
  };

  const toggleRole = (role: string) => { setFormData(prev => { const exists = prev.roles.includes(role); return exists ? { ...prev, roles: prev.roles.filter(r => r !== role) } : { ...prev, roles: [...prev.roles, role] }; }); };

  const handleAvatarSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]; if (!file) return;
      setIsProcessingImage(true);
      uploadFileWithProgress(file, () => {}, (url) => { setFormData(prev => ({ ...prev, avatar: url })); setIsProcessingImage(false); }, (err) => { alert(err.message); setIsProcessingImage(false); });
  };

  const handleDocFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]; if (!file) return;
      if (file.size > 5 * 1024 * 1024) { alert('Max 5MB'); return; }
      setNewDocFile({ name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 });
      uploadFileWithProgress(file, (progress) => { setNewDocFile(prev => prev ? { ...prev, progress } : null); }, (url) => { setNewDocFile(prev => prev ? { ...prev, content: url, status: 'success', progress: 100 } : null); }, (err) => { setNewDocFile(prev => prev ? { ...prev, status: 'error', errorMsg: err.message } : null); });
  };

  const handleAddDocument = () => {
      if (!newDocTitle.trim() || !newDocFile || newDocFile.status !== 'success') return;
      const newDoc: PersonnelDocument = { id: `doc-${Date.now()}`, title: newDocTitle, file: newDocFile };
      setFormData(prev => ({ ...prev, documents: [...prev.documents, newDoc] }));
      setNewDocTitle(''); setNewDocFile(null); if (docInputRef.current) docInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.roles.length === 0 || formData.documents.some(d => d.file.status === 'uploading') || isProcessingImage) return;
    const permissions = { 
        canAssign: formData.canAssign, canViewCustomers: formData.canViewCustomers, 
        canViewTariffs: formData.canViewTariffs, canViewAllTickets: formData.canViewAllTickets, 
        canIssueInvoices: formData.canIssueInvoices,
        canViewSales: formData.canViewSales,
        canManageSales: formData.canManageSales
    };
    if (editingId) {
        onUpdate(personnel.map(p => p.id === editingId ? { ...p, ...formData, permissions } : p));
    } else {
        const newPerson: Personnel = { id: `p-${Date.now()}`, ...formData, status: 'active', permissions };
        onUpdate([...personnel, newPerson]);
    }
    handleCancelEdit();
  };

  const handleRemove = (id: string) => { if (window.confirm(t.deleteConfirm)) { onUpdate(personnel.filter(p => p.id !== id)); if (editingId === id) handleCancelEdit(); } };
  const handleAddRole = () => { if (!newRoleName.trim() || availableRoles.includes(newRoleName.trim())) return; onUpdateConfig({ ...config, personnelRoles: [...availableRoles, newRoleName.trim()] }); setNewRoleName(''); };
  const handleDeleteRole = (roleToDelete: string) => { if (window.confirm(`Delete ${roleToDelete}?`)) { onUpdateConfig({ ...config, personnelRoles: availableRoles.filter(r => r !== roleToDelete) }); } };

  return (
    <div className="space-y-6 animate-fade-in">
       <div className="flex justify-end"><button onClick={() => setShowRoleManager(!showRoleManager)} className="text-sm text-indigo-600 flex items-center gap-1 hover:underline"><IconSettings className="w-4 h-4" /> {t.rolesTitle}</button></div>
       {showRoleManager && (<div className="bg-gray-50 p-4 rounded-xl border border-indigo-100 mb-4 animate-fade-in"><div className="flex gap-2 mb-4"><input className="flex-grow px-3 py-2 rounded-lg border border-gray-300 text-sm outline-none focus:border-indigo-500" placeholder={t.rolePlaceholder} value={newRoleName} onChange={e => setNewRoleName(e.target.value)} /><button onClick={handleAddRole} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-700">{t.add}</button></div><div className="flex flex-wrap gap-2">{availableRoles.map((role, idx) => (<div key={idx} className="bg-white border border-gray-200 px-3 py-1.5 rounded-lg text-sm flex items-center gap-2"><span>{role}</span>{role !== 'مدیر' && (<button onClick={() => handleDeleteRole(role)} className="text-red-400 hover:text-red-600"><IconTrash className="w-3 h-3" /></button>)}</div>))}</div></div>)}
       <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm transition-colors" style={editingId ? { borderColor: '#8b5cf6', borderWidth: '2px' } : {}}><div className="flex items-center gap-3 mb-6"><div className={`p-2 rounded-lg ${editingId ? 'bg-indigo-100 text-indigo-600' : 'bg-purple-100 text-purple-600'}`}>{editingId ? <IconEdit className="w-5 h-5" /> : <IconPlus className="w-5 h-5" />}</div><h3 className="text-lg font-bold text-gray-800">{editingId ? t.editUser : t.newUser}</h3></div>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
             <div className="md:col-span-3 flex flex-col items-center gap-4"><div onClick={() => !isProcessingImage && avatarInputRef.current?.click()} className={`w-32 h-32 rounded-full border-2 border-dashed border-gray-300 flex items-center justify-center bg-gray-50 hover:bg-gray-100 cursor-pointer overflow-hidden relative group transition-all ${isProcessingImage ? 'opacity-50 cursor-wait' : ''}`}>{formData.avatar ? (<img src={formData.avatar} alt="Avatar" className="w-full h-full object-cover" />) : (<div className="text-center text-gray-400"><IconUsers className="w-8 h-8 mx-auto mb-1" /><span className="text-xs">{isProcessingImage ? t.uploading : t.uploadPhoto}</span></div>)}</div><input type="file" ref={avatarInputRef} className="hidden" accept="image/*" onChange={handleAvatarSelect} /></div>
             <div className="md:col-span-9 space-y-4">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4"><div><label className="block text-sm font-medium text-gray-700 mb-1">{t.name}</label><input type="text" required className="w-full px-4 py-2 rounded-lg border border-gray-300 outline-none" value={formData.fullName} onChange={e => setFormData({...formData, fullName: e.target.value})}/></div><div><label className="block text-sm font-medium text-gray-700 mb-1">{t.email}</label><input type="email" required className="w-full px-4 py-2 rounded-lg border border-gray-300 outline-none" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})}/></div></div>
                 <div><label className="block text-sm font-medium text-gray-700 mb-2">{t.roles}</label><div className="flex flex-wrap gap-2 p-3 border border-gray-200 rounded-xl bg-gray-50 max-h-32 overflow-y-auto">{availableRoles.map((role) => (<button type="button" key={role} onClick={() => toggleRole(role)} className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all border ${formData.roles.includes(role) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-300'}`}>{role} {formData.roles.includes(role) && '✓'}</button>))}</div></div>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4"><div><label className="block text-sm font-medium text-gray-700 mb-1">{t.manager}</label><select className="w-full px-4 py-2 rounded-lg border border-gray-300 outline-none bg-white" value={formData.reportsTo} onChange={e => setFormData({...formData, reportsTo: e.target.value})}><option value="">-</option>{personnel.filter(p => p.id !== editingId).map(p => (<option key={p.id} value={p.id}>{p.fullName} ({p.roles.join(', ')})</option>))}</select></div></div>
                 <div><label className="block text-sm font-medium text-gray-700 mb-1">{t.jobDesc}</label><textarea rows={2} className="w-full px-4 py-2 rounded-lg border border-gray-300 outline-none" value={formData.jobDescription} onChange={e => setFormData({...formData, jobDescription: e.target.value})}/></div>
             </div>
          </div>
          <div className="border-t border-gray-100 pt-4"><label className="block text-sm font-bold text-gray-700 mb-3">{t.permissions}</label><div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-3">
              <label className="flex items-center gap-2 cursor-pointer bg-blue-50 px-3 py-3 rounded-lg border border-blue-100"><input type="checkbox" className="w-4 h-4" checked={formData.canAssign} onChange={e => setFormData({...formData, canAssign: e.target.checked})}/><span className="text-xs font-bold text-blue-800">{t.permAssign}</span></label>
              <label className="flex items-center gap-2 cursor-pointer bg-purple-50 px-3 py-3 rounded-lg border border-purple-100"><input type="checkbox" className="w-4 h-4" checked={formData.canViewAllTickets} onChange={e => setFormData({...formData, canViewAllTickets: e.target.checked})}/><span className="text-xs font-bold text-purple-800">{t.permAllTickets}</span></label>
              <label className="flex items-center gap-2 cursor-pointer bg-green-50 px-3 py-3 rounded-lg border border-green-100"><input type="checkbox" className="w-4 h-4" checked={formData.canViewCustomers} onChange={e => setFormData({...formData, canViewCustomers: e.target.checked})}/><span className="text-xs font-bold text-green-800">{t.permCustomers}</span></label>
              <label className="flex items-center gap-2 cursor-pointer bg-amber-50 px-3 py-3 rounded-lg border border-amber-100"><input type="checkbox" className="w-4 h-4" checked={formData.canViewTariffs} onChange={e => setFormData({...formData, canViewTariffs: e.target.checked})}/><span className="text-xs font-bold text-amber-800">{t.permTariffs}</span></label>
              <label className="flex items-center gap-2 cursor-pointer bg-rose-50 px-3 py-3 rounded-lg border border-rose-100"><input type="checkbox" className="w-4 h-4" checked={formData.canIssueInvoices} onChange={e => setFormData({...formData, canIssueInvoices: e.target.checked})}/><span className="text-xs font-bold text-rose-800">{t.permInvoice}</span></label>
              {/* New Sales Permissions */}
              <label className="flex items-center gap-2 cursor-pointer bg-emerald-50 px-3 py-3 rounded-lg border border-emerald-100"><input type="checkbox" className="w-4 h-4" checked={formData.canViewSales} onChange={e => setFormData({...formData, canViewSales: e.target.checked})}/><span className="text-xs font-bold text-emerald-800">{t.permViewSales}</span></label>
              <label className="flex items-center gap-2 cursor-pointer bg-orange-50 px-3 py-3 rounded-lg border border-orange-100"><input type="checkbox" className="w-4 h-4" checked={formData.canManageSales} onChange={e => setFormData({...formData, canManageSales: e.target.checked})}/><span className="text-xs font-bold text-orange-800">{t.permManageSales}</span></label>
          </div></div>
          <div className="bg-gray-50 p-4 rounded-xl border border-gray-200"><h4 className="text-sm font-bold text-gray-700 mb-3 flex items-center gap-2"><IconPaperclip className="w-4 h-4 text-gray-500" />{t.docs}</h4><div className="flex gap-2 mb-4"><input className="flex-grow px-3 py-2 rounded-lg border border-gray-300 text-sm outline-none" placeholder={t.docTitle} value={newDocTitle} onChange={e => setNewDocTitle(e.target.value)} /><button type="button" onClick={() => docInputRef.current?.click()} className="bg-white border border-gray-300 px-4 py-2 rounded-lg text-sm text-gray-600 hover:bg-gray-50 flex items-center gap-2"><IconUpload className="w-4 h-4" />{newDocFile ? t.docFile : t.selectFile}</button><input type="file" ref={docInputRef} className="hidden" accept="image/*,.pdf" onChange={handleDocFileSelect} /><button type="button" onClick={handleAddDocument} disabled={!newDocFile || newDocFile.status !== 'success'} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-700 disabled:opacity-50">{t.add}</button></div><div className="space-y-2">{formData.documents.map((doc, idx) => (<div key={idx} className="flex items-center justify-between bg-white border border-gray-200 p-2 rounded-lg"><div className="flex items-center gap-3"><div className="p-1.5 bg-gray-100 rounded text-gray-500"><IconFile className="w-4 h-4" /></div><div className="flex flex-col"><span className="text-sm font-bold text-gray-800">{doc.title}</span><a href={doc.file.content} target="_blank" rel="noreferrer" className="text-[10px] text-blue-500 hover:underline">View</a></div></div><button type="button" onClick={() => setFormData(p => ({...p, documents: p.documents.filter(d => d.id !== doc.id)}))} className="text-red-400 hover:bg-red-50 p-1.5 rounded"><IconTrash className="w-4 h-4" /></button></div>))}</div></div>
          <div className="bg-gray-50 p-4 rounded-xl border border-gray-200"><h4 className="text-sm font-bold text-gray-700 mb-3 flex items-center gap-2"><IconShield className="w-4 h-4 text-purple-600" />{t.loginInfo}</h4><div className="grid grid-cols-1 md:grid-cols-2 gap-4"><div><label className="block text-sm font-medium text-gray-600 mb-1">{t.username}</label><input type="text" required className="w-full px-4 py-2 rounded-lg border border-gray-300 outline-none dir-ltr text-left" value={formData.username} onChange={e => setFormData({...formData, username: e.target.value})}/></div><div><label className="block text-sm font-medium text-gray-600 mb-1">{t.password}</label><input type="text" required className="w-full px-4 py-2 rounded-lg border border-gray-300 outline-none dir-ltr text-left" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})}/></div></div></div>
          <div className="flex justify-end pt-2 gap-3">{editingId && (<button type="button" onClick={handleCancelEdit} className="px-6 py-2 bg-gray-100 text-gray-600 rounded-lg hover:bg-gray-200 transition-colors font-medium">{t.cancel}</button>)}<button type="submit" disabled={isProcessingImage} className={`px-8 py-2 text-white rounded-lg transition-colors shadow-lg font-bold ${editingId ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-purple-600 hover:bg-purple-700'} ${isProcessingImage ? 'opacity-50 cursor-not-allowed' : ''}`}>{editingId ? t.save : t.create}</button></div>
        </form>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">{personnel.map(person => { const manager = personnel.find(p => p.id === person.reportsTo); return (<div key={person.id} className={`bg-white p-6 rounded-2xl border shadow-sm hover:shadow-md transition-all relative group ${editingId === person.id ? 'border-indigo-500 ring-2 ring-indigo-100' : 'border-gray-100'}`}><div className="flex items-start gap-4"><div className={`w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold shrink-0 overflow-hidden border border-gray-100 ${person.roles.includes('مدیر') ? 'bg-red-100 text-red-600' : 'bg-gray-100 text-gray-600'}`}>{person.avatar ? (<img src={person.avatar} alt={person.fullName} className="w-full h-full object-cover" />) : (person.fullName.charAt(0))}</div><div className="flex-grow"><h4 className="font-bold text-gray-900">{person.fullName}</h4><div className="flex flex-wrap gap-1.5 mt-2 mb-2">{person.roles && person.roles.map((role, rIdx) => (<span key={rIdx} className="text-[10px] px-2 py-0.5 rounded bg-gray-100 text-gray-700 border border-gray-200">{role}</span>))}</div>{manager && (<div className="text-xs text-indigo-600 bg-indigo-50 px-2 py-1 rounded mb-2 inline-flex items-center gap-1"><IconLayout className="w-3 h-3" /> Report: {manager.fullName}</div>)}</div></div><div className="mt-2 text-sm space-y-2"><div className="text-gray-500 flex justify-between"><span>{t.emailLbl}</span><span>{person.email}</span></div><div className="text-gray-500 flex justify-between bg-gray-50 px-2 py-1 rounded"><span>{t.usernameLbl}</span><span className="font-mono">{person.username}</span></div>{person.documents && person.documents.length > 0 && (<div className="mt-3 pt-3 border-t border-gray-100"><span className="text-xs text-gray-500 block mb-1">{t.docsLbl}</span><div className="flex flex-wrap gap-1">{person.documents.map((d, i) => (<a key={i} href={d.file.content} target="_blank" rel="noreferrer" className="text-[10px] bg-gray-100 hover:bg-gray-200 px-2 py-1 rounded text-gray-600 border border-gray-200 block truncate max-w-[100px]">{d.title}</a>))}</div></div>)}</div><div className="absolute top-4 rtl:left-4 ltr:right-4 flex gap-1 opacity-0 group-hover:opacity-100 transition-all"><button onClick={() => handleEdit(person)} className="p-2 text-indigo-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-full transition-all"><IconEdit className="w-4 h-4" /></button><button onClick={() => handleRemove(person.id)} className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-full transition-all"><IconTrash className="w-4 h-4" /></button></div></div>)})}</div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Ticket, TicketStatus, ServiceOption, Personnel, Customer, AppConfig, ProjectDetails, AttachedFile, Currency, Payment, InternalMessage, Invoice, Task, Meeting, SystemLog, ProjectMilestone, ProjectRisk, ProjectTeamMember, KPI, CustomForm } from '../types';
import { IconCheck, IconActivity, IconUsers, IconBriefcase, IconLayout, IconPaperclip, IconShield, IconSettings, IconClock, IconFile, IconEdit, IconTrash, IconProject, IconMoney, IconUpload, IconPlus, IconChart, IconMail, IconInvoice, IconList, IconCalendarClock, IconHistory, IconCopy, IconSearch, IconFlag, IconAlertTriangle, IconTime, IconTrendingUp, IconRefreshCw, IconLock, IconMegaphone, IconBarChart2, IconMapPin, IconWhatsapp, IconTarget, IconClipboard, IconFolder, IconTag } from './Icons';
import { ServiceManager } from './ServiceManager';
import { PersonnelManager } from './PersonnelManager';
import { CustomerManager } from './CustomerManager';
import { SettingsManager } from './SettingsManager';
import { InternalMessenger } from './InternalMessenger';
import { InvoiceModal } from './InvoiceModal';
import { TaskManager } from './TaskManager';
import { MeetingCalendar } from './MeetingCalendar';
import { PerformanceReports } from './PerformanceReports';
import { KPIManager } from './KPIManager';
import { SalesDashboard } from './SalesDashboard';
import { uploadFileWithProgress, logSystemAction, subscribeToSystemLogs, saveTaskToCloud, restoreEntityFromLog, sendInternalMessage, subscribeToCustomForms } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  tickets: Ticket[];
  services: ServiceOption[];
  personnel: Personnel[];
  customers: Customer[];
  messages: InternalMessage[];
  tasks: Task[]; 
  meetings: Meeting[]; 
  kpis?: KPI[];
  config: AppConfig;
  onCreateTicket: (ticket: Ticket) => Promise<void>;
  onUpdateTicket: (ticketId: string, updates: Partial<Ticket>, actorName: string, actionNote?: string, visibility?: 'public' | 'internal') => void;
