          selectAgent: 'Select Agent',
          filterAgent: 'Filter by Agent:',
          allAgents: 'All Agents',
          totalComm: 'Total Commission Paid',
          accessLevel: 'Access Level',
          managerView: 'Manager View',
          expertView: 'Personal View'
      }
  }[lang];

  useEffect(() => {
      const unsub = subscribeToSales(setAllSales);
      return () => unsub();
  }, []);

  // Auto-calculate commission
  useEffect(() => {
      if (formData.amount && formData.commissionPercentage !== undefined) {
          const comm = Math.round(formData.amount * (formData.commissionPercentage / 100));
          setFormData(prev => ({ ...prev, commissionAmount: comm }));
      }
  }, [formData.amount, formData.commissionPercentage]);

  // Handle Service Selection
  const handleServiceChange = (serviceId: string) => {
      const service = services.find(s => s.id === serviceId);
      if (service) {
          setFormData(prev => ({
              ...prev,
              serviceId: service.id,
              serviceName: lang === 'en' && service.titleEn ? service.titleEn : service.title,
              // Only update percentage if it's 0 or user is NOT a manager (managers can override, so we don't auto-reset if they typed something)
              commissionPercentage: (prev.commissionPercentage === 0 || !hasFullAccess) ? (service.commissionPercentage || 0) : prev.commissionPercentage
          }));
      } else {
          setFormData(prev => ({ ...prev, serviceId: '', serviceName: '' }));
      }
  };

  // Handle Agent Change (Manager Only)
  const handleAgentChange = (agentId: string) => {
      const agent = personnel.find(p => p.id === agentId);
      if (agent) {
          setFormData(prev => ({ ...prev, agentId: agent.id, agentName: agent.fullName }));
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.amount || !formData.targetAccount) {
          alert(lang === 'fa' ? 'لطفا تمام فیلدها را پر کنید.' : 'Please complete all fields.');
          return;
      }

      const saleData: SaleRecord = {
          id: formData.id || `sale-${Date.now()}`,
          agentId: formData.agentId!, // Assumed set by state init
          agentName: formData.agentName!, // Assumed set by state init
          amount: Number(formData.amount),
          currency: formData.currency || 'IRR',
          depositDate: formData.depositDate!,
          targetAccount: formData.targetAccount!,
          description: formData.description,
          customerName: formData.customerName,
          createdAt: formData.createdAt || new Date().toISOString(),
          serviceId: formData.serviceId,
          serviceName: formData.serviceName,
          commissionPercentage: formData.commissionPercentage,
          commissionAmount: formData.commissionAmount
      };

      if (isEditing && hasFullAccess && formData.id) {
          await updateSaleInCloud(formData.id, saleData, currentUser.fullName);
      } else {
          await saveSaleToCloud(saleData);
      }

      setShowModal(false);
      resetForm();
  };

  const handleEdit = (sale: SaleRecord) => {
      if (!hasFullAccess) return;
      setFormData(sale);
      setIsEditing(true);
      setShowModal(true);
  };

  const handleDelete = async (id: string) => {
      if (!hasFullAccess) return;
      if (window.confirm(t.deleteConfirm)) {
          await deleteSaleFromCloud(id, currentUser.fullName);
      }
  };

  const resetForm = () => {
      setFormData({ 
          amount: 0, currency: 'IRR', depositDate: new Date().toISOString().split('T')[0], 
          targetAccount: '', description: '', customerName: '', serviceId: '', serviceName: '', 
          agentId: currentUser.id, agentName: currentUser.fullName, 
          commissionPercentage: 0, commissionAmount: 0 
      });
      setIsEditing(false);
  };

  // --- FILTERING LOGIC ---
  const visibleSales = useMemo(() => {
      if (hasFullAccess) {
          return agentFilter === 'all' ? allSales : allSales.filter(s => s.agentId === agentFilter);
      } else {
          return allSales.filter(s => s.agentId === currentUser.id);
      }
  }, [allSales, agentFilter, currentUser.id, hasFullAccess]);

  // --- LEADERBOARD LOGIC ---
  const leaderboard = useMemo(() => {
      const stats: Record<string, { name: string, total: number, count: number, comm: number }> = {};

      allSales.forEach(sale => {
          if (!stats[sale.agentId]) {
              stats[sale.agentId] = { name: sale.agentName, total: 0, count: 0, comm: 0 };
          }
          stats[sale.agentId].total += sale.amount;
          stats[sale.agentId].comm += (sale.commissionAmount || 0);
          stats[sale.agentId].count += 1;
      });
      return Object.values(stats).sort((a, b) => b.total - a.total);
  }, [allSales]);

  // Totals for the current view (History Tab)
  const viewTotals = visibleSales.reduce((acc, curr) => ({
      sales: acc.sales + curr.amount,
      comm: acc.comm + (curr.commissionAmount || 0)
  }), { sales: 0, comm: 0 });

  return (
    <div className="space-y-6 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4">
            <div>
                <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                    <div className="bg-emerald-100 text-emerald-600 p-2 rounded-lg"><IconTag className="w-6 h-6" /></div>
                    {t.title}
                </h2>
                <div className="flex items-center gap-2 mt-2">
                    <span className={`text-xs px-2 py-1 rounded border ${hasFullAccess ? 'bg-purple-50 text-purple-700 border-purple-200' : 'bg-gray-50 text-gray-600 border-gray-200'}`}>
                        {t.accessLevel}: {hasFullAccess ? t.managerView : t.expertView}
                    </span>
                </div>
            </div>
            <div className="flex gap-2">
                <div className="flex bg-gray-100 p-1 rounded-lg">
                    <button onClick={() => setActiveTab('leaderboard')} className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'leaderboard' ? 'bg-white shadow text-emerald-600' : 'text-gray-500'}`}><IconTrophy className="w-4 h-4" /> {t.leaderboard}</button>
                    <button onClick={() => setActiveTab('history')} className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'history' ? 'bg-white shadow text-emerald-600' : 'text-gray-500'}`}><IconCalendar className="w-4 h-4" /> {t.history}</button>
                </div>
                <button onClick={() => { resetForm(); setShowModal(true); }} className="bg-emerald-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-emerald-700 flex items-center gap-2 shadow-lg shadow-emerald-200">
                    <IconPlus className="w-5 h-5" /> {t.add}
                </button>
            </div>
        </div>

        {/* Stats Summary Cards */}
        {activeTab === 'history' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-5 shadow-sm">
                    <div className="text-emerald-800 text-sm font-bold mb-1 flex items-center gap-2"><IconMoney className="w-4 h-4" /> {hasFullAccess && agentFilter === 'all' ? t.totalSales : t.mySales}</div>
                    <div className="text-2xl font-black text-gray-800">{viewTotals.sales.toLocaleString()} <span className="text-xs font-medium text-gray-500">{t.rial}</span></div>
                </div>
                <div className="bg-indigo-50 border border-indigo-100 rounded-2xl p-5 shadow-sm">
                    <div className="text-indigo-800 text-sm font-bold mb-1 flex items-center gap-2"><IconChart className="w-4 h-4" /> {t.totalComm}</div>
                    <div className="text-2xl font-black text-gray-800">{viewTotals.comm.toLocaleString()} <span className="text-xs font-medium text-gray-500">{t.rial}</span></div>
                </div>
                <div className="bg-orange-50 border border-orange-100 rounded-2xl p-5 shadow-sm">
                    <div className="text-orange-800 text-sm font-bold mb-1 flex items-center gap-2"><IconBriefcase className="w-4 h-4" /> {t.count}</div>
                    <div className="text-2xl font-black text-gray-800">{visibleSales.length} <span className="text-xs font-medium text-gray-500">{t.count}</span></div>
                </div>
            </div>
        )}

        {activeTab === 'leaderboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Top 3 Cards */}
                {leaderboard.slice(0, 3).map((agent, index) => (
                    <div key={index} className={`relative overflow-hidden rounded-3xl p-6 shadow-lg border-2 ${index === 0 ? 'bg-gradient-to-br from-yellow-50 to-amber-100 border-amber-300' : index === 1 ? 'bg-gradient-to-br from-gray-50 to-gray-200 border-gray-300' : 'bg-gradient-to-br from-orange-50 to-orange-100 border-orange-200'}`}>
                        <div className="absolute top-0 right-0 p-4 opacity-20"><IconTrophy className={`w-24 h-24 ${index === 0 ? 'text-amber-500' : index === 1 ? 'text-gray-500' : 'text-orange-600'}`} /></div>
                        <div className="relative z-10 text-center">
                            <div className={`w-12 h-12 mx-auto rounded-full flex items-center justify-center text-xl font-bold mb-3 ${index === 0 ? 'bg-amber-400 text-white' : index === 1 ? 'bg-gray-400 text-white' : 'bg-orange-400 text-white'}`}>{index + 1}</div>
                            <h3 className="text-xl font-black text-gray-800 mb-1">{agent.name}</h3>
                            <div className="text-3xl font-black text-gray-900 my-4">{agent.total.toLocaleString()} <span className="text-sm text-gray-500 font-normal">{t.rial}</span></div>
                            <div className="flex justify-center gap-2">
                                <span className="inline-block bg-white/50 px-3 py-1 rounded-lg text-xs font-bold text-gray-700">{agent.count} {t.count}</span>
                                {/* Only show Commission total if User is Manager */}
                                {hasFullAccess && <span className="inline-block bg-green-100/80 px-3 py-1 rounded-lg text-xs font-bold text-green-800">Comm: {agent.comm.toLocaleString()}</span>}
                            </div>
                        </div>
                    </div>
                ))}

                {/* Rest of the list */}
                {leaderboard.length > 3 && (
                    <div className="col-span-full bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-50 text-gray-500">
                                <tr>
                                    <th className="px-4 py-3 text-start">{t.rank}</th>
                                    <th className="px-4 py-3 text-start">{t.agent}</th>
                                    <th className="px-4 py-3 text-center">{t.count}</th>
                                    <th className="px-4 py-3 text-end">{t.totalSales}</th>
                                    {hasFullAccess && <th className="px-4 py-3 text-end">{t.commAmount}</th>}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {leaderboard.slice(3).map((agent, idx) => (
                                    <tr key={idx}>
                                        <td className="px-4 py-3 font-bold text-gray-400">#{idx + 4}</td>
                                        <td className="px-4 py-3 font-bold text-gray-800">{agent.name}</td>
                                        <td className="px-4 py-3 text-center">{agent.count}</td>
                                        <td className="px-4 py-3 text-end font-mono font-bold text-gray-700">{agent.total.toLocaleString()}</td>
                                        {hasFullAccess && <td className="px-4 py-3 text-end font-mono text-green-600">{agent.comm.toLocaleString()}</td>}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {leaderboard.length === 0 && <div className="col-span-full text-center py-12 text-gray-400">{t.noSales}</div>}
            </div>
        )}

        {activeTab === 'history' && (
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                {hasFullAccess && (
                    <div className="p-4 border-b border-gray-100 bg-gray-50 flex items-center gap-3">
                        <IconSearch className="w-5 h-5 text-gray-400" />
                        <span className="text-sm font-bold text-gray-600">{t.filterAgent}</span>
                        <select 
                            className="bg-white border border-gray-300 text-gray-700 text-sm rounded-lg focus:ring-emerald-500 focus:border-emerald-500 block p-2 outline-none"
                            value={agentFilter}
                            onChange={(e) => setAgentFilter(e.target.value)}
                        >
                            <option value="all">{t.allAgents}</option>
                            {salesAgents.map(p => (
                                <option key={p.id} value={p.id}>{p.fullName}</option>
                            ))}
                        </select>
                    </div>
                )}

                <div className="overflow-x-auto">
                    <table className="w-full text-start text-sm">
                        <thead className="bg-gray-50 text-gray-500">
                            <tr>
                                <th className="px-6 py-4">{t.date}</th>
                                <th className="px-6 py-4">{t.agent}</th>
                                <th className="px-6 py-4">{t.customer}</th>
                                <th className="px-6 py-4">{t.service}</th>
                                <th className="px-6 py-4">{t.amount}</th>
                                <th className="px-6 py-4 text-center">{t.commPercent}</th>
                                {hasFullAccess && <th className="px-6 py-4 text-center">Action</th>}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {visibleSales.map((sale) => (
                                <tr key={sale.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 font-mono dir-ltr text-right text-gray-600">{new Date(sale.depositDate).toLocaleDateString('fa-IR')}</td>
                                    <td className="px-6 py-4 font-bold text-gray-800 flex items-center gap-2">
                                        <div className="w-6 h-6 bg-gray-200 rounded-full flex items-center justify-center text-[10px] text-gray-600">{sale.agentName.charAt(0)}</div>
                                        {sale.agentName}
                                    </td>
                                    <td className="px-6 py-4 text-gray-600">{sale.customerName || '-'}</td>
                                    <td className="px-6 py-4">
                                        {sale.serviceName ? (
                                            <span className="inline-flex items-center gap-1 bg-indigo-50 text-indigo-700 px-2 py-1 rounded text-xs font-bold border border-indigo-100">
                                                <IconBriefcase className="w-3 h-3" /> {sale.serviceName}
                                            </span>
                                        ) : '-'}
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="font-black text-emerald-600">{sale.amount.toLocaleString()} <span className="text-[10px] font-normal text-gray-400">{sale.currency}</span></div>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className="bg-orange-50 text-orange-700 px-2 py-1 rounded-lg text-xs font-bold">{sale.commissionPercentage}%</span>
                                        {/* Managers can see amount */}
                                        {(hasFullAccess || sale.agentId === currentUser.id) && sale.commissionAmount && (
                                            <div className="text-[10px] text-gray-400 mt-1">{sale.commissionAmount.toLocaleString()}</div>
                                        )}
                                    </td>
                                    {hasFullAccess && (
                                        <td className="px-6 py-4 text-center">
                                            <div className="flex justify-center gap-2">
                                                <button onClick={() => handleEdit(sale)} className="text-gray-400 hover:text-blue-600"><IconEdit className="w-4 h-4" /></button>
                                                <button onClick={() => handleDelete(sale.id)} className="text-gray-400 hover:text-red-600"><IconTrash className="w-4 h-4" /></button>
                                            </div>
                                        </td>
                                    )}
                                </tr>
                            ))}
                            {visibleSales.length === 0 && <tr><td colSpan={9} className="text-center py-8 text-gray-400">{t.noSales}</td></tr>}
                        </tbody>
                    </table>
                </div>
            </div>
        )}

        {/* Modal */}
        {showModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
                <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in flex flex-col max-h-[90vh]">
                    <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-emerald-50 rounded-t-2xl">
                        <h3 className="font-bold text-emerald-900">{isEditing ? t.edit : t.add}</h3>
                        <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600">✕</button>
                    </div>
                    <div className="overflow-y-auto p-6 flex-grow">
                        <form id="sales-form" onSubmit={handleSubmit} className="space-y-4">

                            {/* Agent Selection - Only for Managers/Admins */}
                            {hasFullAccess && (
                                <div className="bg-indigo-50 p-3 rounded-lg border border-indigo-100">
                                    <label className="block text-sm font-bold text-indigo-900 mb-1 flex items-center gap-2">
                                        <IconUsers className="w-4 h-4" /> {t.selectAgent}
                                    </label>
                                    <select 
                                        className="w-full px-3 py-2 border border-indigo-200 rounded-lg bg-white outline-none focus:ring-2 focus:ring-indigo-500"
                                        value={formData.agentId}
                                        onChange={(e) => handleAgentChange(e.target.value)}
                                    >
                                        {salesAgents.map(p => (
                                            <option key={p.id} value={p.id}>{p.fullName} ({p.roles.join(', ')})</option>
                                        ))}
                                    </select>
                                </div>
                            )}

                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">{t.selectService}</label>
                                <select 
                                    className="w-full px-3 py-2 border rounded-lg bg-white outline-none focus:ring-2 focus:ring-emerald-500"
                                    value={formData.serviceId}
                                    onChange={(e) => handleServiceChange(e.target.value)}
                                >
                                    <option value="">-- {t.service} --</option>
                                    {services.map(s => (
                                        <option key={s.id} value={s.id}>{s.title}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">{t.amount}</label>
                                    <input type="number" required className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.amount || ''} onChange={e => setFormData({...formData, amount: parseInt(e.target.value)})} />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">Currency</label>
                                    <select className="w-full px-3 py-2 border rounded-lg bg-white" value={formData.currency} onChange={e => setFormData({...formData, currency: e.target.value as any})}>
                                        <option value="IRR">IRR</option><option value="USD">USD</option><option value="OMR">OMR</option>
                                    </select>
                                </div>
                            </div>

                            {/* Commission Calculation Display - Editable ONLY for Managers */}
                            <div className="bg-orange-50 p-3 rounded-lg border border-orange-200 grid grid-cols-2 gap-4 text-sm relative">
                                {/* Mask for non-managers to prevent editing */}
                                {!hasFullAccess && <div className="absolute inset-0 bg-white/20 z-10 cursor-not-allowed" title="فقط مدیران امکان تغییر درصد را دارند" />}

                                <div className="text-orange-800 font-bold col-span-2 border-b border-orange-200 pb-1 mb-1 flex items-center gap-1">
                                    <IconBriefcase className="w-4 h-4" /> {t.commissionSection}
                                    {!hasFullAccess && <IconShield className="w-3 h-3 text-gray-400 ml-auto" />}
                                </div>
                                <div>
                                    <label className="block text-xs text-orange-600 mb-1">{t.commPercent}</label>
                                    <div className="relative">
                                        <input 
                                            type="number" 
                                            className="w-full px-2 py-1 rounded border border-orange-300 font-bold text-gray-800 text-center focus:ring-2 focus:ring-orange-500 outline-none disabled:bg-gray-100 disabled:text-gray-500"
                                            value={formData.commissionPercentage}
                                            onChange={(e) => setFormData({...formData, commissionPercentage: parseFloat(e.target.value)})}
                                            disabled={!hasFullAccess}
                                        />
                                        <span className="absolute left-2 top-1.5 text-xs text-gray-400">%</span>
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs text-orange-600 mb-1">{t.commAmount}</label>
                                    <div className="font-bold text-emerald-600 bg-white px-2 py-1.5 rounded border border-orange-200 text-center">
                                        {formData.commissionAmount?.toLocaleString()}
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">{t.date}</label>
                                    <input type="date" required className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.depositDate} onChange={e => setFormData({...formData, depositDate: e.target.value})} />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-gray-700 mb-1">{t.customer}</label>
                                    <input className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.customerName} onChange={e => setFormData({...formData, customerName: e.target.value})} placeholder="Optional" />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">{t.account}</label>
                                <input required className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" value={formData.targetAccount} onChange={e => setFormData({...formData, targetAccount: e.target.value})} placeholder="Card No / IBAN / Bank Name" />
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-gray-700 mb-1">{t.desc}</label>
                                <textarea className="w-full px-3 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-emerald-500" rows={2} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                            </div>
                        </form>
                    </div>
                    <div className="p-4 border-t border-gray-100 flex justify-end gap-3 bg-gray-50 rounded-b-2xl">
                        <button onClick={() => setShowModal(false)} className="px-4 py-2 text-gray-600 font-bold hover:bg-gray-200 rounded-lg transition-colors">{t.cancel}</button>
                        <button type="submit" form="sales-form" className="bg-emerald-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-emerald-700 shadow-lg shadow-emerald-200">{t.save}</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

